comms.text:
@1 אֲרֵי תִפּוֹק לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבָךְ וְיִמְסְרִנוּן יְיָ אֱלָהָךְ בִּידָךְ וְתִשְׁבֵּי שִׁבְיְהוֹן:
@2 וְתֶחֱזֵי בְּשִׁבְיָה אִתְּתָא שַׁפִּירַת חֵזוּ וְתִתִּרְעֵי בַהּ וְתִסְבַהּ לָךְ לְאִנְתּוּ:
@3 וְתָעֵלִנַהּ לְגוֹ בֵיתָךְ וּתְגַלַח יָת רֵישַׁהּ וּתְרַבִּי יָת טוּפְרָנָהָא:
@4 וְתֶעְדֵי יָת כְּסוּת שִׁבְיַהּ מִנַהּ וְתֵיתַב בְּבֵיתָךְ וְתִבְכֵּי יָת אֲבוּהָא וְיָת אִמַהּ יְרַח יוֹמִין וּבָתַר כֵּן תֵּיעוּל לְוָתַהּ וְתִבְעֲלִנַהּ וּתְהֵי לָךְ לְאִנְתּוּ:
@5 וִיהֵי אִם לָא תִתִּרְעֵי בַהּ וְתִפְטְּרִנַהּ לְנַפְשַׁהּ וְזַבָּנָא לָא תְזַבְּנִנַהּ בְּכַסְפָּא לָא תִתָּגַר בַּהּ חֳלַף דִי עִינִיתַהּ:
@6 אֲרֵי תְהֶוְיָן לִגְבַר תַּרְתֵּין נְשִׁין חֲדָא רְחֶמְתָּא וַחֲדָא שְׂנִיאֲתָא וִילִידָן לֵהּ בְּנִין רְחֶמְתָּא וּשְׂנִיאֲתָא וִיהֵי בְּרָא בוּכְרָא לִשְׂנִיאֲתָא:
@7 וִיהֵי בְּיוֹמָא דְיַחְסֵן לִבְנוֹהִי יָת דִי יְהֵי לֵהּ לֵית לֵהּ רְשׁוּ לְבַכָּרָא יָת בַּר רְחֶמְתָּא עַל אַפֵּי בַר שְׂנִיאֲתָא בּוּכְרָא:
@8 אֲרֵי יָת בּוּכְרָא בַר שְׂנִיאֲתָא יַפְרַשׁ לְמִתַּן לֵהּ תַּרְתֵּין חָלָקִין בְּכֹל דִי יִשְׁתְּכַח לֵהּ אֲרֵי הוּא רֵישׁ תָּקְפֵּהּ לֵהּ חָזְיָא בְכֵרוּתָא:
@9 אֲרֵי יְהֵי לִגְבַר בַּר סָטֵי וּמָרֵי לֵיתוֹהִי מְקַבַּל לְמֵימַר אֲבוּהִי וּלְמֵימַר אִמֵהּ וּמַלְפָן יָתֵהּ וְלָא יְקַבֵּל מִנְהוֹן:
@10 וְיֶחֱדוּן בֵּהּ אֲבוּהִי וְאִמֵּהּ וְיַפְּקוּן יָתֵהּ לָקֳדָם סָבֵי קַרְתֵּהּ וְלִתְרַע בֵּית דִין אַתְרֵהּ:
@11 וְיֵימְרוּן לְסָבֵי קַרְתֵּהּ בְּנָנָא דֵין סָטֵי וּמָרֵי לֵיתוֹהִי מְקַבֵּל לְמֵימְרָנָא זָלֵל בְּסָר וְסָבֵי חֲמַר:
@12 וְיִרְגְמֻנֵהּ כָּל אֶנָשֵׁי קַרְתֵּהּ בְּאַבְנַיָא וִימוּת וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ וְכָל יִשְׂרָאֵל יִשְׁמְעוּן וְיִדְחֲלוּן:
@13 וַאֲרֵי יְהֵי בִגְבַר חוֹבַת דִין דִקְטוֹל וְיִתְקְטֵל וְתִצְלוֹב יָתֵהּ עַל צְלִיבָא:
@14 לָא תְבִית נְבִלְתֵּהּ עַל צְלִיבָא אֲרֵי מִקְבַּר תִּקְבְּרִנֵהּ בְּיוֹמָא הַהוּא אֲרֵי עַל דְחָב קֳדָם יְיָ אִצְטְלַב וְלָא תְסָאֵב יָת אַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא:
@15 לָא תֶחֱזֵי יָת תּוֹרָא דְאָחוּךְ אוֹ יַת אִמְרֵהּ דְטָעָן וְתִתְכְּבֵשׁ מִנְהוֹן אָתָבָא תָתֵבִנוּן לְאָחוּךְ:
@16 וְאִם לָא קָרֵב אֲחוּךְ לְוָתָךְ וְלָא יְדַעַתְּ לֵהּ וְתַכְנְשִׁנֵהּ לְגוֹ בֵיתָךְ וִיהֵי עִמָךְ עַד דְיִתְבַּע אֲחוּךְ יָתֵהּ וְתָתֵיבִנֵהּ לֵהּ:
@17 וְכֵן תַּעְבֵּד לַחֲמָרֵהּ וְכֵן תַּעְבֵּד לִכְסוּתֵהּ וְכֵן תַּעְבֵּד לְכָל אֲבֵדַת אֲחוּךְ דִי תֵיבַד מִנֵהּ וְתַשְׁכְּחִנַהּ לֵית לָךְ רְשׁוּ לְאִתְכַּסָאָה:
@18 לָא תֶחֱזֵי יָת חֲמָרָא דְאָחוּךְ אוֹ תוֹרֵהּ רָמָן בְּאָרְחָא וְתִתְכְּבֵשׁ מִנְהוֹן אֲקָמָא תְקִים עִמֵהּ:
@19 לָא יְהֵי תִקוּן זֵין דִגְבַר עַל אִתְּתָא וְלָא יְתַקֵן גְבַר בְּתִקוּנֵי אִתְּתָא אֲרֵי מְרָחָק קֳדָם יְיָ אֱלָהָךְ כָּל עָבֵד אִלֵין:
@20 אֲרֵי יְעָרַע קִנָא דְצִפְּרָא קֳדָמָךְ בְּאָרְחָא בְּכָל אִילָן אוֹ עַל אַרְעָא אֶפְרוֹחִין אוֹ בֵיעִין וְאִמָא רְבֵעָא עַל אֶפְרֹחִין אוֹ עַל בֵּיעִין לָא תִסַב אִמָא עַל בְּנַיָא:
@21 שַׁלָחָא תְשַׁלַח יָת אִמָא וְיָת בְּנַיָא תִּסַב לָךְ בְּדִיל דְיֵיטַב לָךְ וְתוֹרִיפךְ יוֹמִין:
@22 אֲרֵי תִבְנֵי בֵּיתָא חַדְתָּא וְתַעְבֵּד תְּיָקָא לְאִגְרָךְ וְלָא תְשַׁוִי חוֹבַת דִין דִקְטוֹל בְּבֵיתָךְ אֲרֵי יִפֵּל דְנָפֵל מִנֵהּ:
@23 לָא תִזְרַע כַּרְמָךְ עֵרוּבִין דִילְמָא תִסְתָּאַב דִמְעַת זַרְעָא דִי תִזְרַע וַעֲלָלַת כַּרְמָא:
@24 לָא תִרְדֵי בְתוֹרָא וּבַחֲמָרָא כַּחֲדָא:
@25 לָא תִלְבַּשּׁ שַׁעַטְנֵזָא עֲמַר וְכִתָּן מְחֻבַּר כַּחֲדָא:
@26 כְּרֻסְפְּדִין תַּעְבֶּד לָךְ עַל אַרְבַּע כַּנְפֵי כְסוּתָךְ דִי תְכַסֵי בַהּ:
@27 אֲרֵי יִסַב גְבַר אִתְּתָא וְיֵעוּל לְוָתַהּ וְיִסְנִנַהּ:
@28 וִישַׁוִי לַהּ תַּסְקוֹפֵי מִלִין וְיַפֵּק עֲלַהּ שׁוּם בִּישׁ וְיֵימַר יָת אִתְּתָא הָדָא נְסֵבִית וְעַלִית לְוָתַהּ וְלָא אַשְׁכָּחִית לַהּ בְּתוּלִין:
@29 וְיִסַב אֲבוּהָא (נ''א אֲבוּהִי) דְעוּלֶמְתָּא וְאִמַהּ וְיַפְּקוּן יָת בְּתוּלֵי עוּלֶמְתָּא לָקֳדָם סָבֵי קַרְתָּא לִתְרַע בֵּית דִין אַתְרָא:
@30 וְיֵימַר אֲבוּהָא דְעוּלֶמְתָּא לְסָבַיָא יָת בְּרַתִּי יְהָבִית לְגַבְרָא הָדֵין לְאִנְתּוּ וּסְנִנַהּ:
@31 וְהָא הוּא שַׁוִי תַּסְקוֹפֵי מִלִין לְמֵימַר לָא אַשְׁכָּחִית לִבְרַתָּךְ בְּתוּלִין וְאִלֵין בְּתוּלֵי בְרַתִּי וְיִפְרְסוּן שׁוֹשִׁיפָא קֳדָם סָבֵי קַרְתָּא:
@32 וְיִדְבְּרוּן סָבֵי קַרְתָּא הַהִיא יָת גַבְרָא וְיַלְקוּן יָתֵהּ:
@33 וְיִגְבּוּן מִנֵהּ מְאָה סִלְעִין דִכְסָף וְיִתְּנוּן לַאֲבוּהָא דְעוּלֶמְתָּא אֲרֵי אַפֵּק שׁוּם בִּישׁ עַל בְּתוּלְתָּא דְיִשְׂרָאֵל וְלֵהּ תְּהֵי לְאִנְתּוּ לֵית לֵהּ רְשׁוּ לְמִפְטְּרַהּ כָּל יוֹמוֹהִי:
@34 וְאִם קֻשְׁטָא הֲוָה פִּתְגָמָא הָדֵין לָא אִשְׁתְּכָחוּ בְתוּלִין לְעוּלֶמְתָּא:
@35 וְיַפְּקוּן יָת עוּלֶמְתָּא לִתְרַע בֵּית אָבוּהָא וְיִרְגְמֻנַהּ אֱנָשֵׁי קַרְתַּהּ בְּאַבְנַיָא וּתְמוּת אֲרֵי עָבְדַת קְלָנָא בְּיִשְׂרָאֵל לְזַנָאָה בֵּית אֲבוּהָא וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@36 אֲרֵי יִשְׁתְּכַח גְבַר דְשָׁכֵב עִם אִתְּתָא אִתַּת גְבַר וְיִתְקַטְלוּן אַף תַּרְוֵיהוֹן גַבְרָא דְשָׁכֵב עִם אִתְּתָא וְאִתְּתָא וּתְפַלֵי עָבֵד דְבִישׁ מִיִשְׂרָאֵל:
@37 אֲרֵי תְהֵי עוּלֶמְתָּא בְתֻלְתָּא דִמְאָרְסָא לִגְבַר וְיַשְׁכְּחִנַהּ גְבַר בְּקַרְתָּא וְיִשְׁכּוּב עִמַהּ:
@38 וְתַפְּקוּן יָת תַּרְוֵיהוֹן לִתְרַע קַרְתָּא הַהִיא וְתִרְגְמוּן יָתְהוֹן בְּאַבְנַיָא וִימוּתוּן יָת עוּלֶמְתָּא עַל עֵסַק דִי לָא צְוָחַת בְּקַרְתָּא וְיָת גַבְרָא עַל עֵסַק דְעַנִי יָת אִתַּת חַבְרֵהּ וּתְפַלֵי עָבֵד דְבִּישׁ מִבֵּינָךְ:
@39 וְאִם בְּחַקְלָא יַשְׁכַּח גְבַר יָת עוּלֶמְתָּא דִמְאָרְסָא וְיִתְקֶף בַּהּ גַבְרָא וְיִשְׁכּוּב עִמַהּ וְיִתְקְטֵּל גַבְרָא דְשָׁכֵב עִמַהּ בִּלְחוֹדוֹהִי:
@40 וּלְעוּלֶמְתָּא לָא תַעְבֵּד מִדַעַם לֵית לְעוּלֶמְתָּא חוֹבַת דִין דִקְטוֹל אֲרֵי כְּמָא דִיקוּם גַבְרָא עַל חַבְרֵהּ וְיִקְטְּלִנֵהּ נְפַשׁ כֵּן פִּתְגָמָא הָדֵין:
@41 אֲרֵי בְחַקְלָא אַשְׁכְּחַהּ צְוָחַת עוּלֶמְתָּא דִמְאָרְסָא וְלֵית דְפָרִיק לַהּ:
@42 אֲרֵי יַשְׁכַּח גְבַר עוּלֶמְתָּא בְתֻלְתָּא דִי לָא מְאָרְסָא וְיֶחֱדִנַהּ וְיִשְׁכּוּב עִמַהּ וְיִשְׁתַּכְּחוּן:
@43 וְיִתֵּן גַבְרָא דְיִשְׁכֻּב עִמַהּ לַאֲבוּהָא דְעוּלֶמְתָּא חַמְשִׁין סִלְעִין דִכְסַף וְלֵהּ תְּהֵי לְאִנְתּוּ חֳלַף דִי עַנְיַהּ לֵית לֵהּ רְשׁוּ לְמִפְטְרַהּ כָּל יוֹמוֹהִי:
@44 לָא יִסַב גְבַר יָת אִתַּת אֲבוּהִי וְלָא יְגַלֵי כַּנְפָא דַאֲבוּהִי:
@45 לָא יִדְכֵּי דְפָסִיק וְדִמְחַבַּל לְמֵעַל בִּקְהָלָא דַיְיָ:
@46 לָא יִדְכֵּי מַמְזֵרָא לְמֵעַל בִּקְהָלָא דַיְיָ אַף דָרָא עֲשִׂירָאָה לָא יִדְכֵּי לֵהּ לְמֵעַל בִּקְהָלָא דַיְיָ:
@47 לָא יִדְכּוּן עַמוֹנָאֵי וּמוֹאָבָאֵי לְמֵעַל בִּקְהָלָא דַיְיָ אַף דָרָא עֲשִׂירָאָה לָא יִדְכֵּי לְהוֹן לְמֵעַל בִּקְהָלָא דַיְיָ עַד עָלָם:
@48 עַל עֵסַק דִי לָא עֲרָעוּ יָתְכוֹן בְּלַחְמָא וּבְמַיָא בְּאָרְחָא בְּמִפָּקְכוֹן מִמִצְרָיִם וְדִי אֲגַר עֲלָךְ יָת בִּלְעָם בַּר בְּעוֹר מִפְּתוֹר אֲרַם דִי עַל פְּרָת לְלַטָּיוּתָךְ:
@49 וְלָא אָבֵי יְיָ אֱלָהָךְ לְקַבָּלָא מִן בִּלְעָם וַהֲפַךְ יְיָ אֱלָהָךְ לָךְ יָת לְוָטִין לְבִרְכָן אֲרֵי רָחֲמָךְ יְיָ אֱלָהָךְ:
@50 לָא תִתְבַּע שְׁלָמְהוֹן וְטָבָתְהוֹן כָּל יוֹמָיךְ לְעָלָם:
@51 לָא תְרַחַק אֱדוֹמָאָה אֲרֵי אֲחוּךְ הוּא לָּא תְרַחַק מִצְרָאָה אֲרֵי דַיָר הֲוֵיתָא בְאַרְעֵהּ:
@52 בְּנִין דִי יִתְיְלִידוּ לְהוֹן דָרָא תְלִיתָאָה יִדְכֵּי לְהוֹן לְמֵעַל בִּקְהָלָה דַיְיָ:
@53 אֲרֵי תִפּוֹק מַשְׁרִיתָא עַל בַּעֲלֵי דְבָבָךְ וְתִסְתַּמַר מִכֹּל מִדַעַם בִּישׁ:
@54 אֲרֵי יְהֵי בָךְ גְבַר דִי לָא יְהֵּי דְכֵי מִקְרֵהּ לֵילְיָא וְיִפּוֹק לְמִבָּרָא לְמַשְׁרִיתָא לָא יֵעוּל לְגוֹ מַשְׁרִיתָא:
@55 וִיהֵי לְמִפְנֵי רַמְשָׁא יַסְחֵי בְמַיָא וּכְמֵעַל שִׁמְשָׁא יֵעוּל לְגוֹ מַשְׁרִיתָא:
@56 וַאֲתַר מְתַקֵן יְהֵי לָךְ מִבָּרָא לְמַשְׁרִיתָא וְתִפּוֹק תַּמָן לְבָרָא:
@57 וְסִכְּתָא תְּהֵי לָךְ עַל זֵינָךְ וִיהֵי בְּמִיתְבָךְ לְבָרָא וְתַחְפַּר בַּהּ וּתְתוּב וּתְכַסֵי יָת מִפְּקָתָךְ:
@58 אֲרֵי יְיָ אֱלָהָךְ שְׁכִינְתֵּהּ מְהַלְכָא בְּגוֹ מַשְׁרִיתָךְ לְשֵׁזָבוּתָךְ וּלְמִמְסַר בַּעֲלֵי דְבָבָךְ קֳדָמָךְ וּתְהֵי מַשְׁרִיתָךְ קַדִישָׁא וִלָא יִתְחֲזֵי בָךְ עֲבֵרַת פִּתְגָם וִיתוּב מֵימְרֵהּ מִלְאוֹטָבָא לָךְ:
@59 לָא תִמְסַר עֶבֶד עַמְמִין לְיַד רִבּוֹנֵהּ דְיִשְׁתֵּזֵב לְוָתָךְ מִלְוָת רִבּוֹנֵהּ:
@60 עִמָךְ יִתֵּב בֵּינָךְ בְּאַתְרָא דִי יִתִּרְעֵי בַּחֲדָא מִן קִרְוָיךְ בִּדְיֵיטַּב לֵהּ לָא תוֹנִנֵהּ:
@61 לָא תְהֵי אִתְּתָא מִבְּנַת יִשְׂרָאֵל לִגְבָר עָבֵד וְלָא יִסַב גַבְרָא מִבְּנֵי יִשְׂרָאֵל אִתְּתָא אָמָא:
@62 לָא תָעֵל אֲגַר זַנִיתָא וְחוּלְפַן כַּלְבָא לְבֵית מַקְדְשָׁא דַיְיָ אֱלָהָךְ לְכָל נִדְרָא אֲרֵי מְרָחָק קֳדָם יְיָ אֱלָהָךְ אַף תַּרְוֵיהוֹן:
@63 לָא תְרַבֵּי לַאֲחוּךְ רִבִּית כְּסַף רִבִּית עִבוּר רִבִּית כָּל מִדַעַם דְמִתְרַבֵּי:
@64 לְבַר עַמְמִין תְּרַבֵּי וְלַאֲחוּךְ לָא תְרַבֵּי בְּדִיל דִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכֹל אוֹשָׁטוּת יְדָךְ עַל אַרְעָא דִי אַתְּ עָלֵל:לתַמָן לְמֵירְתַהּ:
@65 אֲרֵי תִדַר נְדַר קֳדָם יְיָ אֱלָהָךְ לָא תְאַחַר לְשַׁלָמוּתֵהּ אֲרֵי מִתְבַּע יִתְבְּעִנֵהּ יְיָ אֱלָהָךְ מִנָךְ וִיהֵי בָךְ חוֹבָא:
@66 וַאֲרֵי תִתִּמְנַע לְמִנְדַר לָא יְהֵי בָךְ חוֹבָא:
@67 אַפָּקוּת סִפְוָתָךְ תִּטַר וְתַעְבֵּד כְּמָא דִי נְדַרְתָּא קֳדָם יְיָ אֱלָהָךְ נְדַבְתָּא דִי מַלֶלְתָּא בְּפוּמָךְ:
@68 אֲרֵי תִתָּגַר בְּכַרְמָא דְחַבְרָךְ וְתֵיכוּל עִנְבִין כְּנַפְשָׁךְ שִׂבְעָךְ וּלְמָאנָךְ לָא תִתֵּן:
@69 אֲרֵי תִתָּגַר בְּקַמְתָא דְחַבְרָךְ וְתִקְטוֹף מְלִילָן בִּידָךְ וּמַגְלָא לָא תְרִים עַל קַמְתָא דְחַבְרָךְ:
@70 אֲרֵי יִסַב גְבַר אִתְּתָא וְיִבְעֲלִנַהּ וִיהֵי אִם לָא תַשְׁכַּח רַחֲמִין בְּעֵינוֹהִי אֲרֵי אַשְׁכַּח בַּהּ עֲבֵרַת פִתְגָם וְיִכְתּוֹב לַהּ גֵט פִּטוּרִין וִיהַב בִּידַהּ וְיִפְטְּרִנַהּ מִבֵּיתֵהּ:
@71 וְתִפּוֹק מִבֵּיתֵהּ וּתְהַךְ וּתְהֵי לִגְבַר אָחֳרָן:
@72 וְיִסְנִנַהּ גַבְרָא בַתְרָאָה וְיִכְתּוֹב לַהּ גֵטּ פִטּוּרִין וְיִתֵּן בִּידַהּ וְיִפְטְרִנַהּ מִבֵּיתֵהּ אוֹ אֲרֵי יְמוּת גַבְרָא בַתְרָאָה דְנָסְבַהּ לֵה לְאִנְתּוּ:
@73 לֵית לֵהּ רְשׁוּ לְבַעֲלַהּ קַדְמָאָה דִי פָטְרַהּ לְמִתֻּב לְמִסְבַהּ לְמֶהֱוֵי לֵה לְאִנְתּוּ בָּתַר דִי אִסְתָּאָבַת אֲרֵי מְרָחָקָא הִיא קֳדָם יְיָ וְלָא תְחַיַב יָת אַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא:
@74 אֲרֵי יִסַב גְבַר אִתְּתָא חַדְתָּא לָא יִפּוֹק בְּחֵילָא וְלָא יֵעִבַר עֲלוֹהִי לְכָל מִדָעַם פָּנֵי יְהֵי לְבֵיתֵהּ שַׁתָּא חֲדָא וְיַחְדֵי יָת אִתְּתֵהּ דִי נְסַב:
@75 לָא יִסַב מַשְׁכּוֹנָא רֵחַיָא וְרִכְבָּא אֲרֵי בְהוֹן מִתְעֲבֵד מָזוֹן לְכָל נְפַשׁ:
@76 אֲרֵי יִשְׁתְּכַח גְבַר גָנֵב נַפְשָׁא מֵאֲחוֹהִי מִבְּנֵי יִשְׂרָאֵל וְיִתָּגַר בֵּהּ וִיזַבְּנִנֵהּ וְיִתְקְטֵל גַנָבָא הַהוּא וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@77 אִסְתַּמַר בְּמַכְתַּשׁ סְגִירוּ לְמִטַּר לַחֲדָא וּלְמֶעְבָּד כְּכֹל דִי יַלְפוּן יָתְכוֹן כָּהֲנַיָא לֵוָאֵי כְּמָא דִי פַקֶדְתִּנוּן תִּטְרוּן לְמֶעְבָּד:
@78 הֱוֵי דְכִיר יָת דִי עֲבַד יְיָ אֱלָהָךְ לְמִרְיָם בְּאָרְחָא בְּמִפָקְכוֹן מִמִצְרָיִם:
@79 אֲרֵי תַרְשֵׁי בְחַבְרָךְ רְשׁוּ מִדָעַם לָא תֵעוּל לְבֵיתֵהּ לְמִסַב מַשְׁכּוֹנֵהּ:
@80 בְּבָרָא תְּקוּם וְגַבְרָא דִי אַתְּ רָשֵׁי בֵהּ יַפֵק לְוָתָךְ יָת מַשְׁכּוֹנָא לְבָרָא:
@81 וְאִם גְבַר מִסְכֵּן הוּא לָא תִשְׁכּוּב בְּמַשְׁכּוֹנֵהּ:
@82 אָתָבָא תָתֵב לֵהּ יָת מַשְׁכּוֹנָא כְּמֵעַל שִׁמְשָׁא וְיִשְׁכּוּב בִּכְסוּתֵהּ וִיבָרֵכִנָךְ וְלָךְ תְּהֵי זְכוּתָא קֳדָם יְיָ אֱלָהָךְ:
@83 לָא תַעֲשׁוֹק אֲגִירָא עַנְיָא וּמִסְכֵּנָא מֵאַחָיךְ אוֹ מִגִיוֹרָךְ דִי בְאַרְעָךְ בְּקִרְוָיךְ:
@84 בְּיוֹמֵהּ תִּתֵּן אַגְרֵהּ וְלָא תֵעוּל עֲלוֹהִי שִׁמְשָׁא אֲרֵי עַנְיָא הוּא וְלֵהּ הוּא מְסַר יָת נַפְשֵׁהּ וְלָא יִקְרֵי עֲלָךְ קֳדָם יְיָ וִיהֵי בָךְ חוֹבָא:
@85 לָא יְמוּתוּן אֲבָהָן עַל פּוּם בְּנִין וּבְנִין לָא יְמוּתוּן עַל פּוּם אֲבָהָן אֱנַשׁ בְּחוֹבֵהּ יְמוּתוּן:
@86 לָא תַצְלֵי דִין גִיוֹרָא וְיִתַּמָא וְלָא תִסַב מַשְׁכּוֹנָא לְבוּשׁ אַרְמְלָא:
@87 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּמִצְרַיִם וּפָרְקָךְ יְיָ אֱלָהָךְ מִתַּמָן עַל כֵּן אֲנָא מְפַקְדָךְ לְמֶעְבַּד יָת פִּתְגָמָא הָדֵין:
@88 אֲרֵי תַחְצוֹד חֲצָדָךְ בְּחַקְלָךְ וְתִנְשֵׁי עֻמְרָא בְחַקְלָא לָא תְתוּב לְמִסְבֵהּ לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא יְהֵי בְּדִיל דִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכֹל עוֹבָדֵי יְדָךְ:
@89 אֲרֵי תַחְבּוֹט זֵיתָךְ לָא תְפַלֵי בַּתְרָךְ לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא יְהֵי:
@90 אֲרֵי תִקְטוֹף כַּרְמָךְ לָא תְעָלֵל בַּתְרָךְ לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא יְהֵי:
@91 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּאַרְעָא דְמִצְרָיִם עַל כֵּן אֲנָא מְפַקְדָךְ לְמֵעְבַּד יָת פִּתְגָמָא הָדֵין:
@92 אֲרֵי יְהֵי דִין בֵּין גֻבְרַיָא וְיִתְקָרְבוּן לְדִינָא וִידוּנֻנוּן וִיזַכּוּן יָת זַכָּאָה וִיחַיְבוּן יָת חַיָבָא:
@93 וִיהֵי אִם בַּר חַיָבָא לְאַלְקָאָה חַיָבָא וְיִרְמִנֵהּ דַיָנָא וְיַלְקִנֵהּ קֳדָמוֹהִי כְּמִסַת חוֹבְתֵהּ בְּמִנְיָן:
@94 אַרְבְּעִין יַלְקִנֵהּ לָא יוֹסֵף דִילְמָא יוֹסֵף לְאַלְקָיוּתֵהּ עַל אִלֵין מָחָא רַבָּא וְיֵקַל אֲחוּךְ לְעֵינָיךְ:
@95 לָא תֵחוֹד פּוּם תּוֹרָא בִּדְיָשֵׁהּ:
@96 אֲרֵי יֵתְבוּן אַחִין כַּחֲדָא וִימוּת חַד מִנְהוֹן וּבַר לֵית לֵהּ לָא תְהֵי אִתַּת מֵתָנָא לְבָרָא לִגְבַר אוֹחֲרָן יְבָמַהּ יֵעוּל עֲלַהּ וְיִסְבַהּ לֵהּ לְאִנְתּוּ וְיִבְּמַהּ:
@97 וִיהֵי בּוּכְרָא דִי תְלִיד יְקוּם עַל שְׁמָא דַאֲחוּהִי מֵתָנָא וְלָא יִתִּמְחֵי שְׁמֵהּ מִיִשְׂרָאֵל:
@98 וְאִם לָא יִצְבֵי גַבְרָא לְמִסַב יָת יְבִמְתֵּהּ וְתִסַק יְבִמְתֵהּ לִתְרַע בֵּית דִינָא לָקֳדָם סָבַיָא וְתֵימַר לָא צָבֵי יְבָמִי לַאֲקָמָא לַאֲחוּהִי שְׁמָא בְּיִשְׂרָאֵל לָא אָבֵי לְיַבָּמוּתִי:
@99 וִיקְרוּן לֵהּ סָבֵי קַרְתֵּהּ וִימַלְלוּן עִמֵהּ וִיקוּם וְיֵימַר לָא רְעֵנָא לְמִסְבַהּ:
@100 וְתִתְקְרַב יְבִמְתֵּהּ לְוָתֵה לָקֳדָם סָבַיָא וְתַשְׁרֵי סֵינֵהּ מֵעַל רַגְלֵהּ וְתֵרוֹק בְּאַנְפּוֹהִי וְתָתֵב וְתֵימַר כְּדֵין יִתְעֲבֵד לִגְבַר דִי לָא יִבְנֵי יָת בֵּיתָא דַאֲחוּהִי:
@101 וְיִתְקְרֵי שְׁמֵהּ בְּיִשְׂרָאֵל בֵּית שְׁרִי סֵינָא:
@102 אֲרֵי יִנְצוּן גֻבְרִין כַּחֲדָא גְבַר וַאֲחוּהִי וְתִתְקְרֵב אִתַּת חַד לְשֵׁזָבָא יָת בַּעֲלַהּ מִיַד מָחוּהִי וְתוֹשֵׁט יְדַהּ וְתִתְקֵף בְּבֵית בַּהֲתְּתֵהּ:
@103 וּתְקוּץ יָת יְדַהּ לָא תְחוּס עֵינָךְ:
@104 לָא יְהֵי לָךְ בְּכִיסָךְ מַתְקַל וּמַתְקָל רַבְּתָא וּזְעֶרְתָּא:
@105 לָא יְהֵי לָךְ בְּבֵיתָךְ מְכִילָא וּמְכִילָא רַבְּתָא וּזְעֶרְתָּא:
@106 מַתְקִלִין שָׁלְמִין דִקְשׁוֹט יְהוֹן לָךְ מְכִילָן שָׁלְמִין דִקְשׁוֹט יְהוֹן לָךְ בְּדִיל דְיוֹרְכוּן יוֹמָיךְ עַל אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@107 אֲרֵי מְרָחָק קֳדָם יְיָ אֱלהָךְ כָּל עָבֵד אִלֵין כֹּל עָבֵד שְׁקַר:
@108 הֲוֵי דְכִיר יָת דִי עֲבַד לָךְ עֲמָלֵק בְּאָרְחָא בְּמִפָּקְכוֹן מִמִצְרָיִם:
@109 דִי עָרְעָךְ בְּאָרְחָא וְקָטֵל בָּךְ כָּל דַהֲווֹ מִתְאַחֲרִין בַּתְרָךְ וְאַתְּ מְשַׁלְהֵי וְלָאֵי וְלָא דָחֵיל מִן קֳדָם יְיָ:
@110 וִיהֵי כַּד יְנִיחַ יְיָ אֱלָהָךְ לָךְ מִכָּל בַּעֲלֵי דְבָבָךְ מִסְחוֹר סְחוֹר בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא לְמֵירְתַהּ תִּמְחֵי יָת דוּכְרָנָא דַעֲמָלֵק מִתְּחוֹת שְׁמַיָא לָא תִּתִּנְשֵׁי: פפפ:

@1 **כי תצא למלחמה.** במלחמת הרשות הכתוב מדבר, שבמלחמת ארץ ישראל אין לומר ושבית שביו, שהרי כבר נאמר (לעיל כ, טז) לא תחיה כל נשמה: **ושבית שביו.** לרבות כנענים שבתוכה ואף על פי שהם משבעה אמות:
@2 **אשת.** אפלו אשת איש: **ולקחת לך לאשה.** לא דברה תורה אלא כנגד יצר הרע. שאם אין הקדוש ברוך הוא מתירה, ישאנה באסור. אבל אם נשאה, סופו להיות שונאה, שנאמר אחריו (פסוק טו) כי תהיין לאיש וגו' וסופו להוליד ממנה בן סורר ומורה, לכך נסמכו פרשיות הללו:
@3 **ועשתה את צפרניה.** תגדלם כדי שתתנול:
@4 **והסירה את שמלת שביה.** לפי שהם נאים, שהגוים בנותיהם מתקשטות במלחמה בשביל להזנות אחרים עמהם: **וישבה בביתך.** בבית שמשתמש בו, נכנס ונתקל בה, יוצא ונתקל בה, רואה בבכייתה, רואה בנוולה, כדי שתתגנה עליו: **ובכתה את אביה.** כל כך למה, כדי שתהא בת ישראל שמחה וזו עצבה, בת ישראל מתקשטת וזו מתנולת:
@5 **והיה אם לא חפצת בה.** הכתוב מבשרך שסופך לשנאותה: **לא תתעמר בה.** לא תשתמש בה, בלשון פרסי קורין לעבדות ושמוש, עימראה. מיסודו של רבי משה הדרשן למדתי כן:
@8 **פי שנים.** כנגד שני אחים: **בכל אשר ימצא לו.** מכאן שאין הבכור נוטל פי שנים בראוי לבא לאחר מיתת האב, כבמחזק:
@9 **סורר.** סר מן הדרך: **ומורה.** מסרב בדברי אביו, לשון ממרים: **ויסרו אותו.** מתרין בו בפני שלשה ומלקין אותו. בן סורר ומורה אינו חיב, עד שיגנוב ויאכל תרטימר בשר וישתה חצי לוג יין. שנאמר (פסוק כ) זולל וסבא, ונאמר (משלי כג, כ) אל תהי בסובאי יין בזוללי בשר למו. ובן סורר ומורה נהרג על שם סופו, הגיעה תורה לסוף דעתו, סוף שמכלה ממון אביו ומבקש למודו ואינו מוצא, ועומד בפרשת דרכים ומלסטם את הבריות, אמרה תורה ימות זכאי ואל ימות חיב:
@12 **וכל ישראל ישמעו ויראו.** מכאן שצריך הכרזה בבית דין, פלוני נסקל על שהיה בן סורר ומורה:
@13 **וכי יהיה באיש חטא משפט מות.** סמיכות הפרשיות מגיד, שאם חסים עליו אביו ואמו, סוף שיצא לתרבות רעה ויעבור עברות ויתחיב מיתה בבית דין: **ותלית אתו על עץ.** רבותינו אמרו, כל הנסקלין, נתלין, שנאמר (פסוק כג) כי קללת אלהים תלוי. והמברך ה', בסקילה:
@14 **כי קללת אלהים תלוי.** זלזולו של מלך הוא, שאדם עשוי בדמות דיקנו וישראל הם בניו. משל לשני אחים תאומים שהיו דומין זה לזה, אחד נעשה מלך, ואחד נתפס ללסטיות ונתלה, כל הרואה אותו אומר המלך תלוי. כל קללה שבמקרא לשון הקל וזלזול, כמו (מלכ' א' ב, ח) והוא קללני קללה נמרצת:
@15 **והתעלמת.** כובש עין כאלו אינו רואהו: **לא תראה' והתעלמת.** לא תראה אותו שתתעלם ממנו, זהו פשוטו. ורבותינו אמרו פעמים שאתה מתעלם וכו' :
@16 **עד דרש אחיך.** וכי תעלה על דעתך שיתנהו לו קודם שידרשהו, אלא דרשהו שלא יהא רמאי: **והשבתו לו.** שתהא בו השבה, שלא יאכל בביתך כדי דמיו ותתבעם ממנו. מכאן אמרו, כל דבר שעושה ואוכל יעשה ויאכל, ושאינו עושה ואוכל, ימכר:
@17 **לא תוכל להתעלם.** לכבוש עינך כאלו אינך רואה אותו:
@18 **הקם תקים.** זו טעינה. להטעין משאוי שנפל מעליו: **עמו.** עם בעליו, אבל אם הלך וישב לו, ואמר לו הואיל ועליך מצוה אם רצית לטעון טעון, פטור:
@19 **לא יהיה כלי גבר על אשה.** שתהא דומה לאיש כדי שתלך בין האנשים, שאין זו אלא לשם ניאוף: **ולא ילבש גבר שמלת אשה.** לילך ולישב בין הנשים. דבר אחר שלא ישיר שער הערוה ושער של בית השחי: **כי תועבת.** לא אסרה תורה אלא לבוש המביא לידי תועבה:
@20 **כי יקרא.** פרט למזמן: **לא תקח האם.** בעודה על בניה:
@21 **למען ייטב לך.** אם מצוה קלה שאין בה חסרון כיס, אמרה תורה למען ייטב לך והארכת ימים, קל וחמר למתן שכרן של מצות חמורות:
@22 **כי תבנה בית חדש.** אם קימת מצות שלוח הקן סופך לבנות בית חדש ותקיים מצות מעקה, שמצוה גוררת מצוה, ותגיע לכרם ושדה ולבגדים נאים. לכך נסמכו פרשיות הללו: **מעקה.** גדר סביב לגג, ואונקלוס תרגם תיקא כעין תיק שמשמר מה שבתוכו: **כי יפל הנפל.** ראוי זה לפול ואף על פי כן לא תתגלגל מיתתו על ידך, שמגלגלין זכות על ידי זכאי וחובה על ידי חיב:
@23 **כלאים.** חטה ושעורה וחרצן במפלת יד: **פן תקדש.** כתרגומו תסתאב. כל דבר הנתעב על האדם, בין לשבח כגון הקדש, בין לגנאי כגון אסור, נופל בו לשון קדש, כמו (ישעיה סה, ה) אל תגש בי כי קדשתיך: **המלאה.** זה מלוי ותוספת שהזרע מוסיף:
@24 **לא תחרש בשור ובחמור.** הוא הדין לכל שני מינים שבעולם, והוא הדין להנהיגם יחד קשורים זוגים בהולכת שום משא:
@25 **שעטנז.** לשון ערוב. ורבותינו פרשו שוע טווי ונווז:
@26 **גדלים תעשה לך.** אף מן הכלאים. לכך סמכן הכתוב:
@27 **ובא אליה ושנאה.** סופו:
@28 **ושם לה עלילת דברים.** עברה גוררת עברה, עבר על לא תשנא (ויקרא יט, יז) סופו לבא לידי לשון הרע: **את האשה הזאת.** מכאן שאין אומר דבר אלא בפני בעל דין:
@29 **אבי הנערה ואמה.** מי שגדלו גדולים הרעים יתבזו עליה:
@30 **ואמר אבי הנערה.** מלמד שאין רשות לאשה לדבר בפני האיש:
@31 **ופרשו השמלה.** הרי זה משל, מחורין הדברים כשמלה:
@32 **ויסרו אתו.** מלקות:
@34 **ואם אמת היה הדבר.** בעדים והתראה שזנתה לאחר ארוסין:
@35 **אל פתח בית אביה.** ראו גדולים שגדלתם: **וסקלוה אנשי עירה.** במעמד כל אנשי עירה: **לזנות בית אביה.** כמו בבית אביה:
@36 **ומתו גם שניהם.** להוציא מעשה חדודים שאין האשה נהנית מהם: **גם.** לרבות הבאים מאחריהם. דבר אחר גם שניהם לרבות את הולד, שאם היתה מעברת אין ממתינין לה עד שתלד:
@37 **ומצאה איש בעיר.** לפיכך שכב עמה, פרצה קוראה לגנב. הא אלו ישבה בביתה לא אירע לה:
@40 **כי כאשר יקום** וגו' **.** לפי פשוטו זהו משמעו, כי אנוסה היא ובחזקה עמד עליה כאדם העומד על חברו להרגו. ורבותינו דרשו בו הרי זה בא ללמד ונמצא למד וכו' :
@44 **לא יקח.** אין לו בה לקוחין ואין קדושין תופסין בה: **ולא יגלה כנף אביו.** שומרת יבם של אביו הראויה לאביו. והרי כבר הזהר עליה משום (ויקרא יח, יד) ערות אחי אביך, אלא לעבור על זו בשני לאוין ולסמוך לה (פסוק ג) לא יבא ממזר, ללמד שאין ממזר אלא מחיבי כריתות וקל וחמר מחיבי מיתות בית דין, שאין בעריות מיתת בית דין שאין בה כרת:
@45 **פצוע דכא.** שנפצעו או שנדכאו ביצים שלו: **וכרות שפכה.** שנכרת הגיד ושוב אינו יורה קלוח זרע אלא שופך ושותת ואינו מוליד:
@46 **לא יבא ממזר בקהל ה'.** לא ישא ישראלית:
@47 **לא יבא עמוני.** לא ישא ישראלית:
@48 **על דבר.** על העצה שיעצו אתכם להחטיאכם: **בדרך.** כשהייתם בטרוף:
@50 **לא תדרש שלמם.** מכלל שנאמר (פסוק יז) עמך ישב בקרבך יכול אף זה כן, תלמוד לומר לא תדרש שלמם:
@51 **לא תתעב אדמי.** לגמרי ואף על פי שראוי לך לתעבו שיצא בחרב לקראתך: **לא תתעב מצרי.** מכל וכל, אף על פי שזרקו זכוריכם ליאור. מה טעם, שהיו לכם אכסניא בשעת הדחק. לפיכך. ט **בנים אשר יולדו להם דור שלישי.** ושאר האמות מתרין מיד. הא למדת שהמחטיא לאדם קשה לו מן ההורגו, שההורגו הורגו בעולם הזה, והמחטיאו מוציאו מן העולם הזה ומן העולם הבא, לפיכך אדום שקדמם בחרב לא נתעב וכן מצרים שטבעום, ואלו שהחטיאום נתעבו:
@53 **כי תצא** וגו' **ונשמרת.** שהשטן מקטרג בשעת הסכנה:
@54 **מקרה לילה.** דבר הכתוב בהוה: **ויצא אל מחוץ למחנה.** זו מצות עשה: **לא יבא אל תוך המחנה.** זו מצות לא תעשה. ואסור לכנס למחנה לויה, וכל שכן למחנה שכינה:
@55 **והיה לפנות ערב.** סמוך להערב שמשו יטבול, שאינו טהור בלא הערב שמש:
@56 **ויד תהיה לך.** כתרגומו ואתר, כמו (במדבר ב, יז) איש על ידו: **מחוץ למחנה.** חוץ לענן:
@57 **על אזנך.** לבד משאר כלי תשמישך: **אזנך.** כמו כלי זינך:
@58 **ולא יראה בך.** הקדוש ברוך הוא ערות דבר:
@59 **לא תסגיר עבד.** כתרגומו. דבר אחר אפלו עבד כנעני של ישראל שברח מחוצה לארץ לארץ ישראל:
@61 **לא תהיה קדשה.** מפקרת, מקדשת ומזמנת לזנות: **ולא יהיה קדש.** מזמן למשכב זכור. ואונקלוס תרגם לא תהי אתתא מבנת ישראל לגבר עבד, שאף זו מפקרת לבעילת זנות היא, מאחר שאין קדושין תופסין לו בה, שהרי הקשו לחמור, שנאמר (בראשית כב, ה) שבו לכם פה עם החמור, עם הדומה לחמור. ולא יסב גברא מבני ישראל אתתא אמא, שאף הוא נעשה קדש על ידה, שכל בעילותיו בעילות זנות שאין קדושין תופסין לו בה:
@62 **אתנן זונה.** נתן לה טלה באתננה פסול להקרבה: **ומחיר כלב.** החליף שה בכלב: **גם שניהם.** לרבות שנוייהם, כגון חטים ועשאן סלת:
@63 **לא תשיך.** אזהרה ללוה שלא יתן רבית למלוה, ואחר כך אזהרה למלוה (ויקרא כה, לז) את כספך לא תתן לו בנשך:
@64 **לנכרי תשיך.** ולא לאחיך. לאו הבא מכלל עשה, עשה, לעבור עליו בשני לאוין ועשה:
@65 **לא תאחר לשלמו.** שלשה רגלים. ולמדוהו רבותינו מן המקרא:
@67 **מוצא שפתיך תשמר ועשית.** לתן עשה על לא תעשה:
@68 **כי תבא בכרם רעך.** בפועל הכתוב מדבר: **כנפשך.** כמה שתרצה: **שבעך.** ולא אכילה גסה: **ואל כליך לא תתן.** מכאן שלא דברה תורה אלא בשעת הבציר, בזמן שאתה נותן לכליו של בעל הבית, אבל אם שכרו לעדור ולקשקש, אינו אוכל:
@69 **כי תבא בקמת רעך.** אף זו בפועל הכתוב מדבר:
@70 **כי מצא בה ערות דבר.** מצוה עליו לגרשה שלא תמצא חן בעיניו:
@71 **לאיש אחר.** אין זה בן זוגו של ראשון, הוא הוציא רשעה מתוך ביתו וזה הכניסה:
@72 **ושנאה האיש האחרון.** הכתוב מבשרו שסופו לשנאותה, ואם לאו קוברתו, שנאמר או כי ימות:
@73 **אחרי אשר הטמאה.** לרבות סוטה שנסתרה:
@74 **אשה חדשה.** שהיא חדשה לו ואפלו אלמנה, פרט למחזיר גרושתו: **ולא יעבר עליו.** דבר הצבא: **לכל דבר.** שהוא צורך הצבא, לא לספק מים ומזון ולא לתקן דרכים, אבל החוזרים מעורכי המלחמה על פי כהן, כגון בנה בית ולא חנכו או ארס אשה ולא לקחה, מספיקין מים ומזון ומתקנין את הדרכים: **יהיה לביתו.** אף בשביל ביתו, אם בנה בית וחנכו ואם נטע כרם וחללו, אינו זז מביתו בשביל צרכי המלחמה: **לביתו.** זה ביתו: **יהיה.** לרבות את כרמו: **ושמח.** ישמח את אשתו. ותרגומו ויחדי ית אתתיה. והמתרגם ויחדי עם אתתיה, טועה הוא, שאין זה תרגום של ושמח אלא של ושמח:
@75 **לא יחבל.** אם בא למשכנו על חובו בבית דין, לא ימשכננו בדברים שעושים בהן אוכל נפש: **רחים.** היא התחתונה: **ורכב.** היא העליונה:
@76 **כי ימצא.** בעדים והתראה. וכן כל כי ימצא שבתורה: **והתעמר בו.** אינו חיב עד שישתמש בו:
@77 **השמר בנגע הצרעת.** שלא תתלוש סימני טמאה, ולא תקוץ את הבהרת: **ככל אשר יורו אתכם.** אם להסגיר אם להחליט אם לטהר:
@78 **זכור את אשר עשה ה' אלהיך למרים.** אם באת להזהר שלא תלקה בצרעת, אל תספר לשון הרע. זכור העשוי למרים שדברה באחיה ולקתה בנגעים:
@79 **כי תשה ברעך.** תחוב בחברך: **משאת מאומה.** חוב של כלום:
@81 **לא תשכב בעבוטו.** לא תשכב ועבוטו אצלך:
@82 **כבוא השמש.** אם כסות לילה הוא, ואם כסות יום החזירהו בבקר, וכבר כתוב בואלה המשפטים (שמות כב, כה) עד בא השמש תשיבנו לו, כל היום תשיבנו לו וכבוא השמש תקחנו: **וברכך.** ואם אינו מברכך, מכל מקום ולך תהיה צדקה:
@83 **לא תעשק שכיר.** והלא כבר כתוב, אלא לעבור על האביון בשני לאוין לא תעשוק שכר שכיר שהוא עני ואביון, ועל העשיר כבר הזהר (ויקרא יט, יג) לא תעשק את רעך: **אביון.** התאב לכל דבר: **מגרך.** זה גר צדק: **בשעריך.** זה גר תושב האוכל נבלות: **אשר בארצך.** לרבות שכר בהמה וכלים:
@84 **ואליו הוא נשא את נפשו.** אל השכר הזה הוא נושא את נפשו למות, עלה בכבש ונתלה באילן: **והיה בך חטא.** מכל מקום, אלא שממהרין להפרע על ידי הקורא:
@85 **לא יומתו אבות על בנים.** בעדות בנים. ואם תאמר בעון בנים, כבר נאמר איש בחטאו יומתו, אבל מי שאינו איש, מת בעון אביו, הקטנים מתים בעון אבותם בידי שמים:
@86 **לא תטה משפט גר יתום.** ועל העשיר כבר הזהר (דברים טז, יט) לא תטה משפט, ושנה בעני לעבור עליו בשני לאוין, לפי שנקל להטות משפט עני יותר משל עשיר, לכך הזהיר ושנה עליו: **ולא תחבל.** שלא בשעת הלואה:
@87 **וזכרת.** על מנת כן פדיתיך לשמור חקותי אפלו יש חסרון כיס בדבר:
@88 **ושכחת עמר.** ולא גדיש. מכאן אמרו עמר שיש בו סאתים ושכחו אינו שכחה: **בשדה.** לרבות שכחת קמה ששכח מקצתה מלקצור: **לא תשוב לקחתו.** מכאן אמרו, שלאחריו שכחה, שלפניו אינו שכחה, שאינו בבל תשוב: **למען יברכך.** ואף על פי שבאת לידו שלא במתכון, קל וחמר לעושה במתכון. אמור מעתה, נפלה סלע מידו ומצאה עני ונתפרנס בה הרי הוא מתברך עליה:
@89 **לא תפאר.** לא תטול תפארתו ממנו. מכאן שמניחין פאה לאילן: **אחריך.** זו שכחה:
@90 **לא תעולל.** אם מצאת בו עוללות לא תקחנה. ואיזו היא עוללות כל שאין לה לא כתף ולא נטף. יש לה אחד מהם הרי היא לבעל הבית. וראיתי בתלמוד ירושלמי איזו היא כתף, פסיגין זה על גב זה. נטף, אלו התלויות בשדרה ויורדות:
@92 **כי יהיה ריב.** סופם להיות נגשים אל המשפט. אמור מעתה אין שלום יוצא מתוך מריבה, מי גרם ללוט לפרוש מן הצדיק הוי אומר זו מריבה: **והרשיעו את הרשע.** יכול כל המתחיבין בדין לוקין, תלמוד לומר והיה אם בן הכות הרשע, פעמים לוקה ופעמים אינו לוקה. ומי הוא הלוקה, למוד מן הענין (פסוק ד) , לא תחסם שור בדישו, לאו שלא נתק לעשה:
@93 **והפילו השפט.** מלמד שאין מלקין אותו לא עומד ולא יושב אלא מטה: **לפניו כדי רשעתו.** ולאחריו כדי שתים. מכאן אמרו, מלקין אותו שתי ידות מלאחריו ושליש מלפניו: **במספר.** ואינו נקוד במספר, למד שהוא דבוק, לומר במספר ארבעים ולא ארבעים שלמים, אלא מנין שהוא סוכם ומשלים לארבעים, והן ארבעים חסר אחת:
@94 **לא יסיף.** מכאן אזהרה למכה את חברו: **ונקלה אחיך.** כל היום קוראו רשע ומשלקה קראו אחיך:
@95 **לא תחסם שור בדישו.** דבר הכתוב בהוה והוא הדין לכל בהמה חיה ועוף העושים במלאכה שהיא בדבר מאכל. אם כן למה נאמר שור, להוציא את האדם: **בדישו.** יכול יחסמנו מבחוץ, תלמוד לומר לא תחסם שור מכל מקום, ולמה נאמר דיש, לומר לך מה דיש מיוחד דבר שלא נגמרה מלאכתו וגדולו מן הארץ, אף כל כיוצא בו, יצא החולב והמגבן והמחבץ שאין גדולו מן הארץ, יצא הלש והמקטף שנגמרה מלאכתו לחלה, יצא הבודל בתמרים ובגרוגרות שנגמרה מלאכתן למעשר:
@96 **כי ישבו אחים יחדו.** שהיתה להם ישיבה אחת בעולם, פרט לאשת אחיו שלא היה בעולמו: **יחדו.** המיוחדים בנחלה, פרט לאחיו מן האם: **ובן אין לו.** עין עליו: בן או בת, או בן הבן, או בת הבן, או בן הבת, או בת הבת:
@97 **והיה הבכור.** גדול האחים הוא מיבם אותה: **אשר תלד.** פרט לאילונית שאינה יולדת: **יקום על שם אחיו.** זה שיבם את אשתו יטול נחלת המת בנכסי אביו: **ולא ימחה שמו.** פרט לאשת סריס ששמו מחוי:
@98 **השערה.** כתרגומו לתרע בית דינא:
@99 **ועמד.** בעמידה: **ואמר.** בלשון הקדש, ואף היא דבריה בלשון הקדש:
@100 **וירקה בפניו.** על גבי קרקע: **אשר לא יבנה.** מכאן למי שחלץ שלא יחזור וייבם, דלא כתיב אשר לא בנה, אלא אשר לא יבנה, כיון שלא בנה שוב לא יבנה:
@101 **ונקרא שמו** וגו' **.** מצוה על כל העומדים שם לומר חלוץ הנעל:
@102 **כי ינצו אנשים.** סופן לבא ליד מכות, כמו שנאמר מיד מכהו. אין שלום יוצא מתוך ידי מריבה:
@103 **וקצתה את כפה.** ממון דמי בשתו. הכל לפי המביש והמתביש. או אינו אלא ידה ממש, נאמר כאן לא תחוס, ונאמר להלן בעדים זוממין (לעיל יט, יג) לא תחוס, מה להלן ממון, אף כאן ממון:
@104 **אבן ואבן.** משקלות: **גדולה וקטנה.** גדולה שמכחשת את הקטנה, שלא יהא נוטל בגדולה ומחזיר בקטנה:
@105 **לא יהיה לך.** אם עשית כן, לא יהיה לך כלום:
@106 **אבן שלמה וצדק יהיה לך.** אם עשית כן יהיה לך הרבה:
@108 **זכור את אשר עשה לך.** אם שקרת במדות ובמשקלות הוי דואג מגרוי האויב, שנאמר (משלי יא, א) מאזני מרמה תועבת ה', וכתיב בתריה בא זדון ויבא קלון:
@109 **אשר קרך בדרך.** לשון מקרה. דבר אחר לשון קרי וטמאה, שהיה מטמאן במשכב זכור. דבר אחר לשון קור וחום, צננך והפשירך מרתיחתך, שהיו כל האמות יראים להלחם בכם ובא זה והתחיל והראה מקום לאחרים. משל לאמבטי רותחת שאין כל בריה יכולה לירד בתוכה, בא בן בליעל אחד קפץ וירד לתוכה. אף על פי שנכוה, הקרה אותה בפני אחרים: **ויזנב בך.** מכת זנב, חותך מילות וזורק כלפי מעלה: **כל הנחשלים אחריך.** חסרי כח מחמת חטאם, שהיה הענן פולטן: **ואתה עיף ויגע.** עיף בצמא, דכתיב (שמות יז, ג) ויצמא שם העם למים, וכתיב אחריו ויבא עמלק: **ויגע.** בדרך: **ולא ירא.** עמלק, **אלהים' מלהרע לך**:
@110 **תמחה את זכר עמלק.** מאיש ועד אשה מעולל ועד יונק משור ועד שה (שמואל א' טו, ג) . שלא יהא שם עמלק נזכר אפלו על הבהמה, לומר בהמה זו משל עמלק היתה:

@1 **כי תצא למלחמה על אויביך.** למדנו שבמלחמת הרשות הכתוב מדבר שנאמר ושבית שביו והנה מז' עממין לא הותר להם שבי אך חוייבו להחרים כל נפש אדם כמו שקדם:
@2 **וראית בשביה אשת יפת תואר וחשקת בה.** ידוע שאין תנאי ההתר לבא עליה שתהיה יפת תואר וזה מבואר בעצמו והנה אמרה התרה וחשקת בה מכל מקום כיון שהוא חושק בה עשתה התורה נחת רוח ליצרו. והנה מן התנאי שיראנה בשביה רוצה לומר בעת השביה אך בזולת זה לא הותר לו אם לא נתגיירה ואמר אשת אי זו שתהיה בתולה או בעולה ואפילו אשת איש כגון שברח בעלה ולמדנו מזה שאין אישות לגוי לאסרה על ישראל ולמדנו מזה שאין לו רשות לקחת יותר מאחת שנאמר אשת וחשקת בה ולא בה ובחברתה:
@2 **ולקחת לך לאשה.** ידוע שאין זה לנשואין שהרי אמר אחר זה ואם לא חפצת בה ושלחתה לנפשה וגו' לא תתעמר בה תחת אשר עניתה מגיד שהוא בא עליה קודם שישאנה ואין הביאה ההיא מה שאמר ואחר כן תבא אליה ובעלתה שהרי אמר אחריו ואם לא חפצת בה מגיד שאם לא רצה לבא עליה להיות לו לאשה לא יוכל להתעמר בה תחת אשר עניתה ולזה לאות שכבר בא עליה קודם זה בגיותה שאם נתגיירה לא הוצרכה התורה לומר ומכור אל תמכרנה בכסף. ואמנם הכונה באמרו ולקחת לך לאשה שיותר לבא עליה ורמז בזה שאין ראוי לו שיקחנה לזה הפעל המגונה אם לא לתכלית שישאנה אחר זה והנה סמך לזה אמרו והבאת אל תוך ביתך. להעיר שאין ראוי שינהג בה הפקר אך יכניסנה לביתו או לדומה לו שיבא שם בצנעה ושם יבא אליה ואמר ולקחת לך לאשה להעיר שאין ראוי שיקחה כי אם לו לא לאיש אחר:
@3 **והבאת אל תוך ביתך.** בארה התורה שאין ראוי לו שיבא עליה ויעזבנה תכף שעשה רצונו ממנה או שיכשל בה עוד אחר זה אבל יחוייב לו שיביאה אל תך ביתו והשתדלה התורה שיעשה בה מה שתשקיט רתיחת התאוה אשר לו בה כדי שלא יקחנה אחר זה לאשה ולזה צותה שתגלח ראשה כדי לנוולה ולהסיר יפיה ולגדל צפרניה כי זה גם כן ממה שינוולה ושתבכה קרוביה עד ירח ימים. כי הבכי גם כן יסיר יופי האשה והנה לזאת הסבה גם כן צותה שתסיר שמלת שביה מעליה כי הבגדי' ההם ישימנה יפה ליפויים ולזה חשק בה בהיותה עם הבגדים הנאים ההם ואמר שתשב בביתו כדי שיראה אותה בנוולה ויסור חשקו ממנה והוא מבואר שאם רצתה להתגייר מיד לא יצטרך לזה כי היא מותרת לו אחר זה ולזה הוא ממתין לה עד שלשים יום לראות אם תרצה להתגייר:
@4 **ואחר כן תבא אליה ובעלתה והיה לך לאשה.** מגיד שאינו בועל אותה אלא להיות לו לאשה וזה יהיה בהכרח אחר שנתגיירה:
@5 **והיה אם לא חפצת בה.** רוצה לומר שמתוך נוולה שראית סר החשק שהיה לך או ששקטה תאותך אחר שבאת אליה:
@5 **ושלחתה לנפשה.** לפי מה שאמר לא תעמר בו וידענו שאסור להושיב בארצנו עובדי עבודה זרה למדנו שאינו משלחה עד שתקבל עליה שלא לעבוד עבודה זרה ויתר המצות שנצטוו בני נח ותהיה לנפשה כמו שאר הגרים התושבים:
@5 **ומכור לא תמכרנה בכסף וגומ'.** הזהיר מזה שלא יוכל למכרה כו שימכרו שאר השבי גם הוא לא יוכל להשתעבד בה במדרגה ההשתעבד בשבי מפני שכבר ענה אותה ולזה יהיה לה זה השכר ממנו וכאלו התחכמה התורה בזה להשקיט תאות החושק בה בשביה מפני ראותו שאחר זה תסור ממנו הממשלה שהיתה לו בה ולפי שאמרה התורה שלא יתעמר בה ולא ימכרנה מפני שענה אותה למדנו שכזה יחוייב שימנע מלתת אותה במתנה שהרי ישעבדה בזה ועוד שהתורה אמרה ושלחתה לנפשה רוצה לומר שבעת שישלחנה תהיה לנפשה:
@6 **כי תהיין לאיש שתי נשים וגו'.** לפי שהכונה בזה הוא שלא יעיר מהבכור חלקו הראוי לו מהנחלה ואף על פי שהוא בן השנואה למדנו שאין דקדוק התור' שתחיינה הנשים שתים לבד ושתהיה האחת אהובה והאחת שנואה אבל רצה התורה להודיע זה הדין במקום אשר יתכן יותר שימצא זה הענין והנה סמך זה לענין יפת תואר לפי שהתורה גלתה שהיא שנואה למקום ולזה השתדל לנוול אותה וכאלו באר בזה שאין לו רשות להעביר חק הנחלה מהבכור שנולד לו ממנה אחר שנתגיירה כי אז היא אשתו והנה בארה זה התורה בכללות:
@7 **והיה ביום הנחילו את בניו את אשר יהיה לו.** רוצה לומר כאשר ינחיל את בניו כל קניניו:
@7 **לא יוכל לבכר את בן האהובה על פני בן השנואה.** הזהיר בזה שלא יתן דין הבכורה לבן האהובה ויסיר מבן השנואה ולפי שלא למדנו מזה עדיין שלא יוכל להסיר מהבכורה בן השנואה ובן האהובה יחד הוצרך לומר אחר זה שיחוייב לו להכיר את הבכור בן השנואה לתת לו פי שנים בכל אשר ימצא לו. רוצה לומר שבכל מה שזכה בו האב ביום ההנחלה והוא ברשותו יהיה לבכור כפל מה שיגיע לכל אחד מבניו הנשארים וזה שאם היו ג' בנים עושים מנכסי האב ד' חלקים השנים לבכור וכן על זה הדרך. ומזה המקום למדנו גם כן שלא יוכל מדרך ההנחלה לעשוק מנחלת אחד מבניו ולתת לאחר ומזה המקום למדנו שאין בכורה בבנות וראוי שתדע שה הדין אינו נוהג אלא במה שהאב נותן על דרך ההנחלה שנאמר ביום הנחילו אבל אם רצה לתת בתורת מתנה נותן מה שירצה לאשה שיהיה מבניו ולפי שהתורה לא הזהירה מזה אלא לבניו למדנו ששאר יורשיו יוכל להנחיל את מי שירצה:
@9 **כי יהיה לאיש בן סורר ומורה.** אין הכונה במה שאמר לאיש אבי הבן הזה שאם היה כן היה אומר אינו שומע בקולו ובקול אמו לא איננו שומע בקול אביו. ולזה יהיה הרצון בזה שיגיע הבן הזה למדרגה שיהיה לאיש וזהו תכף שהגדיל ויצא מכלל קטנות ולפי שבעת ההוא שהוא עת לקיחת מוסר הפליג בזה להיות בלתי שומע לקול אביו ולקול אמו. ונטה אל הזוללות והשכרות הפליגה התורה בענשו להתברר העניין שכל מה שיגדל יוסיף ברוע:
@9 **סורר ומורה.** רוצה לומר שהוא סר ממוסר האב והאם וממרא אותם בדרך שאינו שומע לקולם וזאת ההסרה וההמראה הוא בענין הזוללות והשכרות כמו שאמר אחר זה בננו זה סורר ומורה איננו שומע קולנו זולל וסובא. והנה שם הזולל וסובא לא יפול אלא בזוללי בשר וסובאי יין כאמרו אל תהי בסובאי יין בזוללי בשר למו והוא מבואר שלא באי זה שיעור שיאכל אדם מן הבשר וישתה מן היין יקרא זולל וסובא אבל יש לו שיעור לא יפול זה השם על פחו' ממנו ושערו חכמים כי מי שיאכל בשר משקל חמשים דנרין בת אחת וישתה מן היין חצי לוג בבת אחת יתכן שיתואר בזה השם והוא מבואר מצד הוראת הגדר ולא יקרא מפני זה זולל וסובא גם כן אם לא אכל זה השעור ברעבתנות ושתה היין בגרגרנות כמנהג הזוללים והסובאים ובמנהג שהם אוכלים אותו ושותי' אותו וזה שהבשר לא יהיה חי ולא שלם הבשול והיין לא יהיה חי ולא שלם המזינה וזה מבואר ממנהגם לפי שלא יקרא בזה השם מפני פעם אחת שיקרה לו זה כמו שלא יתואר ברופא מי שרפא פעם אחת אם לא יורגל במלאכת הרפואות הנה צריך שיהיה הענין הזה באון שיוכל זה הבן להרגיל עצמו בו וזה אמנם יהיה כשיגנוב משל אביו ואמו מה שיקנה בו הבשר והיין שאם יגנוב משל אחרים הנה לא ימצא לו לגנוב שם אלא בקושי ויצטרך גם כן שיאכלנו בבית אחרים עם חבורה מהאנשי' רעי המנהג באלו הדברים כי אז ימצא לו בקלות להמשך לזה המעשה ואמנם אם יאכל זה וישתה ברשות אביו הנה לא ישלם לו אלא בקושי ההסתר שם מאביו ומאמו והוא מבואר עוד שהבשר שירגילו לאכלו אילו הגרגרנים הוא בשר בהמה ויחוייב גם כן שיהיה קונה בזול מה שיקנה ממבשר והיין שאם יצטרך לקנות זה ביוקר לא ימצא לו לגנוב משל אביו מה שיוכל להרגיל בו עצמו בזה המנהג הרע כדרך שיתכן שיתואר כשהוא זולל וסובא:
@9 **ויסרו אותו.** הנה מפני שזה המאמר יסבול שיסרו אותו אביו ואמו כאמרו במוציא שם רע ויסרו אותו הנה ראוי שנבין בזה המקום שלקוהו בית דין לפי שהעונש הנפלא שענשוהו התור' אח' זה הוא יותר ראוי בזה האופן ר"ל כאשר נתברר שאינו מקבל מוסר לא מאביו ומאמו ולא מבית דין. והנה אמרו איננו שומע בקול אביו ובקול אמו ר"ל שלא יקבל מוסרם ואף כי יכוהו ויוכיחוהו כי בזול' זה לא יתברר שאינו שומע בקולם ואמרו ויסרו אותו ר"ל מי שיש לו רשות ליסרו אחר האב והאם והם הדיינים:
@9 **ולא ישמע אליהם.** ר"ל שעדיין אינו מקבל מוסר אביו ואמו אף כי לקה ע"י ב"ד:
@10 **ותפשו בו אביו ואמו.** מגיד שצריך ששניהם יסכימו בזה:
@11 **ואמרו אל זקני עירו בננו זה.** ר"ל בננו זה סורר ומורה שהבאנוהו בפניכם ולקח והנה עודנו מחזיק ברשעתו:
@11 **איננו שומע בקולינו זולל וסובא.** וצריך שיהיו זקני העיר ההיא ראויים דון דיני נפשות ר"ל שיהיו עשרים ושלשה וצריך שיהיו שם הדייני' שלקח בפניהם כי בזולת זה לא ישפטוהו סקילה כי המשפט הראשון לאו הוא אלא למלקות:
@12 **וכל ישראל ישמעו וייראו.** לפי שביאר שבשער מקומו יהיה נסקל חוייב מזה שתהיה הודעת זה לכל ישראל כשיכתבו זקני העיר היא כל ישראל סקלנו פלוני בב"ד פלוני מפני שהיה סורר ומורה ואולם התנאים האחרים אשר בזה הענין הם לפי מה שנזכר פה שלא ינהג זה הדין אלא בבן לא בבת שנא' כי יהיה לאיש בן ולא ינהג בבן אלא כשהוא גדול כי לא יהיה בן עונשים קודם זה ואחר זה ימשך לו זה הדין עד שישלם היותו לאיש שנאמר כי יהיה לאיש בעת היותו לאיש לא אחר זה ולפי שהוא יתחיל להיות איש כשיתחילו השערות אצל הערוה כמו שהתבאר בשרשי' הכוללי' הנה נשלמה היותו לאיש אחר שהקיפו השערות כל הגיד ולפי שה ישלם לפי הנהוג בשלשה חדשי' הנה לא יהיה ימי סורר ומורה כי אם ג' חדשים ואם תתאחר בו יותר צמיחת אלו השערות הה נלך בזה לפי הנהוג על דרך הטבע ואם תמהר לו נשפט להקל שכיון שנשלמה היותו לאיש הנה אינו נסקל ולא ינהג זה אלא כשיהיו לאביו ולאמו ידי' לתפוש ורגלים ללכת ולשון לדבר עינים לחזות שנאמר ותפשו בו אביו ואמו והוציאו אותו ואמרו בנינו זה ולפי שהם מרגישים שהוא אינו שומע בקולם למדנו שאינם חרשים וראוי שתדע עוד שאם היה באכילתו ושתייתו צד מצוה או צד עברה לא היה נסקל שנאמר איננו שומע בקולנו שאין בעניינו אלא השמיעה בקולנו או לא שמיעה יצאו מצוה ועברה שיש בהם שמיעה בקול השם יתעלה או לא שמיעה ולפי שההלקאה והסקילה לא יהיה אחת להם אלא בעדות צריכים אביו ואמו שיביאו עדים תחילה שהוא זולל וסובא בתנאים הנזכרים וילקוהו בית דין על זה ואחר זה יביאו עדים שאינו שומע בקולם ויסקלוהו:
@13 **וכי יהיה באיש חטא משפט מות והומת ותלית אותו על עץ.** כבר בארה התורה בזה המקום שהנתלה הוא המקלל שאמ' כי קללת אלהים תלוי ולפי שעובד עבודה זרה נקרא מגדף גם כן כאמרו והנפש אשר תעשה ביד רמה את יי' הוא מגדף למדנו שהעובד עבודה זרה נתלה גם כן ושני אלו הם נסקלים כמו שקדם ומגיד שאחר מיתתם יתלום על עץ:
@14 **לא תלין נבלתו על העץ.** מגיד שאם הלינה עובר בלא תעשה:
@14 **כי קבור תקברנו ביום ההוא.** מגיד שמצות עשה לקברו:
@14 **כי קללת אלהים תלוי.** רוצה לומר מפני שברך השם יתעלה הוא תלוי ויהיה זה גורם לחלול השם כל זמן שיתמיד שם כשיאמרו האנשים על מה נתלה ולפי שכוונת התורה היא זו למדנו שהעץ שיתלוהו עליו ראוי שיהיה נקבר עמו כדי שלא יאמרו זהו העץ שנתלה בו פלוני על שבירך השם יתעלה ויהיה זה גורם לחלול השם והנה מצאנו כי גם לכבוד הבריות חסה התורה שלא יהיה זכר למה שבאה לאדם תקלה על ידו ולזה אמר ואת הבהמה תהרוגו ולזה הוא מבואר שהעץ הוא נקבר עמו ולזה גם כן אמר כי קבור תקברנו ולא אמר תקברנה שיהיה שב אל הנבלה ולזה יחוייב שיהיה העץ תלוש שלא יהיה חסר אלא הקבורה ומזה המקום למדנו שלא ישהו אותו שם אבל יתלוהו ותכף יקברוהו עם העץ כי כל מה שישהו אותו שם נמצא שם שמים מתחלל:
@14 **ולא תטמא את אדמתך אשר יי' אלהיך נותן לך.** רוצה לומר כי בזה החלול לשם יתעלה שיהיה גורם דבר הלנת נבלתו על העץ. תטמא אדמתך. ולזה ראוי שתהיה נזהר לבלתי הלין נבלתו על העץ או אמר ולא תטמא את אדמתך מפני העפוש שיתחדש אז במקם ההוא אם תשאר שם הנבלה ואולם שאר הדינים אשר בזה הוא שאין האשה נתלית שנאמר אותו ולא אותה ושאין תולין כליו עמו אבל תולין אותו ערום שנאמר אותו ואין בית דין תולין שנים ביום אחד שנאמר אותו ולא אותו וחבירו ולמדנו מזה שמצות עשה לקבור כל הרוגי בית דין ביום המיתה שנאמר קבור תקברנו ביום ההוא וכל שכן שראוי לקבור שאר מתים ביום המיתה אלא אם הלינו אותם לכבודם שעל ההלנה שהוא נוול הזהירה תורה לא על ההלנה שהיא לכבוד:
@15 **לא תראה את שור אחיך או את שיו נדחים.** כגון שראה חמור וכליו הפוכים פרה ורוצה בין הכרמים שהצורה מוכחת שהם אובדים וכן כל מה שדומה לזה ואמר לא תראה להגיד שכיון שהוא רואה אותם אפילו מרחוק הוא מחויב להטפל בהם להשיבם לאחיו:
@15 **והתעלמת מהם.** רוצה לומר שאין לך רשות להתעלם מהם אך תחוייב להשיבם והוא מבואר שאינו מתעלם מהם אלא אם היה דרכו שלא להתעלם מהם אם היו שלו והיו נדחים בזה האופן כי אז הוא מתעלם מהם מפני היותם משל אחיו לא שלו ואולם אם היה זה הרואה אותם גדול המעלה עד שיקל בהם אם היו שלו ולא יטרח לחזור אחריהם הוא בעצמו או שהיתה אבידתו שיאבד בעת היותו טורח בזה יותר מערך האבדה ההיא אף על פי שהיתה שלו יעזבינה לזאת הסיבה או שהתורה תכריחהו שלא ילך שם להשיבה ואפילו היתה שלו כמו שהיה כהן והאבדה בבית הקברות הנה לא יחוייב להשיב זאת האבדה:
@15 **השב תשיבם לאחיך.** כיון שהשיבם לאחיו קיים המצות ואף על פי שלא הודיעו זה:
@16 **ואם לא קרוב אחיך אליך.** רוצהלומר כי אף על פי שאתה יודע מי הם הבעלים אינך זקוק לטרוח להשיבה אליהם אם היה רחוק ממך:
@16 **ולא ידעתו.** מגיד שאיך שהיה משי אלו הסבות הנה תאספהו אל תוך ביתך ולא תוך בית אחר:
@16 **והיה עמך עד דרוש אחיך אותו והשבותו לו.** מגיד שאם ידרוש ולא ידרוש אותו הדבר. ר"ל שלא יתן סמנים בדרך שיתבאר שהוא אותו לא תחוייב להשיבו שלא יתן סמנים בדרך שיתבאר שהוא אותו לא תחוייב להשיבו לו אך אם יתן סמניו אז תשיבנו לו:
@17 **כן תעשה לחמורו וכן תעשה לשמלתו וכן תעשה לכל אבדת אחיך וגו'.** מגיד שאר נדחים הוצרך להזכיר שכן יהיה זה הדין בשמלה וכל אבידה שיורה צורת הנחתם שזהו היא אבידה ולא הונחה שם לדעת כמו שירה ענין היותם נדחים בשור ושה שהם אובדים:
@17 **אשר תאבד ממנו.** לא שיאבדה לדעת וכן אם היתה במקום שאבודה ממנו ומכל אדם כמו שהיא נאבדת בזוטו של ים ובשלילותו של נהר שאין אני קורא בזה אשר תאבד ממנו כי לא ממנו לבד היא אובדת:
@17 **לא תוכל להתעלם.** כבר בארנו מתי לא יחוייב להטפל בה ואינו קרוי התעלם וכבר נתבאר בפרשת ואלה המשפטים שזאת המצוה נוהגת גם באבידת רשעי ישראל ולפי שתזהיר על אביד' אחיו למדנו שאם מצא חמור והביאו בביתו עושה מלאכה ואוכל ואינו עומד בטל מפני השבת אבדה לבעלים וכן העניין במה שידמה לזה:
@18 **לא תראה את חמור אחיך או שורו נופלים בדרך.** ראוי שיובן זה שהם נופלים מפני המשא שאם היו נופלים בזולת המשא מפני חולשתם אין שם דרך להקימם ואולם הכונה הוא בזה שהיו רובצים תחת משאם כמו שנזכר בפרשת ואלה המשפטים וכבר צוה שם לפרוק משאם עם הבעלים ובזה המקום צוה להקים המשא עליהם עם הבעלים ולזה אמר הקם תקים עמו וכבר בארנו קודם שה מתי יקרא זה העניין התעלם ומתי לא והנה אמר בפרשת ואלה המשפטים כי תפגע ובזה המקום אמר לא תראה ולזה לא יחוייב אלא על ראייה שהיא כפגיעה וזה לפי מה ששערו חכמים ריס שהוא אחד משבעה ומחצה במיל ואם היה רחוק ממנו יותר משה השיעור אינו חייב בזאת המצוה ואמר הקם תקים עמו שאינו חייב לטעון המשא על הבהמה אם לא יעזרו לו הבעלים ואם היה זקן או חולה טוען הוא לבדו ולפי שאין אדם חייב לעשות מלאכת חבירו ולטרוח בה בחנם הוא מבואר שהטוען יקח שכר על הטעינה אך לא על הפריקה כי אינה מעצם המלאכה:
@19 **לא יהיה כלי גבר על אשה.** הזהיר שלא תלבש אשה בגדים מיוחדים לאיש ומה שידמה לזה שיביא לחשוב לאנשים שהיא איש כי זה ממה שיביא לזנות כי היא תלך בין האנשים לזנות עמהם ולא יורגש בזה וכן לא ילבש גבר בגדים ותכשיטין מיוחדים לנשים כי זה יביאהו להתערב עם הנשים ויזנו עמו ולזה אמר כי תועבת יי' אלהיך כל עושה אלה כי זה יביא אל שתמלא הארץ זמה והנה הרחיקה התורה שלא יהיה אפילו כלי אחד מגבר על אשה ואף על פי שהוא לבדו לא יביא לחשוב בה שהוא איש ושלא ילבש איש אפילו לבוש אחד מיוחד לנשים אף על פי שהוא לבדו לא יביא לחשוב בו שהוא אשה ולזה הוא מבואר שאיש שצובע שערו הלבן או שמלקט לבנות מתוך שחורות עובר על זאת האזהרה וכן האשה ששמה כובע האיש בראשה או מה שידמה לזה הנה זה ביאור מה שהוגבלנו באורו בזאת הפרשה:
@20 **כי יקרא קן צפור.** רוצה לומר עוף טהור ואמר כי יקרא שאם היה מזומן כמו אווזים ותרנגולים ומה שידמה להם אינו חייב לשלח ולזה אמר גם כן לפניך בדרך:
@20 **בכל עץ או על הארץ.** הוא מבואר שדבר הכתוב בהווה אך באי זה מקום שימצא הקן נוהג בו זה הדין ואפילו היה על המים:
@20 **אפרוחים או בצים.** הנה לפי הוראת הגדר יקראו אפרוחים החיים וכן הבצים שתרבץ האם עליהם הם ראוים להיות מהם אפרוח ואם לא לא ידבק בהם גדר הביצה ולא אמר אפרוחים או בצים אלא בהווה שהרי אמר קן צפור וכבר יקרא קן צפור אפילו אין בו כי אפ אפרוח אחד או ביצה אחת:
@20 **והאם רובצת על האפרוחים או על הבצים.** מגיד שאם אינה רובצת עליהם מותר לקחת אותה ואם היא רובצת על דבר מבדיל בינה וביניהם והדבר ההוא נוגע בהם כמו שהיה עליהם בגד והיא רובצת על הבגד ההוא ומה שידמה לזה הרי הדבר ספק אם תקרא רובצת עליהם אם לא ומגיד שאם היה הזכר רובץ עליהם לא ינהג בו זה הדין כי אינו אם וכן אם נשחטה האם שם בקן שהרי אינה אם ואינה בת שלוח:
@20 **לא תקח האם על הבנים.** זאת היא כשהיתה האם לך אם לקחת אותו אבל אם של מוקדשין או שהרגה את הנפש אתה רשאי לקחת אותה:
@21 **שלח תשלח את האם.** מגיד שאם לקחה ושלחה פטור ואינו פטור אם לא קיים עשה שבה הוא או שלוחו אבל אם שלחה אחר שלא מדעתו הנה לא קיים עשה שבה והתורה אמרה שלח תשלח ולזה ילקח כשהיה הדבר באון שימש ממנו חיוב מלקו':
@21 **למען ייטב לך והארכת ימים.** מגיד שאלו המצות יישירו האדם אל הטובות הגופיות והנפשיות והנה התועלת בזאת המצוה היא להרחיק לקיחת הקן בזה האופן כי הרבה יהיה שלא יקח אדם תועלת באפרוחים או בבצים ויהיה זה סבה אל שיניח הקן ההוא ותשלם ההויה בו ולא יבלבל הטוב שמשפיע השם יתעלה בהמצאת אלו המינים אם לא לתועלת אשר כוון בהם ואם אמר אומ' שבלקיחת הקן בכללו עם האם תשלם זאת ההויה אמרנו לו כי דרך אלו העופות המדבריים הוא שיבריחו מיד אדם ואם ישימום במאסר יצטערו ותמנע האם מלרבץ על בניה ויאבד הקן עם שאין ראוי שיקח מהם האדם כי אם על דרך הצידה לא שישתמש לצודם ולהשחיתם בכלי בעינו אשר שם השם יתעלה בהם להתמיד הויתם והוא הדמיון ששם באם לרבץ על הבנים כדי שיצאו ממנו אפרוחים והאהבה הדמיונית ששם בה לרבץ על האפרוחים לגדלם ולהשגיח במחייתם ובזה האופן דומה זאת המצוה במה שהזכיר מלבשל גדי בחלב אמו:
@22 **כי תבנה בית חדש.** אחד הבונה או שנתן לו במתנה או קנאו או יורשו כי כונת התורה היא שלא ישים דמים בביתו והנה אם לא ידבק במקום ההו' שם בית כמו שלא היה בו שיעור בית אינו חייב במעקה שנאמר בית וזה אינו בית:
@22 **ועשית מעקה לגגיך.** אפילו היה של שותפין כיון שהוא בית שהוא ראוי לדירה כי התורה דקדקה בזה כדי שלא יפול הנופל ממנו והנה שיעור המעקה הוא בדרך שישמור מהנפילה ושערו חכמים עשרה טפחים ולזה יחוייב גם כן שיהיה חזק שיוכל האדם להסמך בו בבואו שם ולא יפול והנה אמר לגגך למעט הבתים שאינם ראויים לדירה כמו בתי כנסיות ובתי מדרשות והנה ההיקש אחד בכל מה שיהיה בבית שיוכל ליפול הנופל ממנו כמו הבור ומה שידמה לו אמנם אם היה הבית נמוך והיה אפשר שיפול מרשות הרבים אינו חייב לעשות שם מעקה ברשות הרבים שהרי אין הסכנה ברשותו וכבר אמרה התורה כי יפול הנופל ממנו לא בתוכו והנה נמשכה זאת המצוה לקודמת לה שלא ישתמש האדם בבנין הבית שהוא מסודר מהשכל המעשי לשמירת האדם ולהיות לו למחסה ולמסתור אל הפסדתו במה שיהיה בביתו סבה לו הפך מה שכוון בו:
@23 **לא תזרע כרמך כלאים.** רוצה לומר שלא יזרע עם כרמו כלאים ויהיה זה כשיזרע זרעים משני מינים עם חרצן יחד שהוא אז זורע הכרם וזורע עמו כלאים ואז הוא עובר גם כן עם זה משום זורע כלאים זהרי אמרה תורה שדך לא תזרע כלאים והוא מבואר שכבר יקרא זורע הזורע בידו או מהחפה הזרעים שם בעפר:
@23 **פן תקדש המלאה הזרע אשר תזרע ותבואת הכרם.** ידוע שאין הרצון באמרו פן תקדש שיהיה קדש כי לא יהיו הדברים קדש בכמו אלו הסבות ואולם הקדושה הזאת היא שתהיה נבדל מהנאתם כי הקדש יאמר על ההבדל ולזה גם כן יאמר על הטומאה באמרו אל תגע בי כי קדשתיך ולפי שאמר כי זה יהיה סבה שהמלאה רוצה לומר מלאת הכרם תאסור הזרע אשר תזרע ותבואת הכרם למדנו שלא יתחייב על זריעת הכלאים בכרם בזה האופן אם לא היתה שלמות הוית הזרעים באה עם התבואות הכרם וזה לא יהיה אלא בזרעי' שאינם עושים אלא לשלם שנים כמו החרצן וכן הקנבוס ולוף כמו שזכרו רז"ל. ומזה המקם למדנו שאף על פי שלא יזרע כרמו כלאים אך היו נזרעים בו קצת זרעים והשריש זרעם בעת בא תבואת הכרם שהם נאסרים שנאמר הזרע אשר תזרע ותבואת הכרם שבעת שיזריעו זה יעשה זה תבואה ולפי שאמר לא תזרע כרמך וגו' פן תקדש למדנו כי שלו הוא אוסר ולא של חבירו ולפי שאמר כרמך להעיר על היותו כלם אחד למדנו שאם היה הענין בדרך שיהיה נבדל מכרמו כמו שהיתה שם מחיצה או הפסק יביא מהכלל בכרם ההוא אינו מקודש וראוי שתדע שלא תכלול זאת האזהרה מזריעת מיני אילנות בכרם וזה כי האילנות דרכם שינטעו לא שיזרעו שנאמר ונטעתם כל עץ מאכל ולזה לא נכללו אלא במה שאמר ולא תזרע. ולזאת הסבה היה ראוי ג"כ שיתחייב על זריעת מיני זרעי' בכרם ואף על פי שלא יזרע עמהם חרצן כי בכרם ראוי לומר נטיעה אמר מי האיש אשר נטע כרם. כרמים וזתי' אשר לא נטעת. ועוד כי לא יקרא כרם אלא כשיהיו בו גפנים ואין העניין בזה כמו הענין באמרו שדך לא תזרע כלאים וזה כי השדה יקרא שדה ואם אין בו זרעים ואין העניין כן בכרם כי הארץ לא תקרא כרם אם לא בו גפנים אלא כי מפני שאפשר שיפול קצת ספק על זה כי כבר יאמר האומר אני נוטע כרם או אני זורע כרם היה שלא יתחייב מלקות בזולת זה האופן כי לא ילקו על הספק ולפי שאמר לא תזרע אשר תזרע למדנו שאם זרעהו הרוח או אחר שלא מדעתו אינו אוסר שהרי אינו זורע. והנה לא יקרא כרם אלא מה שהיה נטוע מהגפנים בצורת כרם והמעט שיפול בו זה השם לפי הוראת הנדר הם ה' גפני' ולפי שאמר שיאסר זרע אשר תזרע:
@24 **לא תחרוש בשור ובחמור יחדיו.** הנה מפני שלא אמר לא תחרוש בסוס ובחמור אבל לקח שני מיני' מן החי ההולך אחר טמא ואחר טהור למדנו שזה הדין נוהג בכל שני מיני בהמה או היה שיהיה הא' טהור והשני טמא כמו הענין בשור ובחמור ואין ראוי שנבין שלא יהיה זה נוהג אלא בשור וחמור לפי שכבר מצאנו שדקדקה התורה בכלאי' בכל שני מיני בהמה שנאמר בהמתך לא תרביע כלאים וכל ב' מיני זרעים שנאמר שדך לא תזרע כלאים הנה מפני זה ראוי שנבין מזה המקום שדקדקה התורה נשתוף שי מינים במלאכה שאחד מהם מהטהורה והשני מהטמאה ולפי שאמר יחדיו למדנו שאיך שיהיו במלאכה אחת עובר המשתף אותם במלאכה ההיא על זה הלאו והנה לקח החרישה תמורת כל מלאכה שישתתפו בה כי אין בכאן סבה תחוייב שדקדקה התורה בשור וחמור ולא בשאר המינים ושכבר דקדקה התורה בחרישה ולא בשאר המלאכות ולפי שאמר בשור ובחמור למדנו בשור ואדם או בחמור ואדם לא יאסר זה ועוד כי האדם מצד הנהגתו הב"ח במלאכתם הוא משתתף עמהם. ואם היה האדם מוזהר מלחרוש עם השור אם עם החמור היה ראוי שתצוה לא תחרוש בשור או לא תחרוש בחמור:
@25 **לא תלבש שעטנז צמר ופשתים יחדיו.** לפי שאמר בפרשת קדושים תהיו ובגד כלאים שעטנז לא יעלה עליך למדנו שהעליה שהיא דרך לבישה נאסרה לבד אבל מציע הוא תחתיו בגדים של כלאים ולפי שאין דרך לבישה בגדי צמר ואניצי פשתן שאינו בגד למדנו שאין אסור ללבוש אותם יחד והנה בגד כלאים שעטנז הוא לפי מה שיורה עליו הגדר שיעשה בגד צמר ופשתים יחדיו ולפי שהבגד יהיה נעשה מאלו בזולת טויה כמו הלבדים שנקראים בגד הנה אם עשה לבדין מצמר ופשתן הרי הם כלאי בגדים וכן אם ערבם בטויה שהיה קצת נימי הטיווי צמר וקצתם פשתים וכן אם ערב אותם באריגה באופן שישותפו בה עשות הבגד מהם באחד מאלו השלשה אופנים הנה הוא נקרא בגד כלאי' שעטנז ולפי שאמר צמר ופשתי' יחדיו למדנו שאיך שיהיו יחדיו בבגד בדרך שיתכן בהם שיהיו חלק בגד הנה הבגד ההו' כלאי' ולזה אם חבר חוט אחד של צמר בבגד של פשתן באופן שיהיה חבור עמו רוצה לומ' שיתאחד עם הבגד הנה הבגד ההוא כלאים ראיה לדבר שהרי סמך לזה אמרו גדילים תעשה לך שכבר נתבאר שיושם בו פתיל תכלת שהוא של צמר כאלו באר שמפני המצוה הותר זה אך הוא כלאי' לולי המצוה ומזה יתבאר שאין כלאי בגדים נוהגים אלא בצמר ופשתים והנה לא יקרא צמר אלא הבא מן הצאן וידמה שכבר היו נוהגים לעשות זה כומרי עבודה זרה וזה יתבאר במעט עיון ממה שנזכר בזה בפרשת קדושים תהיו. ולפי שאמר צמר ופשתים יחדיו והנה הם יחדיו כשיתחברו להיות בגד אחד למדנו שאף על פי שלא יתחברו זה לזה הנה מפני שהבגד ההוא נכלל בו צמר ופשתים יחדיו הנה הוא אסור ללובשו מכאן שהלובש חלוק של צמר גמלין והיה בו חוט אחד של צמר רחלים בצד זה וחוט אחד פשתן בצד השני הנה הוא עובר משום כלאי' ואפילו השק והקופה מצטרפים את הכלאים רוצה לומר אם חבר קצת בגד צמר לצד אחד מבגד שק ובגד פשתן לצד השני הנה השק יצרפם להיות כלאים וכן הענין בחתיכת קופה כמו שאמרו בספרי ובתשיעי מכלאים אמרו מצטרפין לכלאים והכל עלה לענין אחד:
@26 **גדילים תעשה לך.** למדנו שבמקום מצוה לבד הותר זה ולזה יתבאר שהכהנים שלבשו בגדי כהונה שלא בשעת עבודה חייבים משום כלאים וכן הנושא שני בגדים שיש בהם ציצית בכל אחד מהם בדרך שיהיה כלאים לולי המצוה ההיא לא הותר ללבוש כי אם אחד מהם כי המצוה כבר קיימה בבגד האחד מהם ולפי שסמך זאת המצוה למה שזכר מצמר ומפשתים למדנו שאין מצות ציצית נוהגת אלא בבגדים של צמר או של פשתים ולפי שאמר תעשה לך גו' למדנו שצריך לעשות הגדילים על ארבע כנפות הכסות לא שישימם שם מן העשוי ולא שישימם באמצע הבגד אבל אצל ארבעה כנפות אין עושים לה גדילים והוא ציצית הנזכר במה שקדם ולפי שאמר כסותך אשר תכסה בה למדנו שאם אינו מתכסה בה אינה חייבת בציצית רוצה לומר אם מונחת בכלי ולמדנו עוד שאם אין בכסות שיעור לכסות בה הקטן שאפשר שתנהג בו זאת המצוה אינו חייב בציצית שנאמר אשר תכסה בה רוצה לומר שתוכל לכסות בה ואחשוב שאין ראוי לאדם שילבש יחד שני בגדים שיש בהם ציצית שהרי נאמר אשר תכסה בה ולא בה ובחברתה וראיתם אות ולא אותו וחבירו עם שזה יביא להאמנת השניות בש' יתעלה ובתורה כי זאת המצוה מעידה על הפך זה כמו שביארנו במה שקדם בסוף פרשת שלח לך. ובכלל הנה כמו שיעברו על נשיאת שני תפילין בראש משום בל תוסיף מפני שיש מקום בראש ראוי להניח בו שני תפילין. כן יעברו על נישאת יותר מבגד ציצית אחד משום בל תוסיף שהרי האדם ראוי לעשות כמה בגדי ציצית כי לא הונח לו המקום מוגבל אם יהיה כבגד העליון או התחתון או האמצעי ואולם שאר הדינין אשר בציצית כבר בארנום בסוף פרשת שלח לך הנה זה ביאור מה שהגבלנו בביאור בה מזאת הפרשה:
@27 **כי יקח איש אשה.** רוצה לומר שקנה אותה לו לאשה באחד ממיני הקניה ואחר כך בא אלה ושנא אותה ומפני שנאתו אותה העליל אותה שלא מצאה בתולה והוציא עליה שם רע לפי שידענו שאין האשה נסקלת על פי הבעל שנאמר על פי שנים עדים או שלשה עדים יומת המת ועוד שאף על פי שנודה שיאמן הנה לא תתחייב מפני זה מיתה כי אולי נבעלה קודם שתארס הנה מזה המקום יתבאר לנו שהוצאת שם רע הזה הוא שהביא עדים שזנתה בבית אביה אחר שנתארסה לו ועל זה אמר והוציא עליה שם רע רוצה לומר על ידי עדים שהעידו שזנתה אחר שנתארסה. או יהיה הרצון באמרו ושם לה עלילות דברים על יד עדים כי מאמרם יאמן ולזה יושמו לה הדברים ההם והם אמרם שנבעלה אחר שנתארסה והוצאתו עליה שם רע הוא מה שיאמר מעצמו שלא מצא לה בתולים כי זה אינו כי אם הוצאת דבה ושם רע כי דבריו אינם נאמנים ולזה ישפטו על פיהם הדיינים ויעיד על אמתת זה הפי' מה שאמר אחר זה והנה הוא שם עלילות דברים לאמר לא מצאתי לבך בתולים רוצה לומר כי לאמת שלא מצא לבתו בתולים שם עלילות דברים בפי העדים להעיד שקר ולא אמ' שם לה כי לא הושמו לה עלילות ההן אחר שיש לה עדים שיזימו עדי הבעל ולזה הוצרך לומ' והוציא עליה שם רע:
@28 **ואמר את האשה הזאת לקחתי.** מגיד שאומר כל דבריו לבית דין בפני אשתו שנאמר הזאת:
@28 **ואקרב אליה ולא מצאתי לה בתולים.** מגיד שהביאה שבא עליה הוא במקום בתולים לא שלח כדרכה:
@29 **ולקח אבי הנערה ואמה והוציאו בתולי הנערה וגומ'.** לפי שהוא מבואר שהוא אפשר להם להביא עדים שכאשר בא עליה בעלה היתה בתולה ואף על פי שיביאו השמלה מגוללה בדמים אין זה עדות שהיתה בתולה כי כבר יתכן שהיו הדמים ההם מן הדמים הבאים מן המקור או מזולתם הוא מבואר שהוצאת הבתולים הוא שיביאו עדים להזים העדים הראשונים והנה מה שאמר אל זקני העיר ידוע שצריך שיהיו ראויים לדון דיני נפשות כי על זה הדבר בא הבעל:
@30 **ואמר אבי הנערה.** למדנו מה שאין ראוי לאשה שתדבר בפני בית דין אך ידברו קרוביה או אוהביה בעבורה כדי שלא תתבייש:
@31 **ופרשו השמלה.** רוצה לומר שכבר חוקרין באלו העדיות עד שיעמדו על אמתת הדבר:
@32 **ולקחו זקני העיר ההיא את האיש ויסרו אותו.** רוצה לומר שילקוהו ולזה אמר שיקחו אותו כדי להלקותו:
@33 **וענשו אותו מאה כסף.** הם מאה שקלים של כסף צרוף:
@33 **ונתנו לאבי הנערה.** מגיד שאם היתה נערה זוכה אביה בזה הקנס ואם לא היה לה אב הרי הוא לעצמה כי לא זכתה התורה בו אלא לאב לא ליורשיו והנה האשה בנעוריה ברשות אביה כמו שביארנו בפרשת ראשי המטות ונתבאר גם כן בזאת הפרשה במוציא שם רע ובאונס ומפתה ולפי שכבר דקדק בכל המקומות לזכור בה שם נערה שנאמר ולקח אבי הנערה ואמר אבי הנערה ונתנו לאבי הנעה למדנו שאם היתה נערה בעת הוצאתו שם רע לא ילקה מוציא שם רע ולא יענש בזה הכסף:
@33 **כי הוציא שם רע על בתולת ישראל.** למדנו שאם לא היתה בתולת ישראל הוא שתהיה הורתה ולדתה בקדושה אין זה הדין נוהג במוציא שם רע רוצה לומר ללקות ולשלם קנס וראוי שתדע שצריך שיאמר שמעת שקדש אותה באלו הקדושין אשר עליה בא עליה זנתה שנאמר את האשה הזאת לקחתי ואקרב אליה ולא מצאתי לה בתולים רוצה לומר את האשה הזאת קדשתי ושבעת קרבתי אליה ולא מצאתי לה בתולים כאלו יאמר שבעת שקדשה היו לה בתולים אך אחר זה כשקרב אליה לא היו לה בתולים לפי שכבר נבעלה בנתים ובזה האופן יהיה זה המאמר בעצם ומדרך מה שהוא כמו שהתבאר בשרשים הכוללים ולזה הוא מבואר שאם הביא עדים שבעת שהיתה מאורשת בקדושים אחרים נבעלה לא ינהג במוציא שם רע זה הדין כאלו תאמר שקדשה לו וגרשה וחזר וקדשה והביא עדים שבהיותה מקודשת לו בקדושין הראשונים נבעלה וכן אם קדשה אחיו והיתה זקוקה לו לא ינהג בה מוציא שם רע זה הדין שאינו יכול לומר את האשה הזאת לקחתי וכן אם לא אמר הבעל אלא שלא מצא לה בתולים ולא הביא עדים שזנתה תחתיו אינו נוהג בו זה הדין ממוציא שם רע שנא' ושם לה עלילות דברים מגיד שצריך שיביא הוא העדים וכן אם לא אמר שזנתה תחתיו שנאמר והוציא עליה שם רע אף על פי שבאו עדים מעצמ' והעידו שמשנתארסה זנתה והוא מבואר שכאשר יאמר שזנתה תחתיו צריך שיוציא שם רע עליה שזנתה כדרכה כי לולי זה לא יהיה רושם בדבריו לאמת שלא מצאה בתולה ומזה יתבאר שאם לא היתה בחזקת בתולה כשנתקדשה לו לא ינהג בו זה הדין כי לא יתבאר מדברי העדים שהלכו בתליה בביאה ההיא והוא המכוון בדברי הבעל ולזה היה ענשה בסקילה כמשפט נערה בתולה מאורסה והנה נדקדק בכל זה במוציא שם רע מפני שעניינו הוא חדוש ואין ראוי שנקח ממנו זולת מה שזכרה אותו התורה:
@33 **ולא תהיה לאשה לא יוכל לשלחה כל ימיו.** עשתה התורה לו כמשפט הראוי לו כי אולי מפני שהית' בעודה שם לה עלילות דברים לתכלית שלא תשאר עמו כלל ורצתה התורה שתהיה לו לאשה כל ימיו והזהירה אותו שלא ישלחנה בגט לפיכך אם שלחה צריך להחזירה ואם היה כהן שאינו יכול להחזירה הנה כבר עבר על לא תעשה בשלחו אותה וראוי שתדע שאם לא היתה ראויה לו אלא בעברה כמו שזנתה תחתיו או שכבר נתברר שהיא אסורה לו לא יחוייב לו לקיימה כי התורה לא התחכמה בזה אלא כנגד רוע תכונתו שמפני שנאתו אותה היה רוצה שלא תשאר עמו ורצתה התורה להכניע רוע רצונו:
@34 **אם אמת היה הדבר הזה וגומ'.** רוצה לומר שכבר נמצאו דברי הבעל אמתיים ולא נמצאו עדים שיזימו עדי הבעל או שהביא הבעל עדים להזים את זוממי עדיו:
@35 **והוציאו הנערה אל פתח אביה וסקלוה.** עשתה התורה זה לבייש הוריה על שלא תקנוה מן המוכר מה שראוי. והוא מבואר שאם אין לה פתח בית אביה הנה היא נסקלת אל שער העיר ההיא כמו שביאר אחר זה במשפט הנערה בתולה מאורסה שאם ישכב איש אותה בעיר יהיו נסקלין על שער העיר למדנו מזה שאם לא היו בעיר אך בבית אביה סוקלין אותה על פתח בית אביה וראוי שתדע שאף על פי שלא היתה נערה בעת הוצאת זה השם הרע כיון שהיתה נערה בתולה מאורסה בעת שזנתה הרי היא נסקלת וכבר החמירה התורה על הנערה בתולה מאורסה יותר ממה שהחמירה בשאר המאורסות או בנשואות הבעולות בעל לפי שזה הענין הורה על הפלגת רוע תכונתה שתכף שגדלה והחלה להולד המותר הזרעי בה נטתה אל הזנות עם היותה בלתי יודעת עדיין טעם משכב האנשים ולא חששה לרוב תאותה אל הצער הקורה לה בהשחתת בתוליה ואל הבשת שיתכן שיקרה לה מזה כי העדר בתוליה יעידו על זנותה הנה זה ממה שיורה כי אחר שישלם להיות גובר המותר הזרעי בה תגדל תאותה יותר ותמלא הארץ זמה עם מה שהרגישה בהנאת משכב האנשים והיותה בטוחה אז מהצער והיות נקייה אז מהבשת שהיה ראוי שישיגנה על זה בהיותה בתולה:
@36 **כי ימצא איש.** רוצה לומר בעדים:
@36 **שוכב עם אשה בעולת בעל.** ידענו כי שוכב יקרא אפילו שלא כדרכה שנאמ' ואת זכר לא תשכב משכבי אשה והנה אמרו בעולת בעל יכלול אפילו בא עליה ארוסה בבית אביה:
@36 **ומתו גם שניהם.** מגיש שכאשר היה הענין כן ימותו שניהם. אך אם היה הוא איש והיא קטנה או היא אשה והוא קטן לא ימות כי אם הגדול מהם שהוא בן עונשים:
@37 **כי יהיה נערה בתולה מאורשה לאיש.** למדנו מזה שאין קדושי קטן כלום ולזה אמר מאורשה לאיש והנה לא ינהג בה זה הדין אלא בעת היותה נערה ושתהיה בחזקת בתולה כי לא חייבה התורה שיעידו העדי שהיא בתולה אז כשנבעלה כי זה לא יתכן:
@37 **ומצאה איש בעיר ושכב עמה.** אפילו שלא כדרכה כי הוא יקרא גם כן משכב כמו שביארנו והנה יעידו עדים על זה המשכב כי בזולת זה לא ימותו כמו שקדם:
@38 **והוציאו את שניהם אל שער העיר ההיא.** הנה דקדקה התורה בכל המקומות שתהיה ההמתה בשער שנמצאו בו כדי שיוסרו כל העם אשר נמצאת בהם זאת הרעה כי בודאי היה זה לרוע מנהג בני העיר המוכיחים והנוכחים:
@38 **את הנערה על דבר אשר לא צעקה בעיר.** אמר זה כי זה מעיד שלא היתה אנוסה כ"א לא נתרצת בזה היתה יכולה לצעוק וימלטוה האנשים ממנו והוא מבואר שהתורה דברה בזה בהוה כי בעיר יהיה על צד הפתוי ובשדה יהיה על צד האונס אך ראוי שתדע שבכל מקום שהתבאר שצעקה ואין מושיע לה הרי היא פטורה כי לא חטאה בזה ובכל מקום שתעשה זה ברצון הלא היא נסקלת:
@39 **והחזיק בה האיש.** ר"ל שלקחה בחזקה ובאונס:
@40 **ולנערה לא תעשה דבר.** למדנו מזה שהאנוס פטור מכלום:
@40 **כי כאשר יקום איש על רעהו ורצחו נפש כן הדבר הזה.** המשיל זה הענין לרוצח לפי שנתבאר היותה אנוסה על זה ראוי שנשפוט כי הדבר קשה לה כאלו בא להרגה מרוב הזנות שיש בזה הענין אצל הנערה הבתולה המאורשה לסבות שזכרנו במה שקדם עם שכל הנשים הטובות והראויות זר בעיניהם ענין הזנות עד שיבחרו המות על הזנות:
@41 **צעקה נערה המאורשה ואן מושיע לה.** למדנו מזה שראוי לרואים שיושיעוה מיד מאנסה וההושעה תהיה בשימלטוה מזה הפועל בצד שיוכלו עליו ולזה אם לא יוכל הרואה לאסרו בדרך שלא יוכל על זה הנה יש לו רשות להכותו או לחבול בו בדרך שתשלם לה ההצלה ממנו ואפילו בנפשו של רודף אחריה אם לא יוכל להצילה בצד אחר ולפי שכבר הקיש לזה הקם על רעהו ורצחו נפש למדנו שהרודף אחר חבירו להרגו יש רשות לרואים להושיעו ואפילו בנפשו של רודף ולזה אמרה התורה לא תעמוד על דם רעך ואינו דוקא דבר שיש מן הסכנה המגיע מנרדף ליד דם כי אפילו ממה שיגיע לו מן הפגם והבושת ואפילו אין בו היזק מן הממון כמו זה הענין המגיע בנאנסת זאת כי כלנו חייבים בכבוד האחד על חבירו:
@42 **כי ימצא איש נערה בתלה אשר לא אורשה וגו'.** רוצה לומר שאנס אותה והיא נערה בחזקת בתולה:
@42 **ושכב עמה ונמצאו.** רוצה לומר שיהיו שם עדים וכבר יתבאר במה שקדם שהנבעלת בעיר סתמה שהיא מפותה עד שיתברר האונס והנבעלת שדה סתמה שהיא אנוסה ולא יצטרך התראה באונס ומפתה כמו שהאוכל משל חבירו משלם ואינו צריך התראה ולפי שדקדקה התורה שתהיה התולה ולזה הסכימ' שיתן לאביה כסף במוהר הבתולות כמו שנזכר בפרשת ואלה המשפטים וזכר בזה המקום שזה הכסף הוא חמשים סלעים של כסף למדנו שלא ינהג זה הדין אלא כשבא עליה כדרכה מהמקום שהיא בתולה כי אין בכאן עונש לה שנוכל לומר שבעבורו דקדקה התורה שתהיה בתולה ולזה גם כן הסכימה התורה שיתן זה הכסף מפני מוהר הבתולות הראוי להם מצד בתוליהן:
@43 **ולו תהיה לאשה.** זו היא מצות עשה ולפי שרצה זה האונס לקחת אותה שלא לשם אישות כי אולי לא יתרצה בזה מצד מעלתו או מצד פחיתותה עמדה התורה כנגד מחשבתו והכריחה אותו שתהיה לו לאשה תחת אשר ענה אותה ונהנה משכיבתה וחשב לקחת זה ממנה בזולת חק שיהיה לו עליה רצתה התורה שיהיה מה שאכל מבשרו ולזה הוא מבואר שאם לא היתה מותרת לו לא יחוייב לו ללקחה ולפי שזה הכסף יתן מפני הנאת בתוליה ונתבאר בחובל בחבירו שהוא משלם ה' דברים כמו שביארנו בפרש' ואלה המשפטים הנה הוא מבואר שהוא ישלם עוד בושת ונזק וצער והוא מבואר גם כן שישלם גם כן שבת ורפוי אם קרה שיצטרך לה זה מפני צער השכיבה ואולם במפותה אינו צער שהרי נתרצתה והוא מבואר שאם אין לנערה האנוסה אב שהקנס הוא לעצמה לא ליורשי האב כי לא זכתה התורה בו אלא לאב:
@43 **לא יוכל לשלחה כל ימיו.** רוצה לומר מפני בחירתו אמנם התורה תכריחהו על זה הנה לא יחוייב לשלח כי התורה לא עמדה בה אלא כנגד בחירתו כמו שנתבאר מדברינו ואם שלחה יחוייב שיחזירנה או עבר על לא תעשה ולזה אם יכול לקיים העשה אחר זה הנה כבר עבר על לא תעשה והוא מבואר שאם לא רצתה להנשא:
@44 **לא יקח איש את אשת אביו.** הנה סמך זה לענין האנוסה להודיע שאשת אביו הוא שאסורה לו לא אנוסת אביו ואף על פי שנתבאר בכאן שזה האונס קושר אותו אל שיקחה לו לאשה הנה מפני שאינה אשתו היא מותרת להנשא לבנו וכאלו העיר בזה שאם לא רצתה בו מפני היותו זקן והיתה מתרצה בבנו היה ראוי לאב להשתדל לפייסה בזה הענין כי בזה תשקוט קצת תלונתה וזהו אמרו לא יקח איש את אשת אביו כאלו יאמר אשת אביו הוא שלא יוכל לקד' אבל מקדש הוא אנוסת אביו והנה לא תמצא באלו העריות שאמר לא יקח כי אם בזה המקום:
@44 **ולא יגלה כנף אביו.** רוצה לומר סתר אביו והוא כאלו אמר ולא יגלה ערות אביו:
@45 **לא יבא פצוע וגו'.** רוצה לומר פצוע ודכא ואמר אחר זה וכרות שפכה למדנו שאלו הפצעים והכריתה והדיבות הוא בכלי ההולדה ולפי ששפיעת הזרע תהיה מהגיד אם בשבילי הזרע אם בהבצים למדנו שבאלו הכלי' אם היתה הפציעה או הדיבה או הכריתה באי זה שיהיה מהם היה זה הנה יקרא באלו השמות רוצה לומר פצוע שפה או דכה שפכה או כרות שפכה והוא מבואר שאלו התארים לא יהיו אלא למי שנעשה לו זה לא למי שנברא בזה החסרון כי לא יתכן שיקרא כרות שפכה אלא למי שנכר' השפכה לא למי שלא כרתוהו לו דבר אלא שנברא בזה חסרון והנה הזהיר בזה המקום שלא יבוא אחד מהם בקהל השם רוצה לומר לקחת אשה מישראל:
@46 **לא יבא ממזר בקהל ה'.** ידוע עי הולד שיהיה לאיש מאשתו הוא בנו והוא נקרא בן ואמנם מי שיש לו ממי שיאן לו אישות בה בשום פנים הוא הנקרא ממזר ולזה הוא מבואר מצד הוראת הגדר והנה הזהיר מלבא ממזר בקהל השם. רוצה לומר שלא ישא ממזר בת ישראל ולא תנשא ממזרת לישראל וענין הביאה בקהל הוא בעילה באישות ולזה אם קדש ולא בעל אינם עוברים על זאת האזהרה:
@46 **גם דור עשירי לא יבא לו בקהל ה'.** כבר נתבאר אחר זה שאין הרצון בזה הלשון שמהדור העשירי ואילך יהיה מותר לבא בקהל זהרי אמר כן בעמוני ומואבי וזכר שם שהו אסור לבא בקהל עד עולם ולזה תהיה הכונה בזה המקום שעד עולם לא יבא ממזר בקהל יי' ואם אמר אומר כי מזה המקום יתבאר שאינו אסור מעשירי ואילך כיון שלא אמר עד עולם אמרנו כי התורה לא תאמר דברים סותרים זה את זה כל שכן שתאמר אותם עם זה ללא ענין ולזה הוא מבואר שאם היתה הכונה באמרה גם דור העשירי שמדור עשירי ואילך יבא בקהל הנה זה יהיה סותר מה שאמר אחריו עד עולם ועוד שלא היה צריך לזכור זה הסותר אבל יספיק כשיאמר לא יבוא עמוני ומואבי בקהל השם עד עולם:
@47 **לא יבא עמוני ומואבי בקהל השם.** ר"ל אחר שנתגיירו כי קודם זה לא היה צריך להזהיר בו וידענו שהמואבית מותרת מיד כשנתגיירה שהרי מצאנו בבועז שהיה משופטי ישראל ונשא רות המואביה ומצאנו גם כן בשלמה המלך שנשא נעמה העמונית ולזה הוא מובא' שהרצון בזה להזהיר בזכרים לבד מעמון ומואב שלא יבאו בקהל יי' ויעיד על זה מה שאמר על דבר אשר לא קדמו אתכם בלחם ובמי' בדרך בצאתכם ממצרים וזה כי דרך האנשים לעשות הפועל לא הנשים ולזה לא נענשו הנקבות:
@48 **ואשר שכר עלים וגומ'.** אמר זה בעבור בלק מלך מואב:
@50 **לא תדרוש שלומם וטובתם כל ימיך לעולם.** מגיד שאף על פי שאנחנו מחוייבים לקרוא לשלום לאשר נלחם עמו הנה לא נעשה כן לעמון ומואב בהיותינו נלחמי' עמהם באי זה עת שיהיה וזה הוא ענין זאת האזהרה:
@51 **לא תתעב אדומי כי אחיך הוא.** הזהיר שלא נתעב אדומי ומצרי מלבא בקהל כמו הענין בעמוני ומואבי אבל כשנתגיירו הדור השלישי יהיה מורת לבא בקהל יי' והם בני בניהם:
@53 **כי תצא מחנה על אויביך וגו'.** אמר כשתצא להלחם על אויביך ושמת העיר במצור בדרך שבני ישראל יעמדו במחנה לצוד על אויביהם צרך שישמרו מכל דבר רע כדי שלא יסור מהם השגחת השם יתעלה:
@54 **כי יהיה בך איש אשר לא יהיה טהור מקרה לילה.** הנה סמך זה למה שאמר ונשמרת מכל דבר להזהיר שלא יהרהר בעברה ביום ויבא לידי טומאה בלילה וצוה שיצא מן המחנה ההוא לפי שהמחנה ההוא הוא קדוש להיות בו שיכנה וידמה שזה יהיה לבד כשיהיה שם אדון אלהים כאמרו כי ה' אלהיך מתהלך בקרב מחניך ומזה המקום למדנו שבעל קרי יוצא חוץ מהמקדש שהוא מחנה שכינה והוא אך ממחנה ישראל לא יצא כי אם המצורע כמו שקדם מאמרו בדד ישב מחוץ למחנה מושב וצוהו לטבול ולהעריב שמשו כמשפט מי שתצא ממנו שכבת זרע:
@56 **ויד תהיה לך מחוץ למחנה וגומ'.** צוה שיתקנו מקום מחוץ למחנה שיפנו שם לכבוד השם יתעלה שהוא מתהלך בקרב המחנה. עם שבזה ישמור המחנה מהעפוש ההוא ולזה גם כן צוהו שתהיה לו יתד אצל כלי מלחמתו שיחפור בו הארץ כשיפנה ויכסה בעפר צואתו ויהיה זה סבה שלא ירגישו בעפוש ההוא במחנה הקדוש ההוא ויהיה כבוד לשם יתעלה ומזה המקום למדנו שאין ראוי להתפלל ולומר דבר קדושה במקום שיש בו צואה אם לא היתה מכוסה:
@58 **להצילך ולתת אויבך לפניך.** התכלי הראשון הוא להצילך ואם זכית שתדבק בך מן ההשגחה שיתן אויבך לפניך יעשה זה גם כן:
@58 **ולא יראה בך ערות דבר ושב מאחריך.** מגיד שאם יראה השם יתעלה בהם שום חטא ודבר מוגנה תסור שכינתו מהם ולמדנו מזה לפי דרכנו שהערוה לא יספיק בה הכסוי אם היה שתראה והיה זה כן כי ענינה יותר מגונה כי ראותה מביא להרהר בעברה:
@59 **לא תדגיר עבד אל אדוניו.** הנה זאת האזהרה בעבד כנעני שברח מחוצה לארץ לארץ להמלט מאדוניו הישראלי והראיה על זה כי העד האמור סתם בתורה הוא עבד כנעני והוא מה שאמר בהם מהם תקנו עבד ואמה. והתנחלתם אותם לבניכם אחריכם:
@60 **עמך ישב בקרבך.** רוצה לומר בארץ בקרבך לא שיהיה לו עיר לעצמו:
@60 **במקום אשר יבחר באחד שעריך.** אך לא במקום הבחירה:
@60 **בטוב לו לא תוננו.** רוצה לומר ביותר נאות לו לצאת ממנו פרנסתו ואף על פי שאיננו יותר טוב מצד עצמו:
@60 **לא תוננו.** זאת אונאת דברים והנה זה העבד יהיה עתה גר צדק כי העבדים נכנסו ברוב המצות לא יחסר בהם אלא שיצאו משעבוד האדון ואז הם גרי צדק כי לולי שעבוד האדון היו מחוייבים בכל זה מצות אך מפני שעבודו הם פטורים ממצות עשה שהזמן גרמא:
@61 **לא תהיה קדשה בבנות ישראל.** רוצה לומר פנוי מוכנת לתשמיש לכל אדם:
@61 **ולא יהיה קדש מבני ישראל.** רוצה לומ' שלא יתפרץ האיש לבעול הפנויות והנה קרא אותו קדש כי העברה תמשכהו לזה וכו' והוא קדש לזה הפעול מרוב המשכו לזה הגנות אם נסתבך בו מעט כי לאי יחשב בזה לחטא מפני היותו פנוי והיא פנויה:
@62 **לא תביא אתנן זונה ומחיר כלב בית יי' אלהיך לכל נדר.** מגיד שעושה אותם נדבה והיר הם כמו בהמה טמאה אשר יקריבו ממנה קרבן להש' שיעריכנה ויכי' בדמיה אך אם נדר עולה או שלמים והביא בהמה או עוף שהם אתנן זונה ומחיר כלב הרי הוא עובר על זאת האזהרה מזה המקום למדנו שאין אסור להקריב למזבח אלא הם עצמם לא חליפיהם ולזה אם היה האתנן או המחיר דמי' וקנה מהם בהמה עוף למזבח אינו עובר על זאת האזהרה והנה הזונה תקרא מי שיש אסור בבעילתה כמו גרושה לכהן הדיוט ואלמנה לכהן גדול ומה שידמה לזה ואולם האחרת שאין אסור בבעילתה תקרא קדשה. ולזה תמצא על הרוב שם הזונה באשת איש ובת איש כהן כי תחל לזנות הנה אמרו אל תחלל בתך להזנותה. ידמה שהוא מזאת הכוונה שאם הי' אשת איש אין ביד האב להזנות' גם לא הוצרך לזאת האזהרה ובכלל הנה הזונה יהיה הרצן בה השטה וחנטיה מדרכי התורה מדבר הבעליה ולזה תהיה הזונה נבעלת בעילה אסורה מן התורה ואולם אתנן זונה הוא מה שיתנה האיש לתת לה בזנות ההוא והוא אתנן לה אחר זנותה כאלו תאמר שאמר לה אם תבעלי לי או לפלוני אתן לך טלה אחר ונבעלה לו ונתן לה טלה אחד תכף הרי זה אתנן זונה ואם לא נתנו לה אלא לאחר זמן מה כיון שלא יחד לה הטלה שנתן לה באתננה אין בו דין אתנן זונה כי לא היה זה אלא פרעון חוב שהיה חייב לה תכף אחר הבעילה והרי נשתנה האתנן וכן אם הקדים לתת לה האתנן קודם הבעילה והקדישה אותו למזבח והקריבתו וקודם בעילה אינו אתנן זונה כי עדיין לא נהיה הזנות. וכבר נתבאר בכלאי הכרם שאין אדם אוסר דבר שאינו שלו ולזה אם נתן לה באתננה מה שאינו שלו אינו נפסל עוף קדשים להיותו מוכן אל העופפות והבעלים מטפלין בהבאתו עד העזרה הרי הוא כמו שלו לפסל והנה מחיר כלב הוא שיחליף כלב בבהמה או עוף אחד או הרבה והנה נפסלו אלו למזבח כי הם תעבת השם יתעלה כמו שזכר והנה אחשוב שאמר זה בכלב לפי שהוא שטוף מאד במשכב זכור ולזה מנע מחירו וחשבו כמו אתנן זונה ומזה המקום נלמד שהאתנן שנתן על המשכב זכור הוא פסול למזבח עם שהוא יותר מתועב מאתנן הזונה וראוי שנלמד מזה שהרובע והנרבע פסולין למזבח כי גם המחיר כלב פסלה התורה מפני היותו רובע ונרבע והנה בזאת האזהרה תועלת אחר כללי אך אינו מיוחד כמו הראשון והוא כי הזונה תהיה על הרוב אשת איש והיא ראויה להיות לבעלה לבד וברית הנשים לבעליהן חזק מאד וגם הכלב להיותו חזק האהבה הדמיונית לבעליו היה ראוי שיהיה לבעליו לבד ובריתו עם בעליו חזק מאד והנה הדברים אשר היו כלי להתנכר דבר ממשלה למי שהוא לו אין ראוי שנשימהו כלי להכיר הממשלה לשם יתעלה הנה זהו ביאור מה שצריך לבאר בזאת הפרשה שהגבלנו ביאורה:
@63 **לא תשיך לאחיך נשך כסף אבל כל דבר אשר ישך.** ידוע שהנשך יהיה מהמלוה לא אל הלוה וזה מבואר מצד הוראת הגדר אך אם יתן לשליח סך מה בשכר מה שיטרח לבקש לו מי שילונו הנה זה נכנס בגדר השכירות לא בגדר הנשך וכן אם הלוה אדם לחבירו והזמינו לפני בית דין לזמן מה ונתן לו סך מה להרויח זמן ההזמנה ההיא לזמן יותר ארוך אין זה גם כן נכנס בגדר הנשך כי איננו אז מלוה לו ממון ואינם גם כן נותן לו זה בשביל הארכת פרעון הממון אבל מצד שהיום ההוא רחוק לו מללכת שם לפני בית דין ולזה יבקש ממנו יום יהיה בו יותר פנוי. והנה אמר נשך כסף נשך אוכל לפי שכבר אמר במה שקדם אך כספך לא תתן לו בנשך ובמרבית לא תתן אכלך ולמד בכאן שאם נתן כספו בנשך כסף או בנשך אוכל וכן הענין באכל עובר בלא תעשה:
@63 **נשך כל דבר אשר ישך.** רוצה לומר אף על פי שלא היה נשך כסף או נשך אכל מכל מקום כיון שהתנה לתת לו בשכר ההלואה אי זה דבר שיהיה שוה כסף בצד מהצדדים עובר בלא תעשה ולפי שהיה אמרו לא תשיך אפשר שיהיה אזהרה ללוה שלא יסבב לאחיו שיהיה נושך וכבר באה האזהרה למלוה כמו שאמר במה שקדם. את כספך לא תתן לו בנשך. הנה ראוי שנבין שבזה המקום באה האזהרה ללוה עם שהוא מבואר שהלוה גם כן יש לו מבוא בזה החטא כי לא יוכל המלוה להלוות ברבית אם לא יסכים הלוה בנתינת הרבית והנה לזה תהיה אזהרה ללוה ולמלוה ולפי שאמר לאחיך למדנו שאינו מצוה להלוות ברבית לגר תושב או שלא ללות ממנו ברבית:
@64 **לנכרי תשיך.** היא מצות עשה מפני שהוא עובד עבודה זרה חייבה אותנו התורה להלוות לו ברבית כשירצה ללות ממנו לגרום לו מהנזק מה שאפשר שלא תהיה בו נטיה מהיושר ולזה צוה גם כן במה שקדם לנגוש הנכרי וראוי שיתבאר שאין הכונה בזה לנכרי תוכל להשיך שאם היה הענין כן היה זה המאמר מותר וזה כי כבר התבאר מאמרו לא תשיך לאחיך שאפי' לגר תושב מותר להשיך וכל שכן לנכרי שהרי מצאנו בנבלה שהקדים הכתוב הנתינה לגר תושב על המכירה לנכרי:
@64 **למען יברכך ה' אלהיך בכל משלח ידך על הארץ.** אין ראוי שיובן מזה שלא תנהג זאת האזהרה כי אם בארץ ישראל כי הוא מבואר כי אין לו התלות בארץ וכבר נזכר במה שקדם בזולת זכירת ארץ ואמנם הכונה בזה הוא שכבר ימשך לה מהטוב בקיום זאת המצוה שיברכך ה' אלהיך בכל משלח ידיך על הארץ ההיא הנבחרת ואולם בזולתה לא ימשך לה כל זה רוצה לומר שתתברך בכל משלח ידך כי אין שאר הארצות מוכנות לברכה כמו זאת הארץ הנבחרת שהיא מוכנת מאד אל שידבק בה ההשגחה האלהית כמו שקדם:
@65 **כי תדור נדר לה' אלהיך לא תאחר לשלמו.** ראוי שתדע שאין הבדל בזה בין נדר לנדבה והדברים קל וחומר אם בנדר שמה שנדר אינו בעין עובר בכל תאחר כל שכן כנדבה שהיא בעין עם שכבר צריך בה למהר להביאה למקם הבחירה כדי לשמרו שלא יהיה מועל בה אם להיותו נהנה ממנה עם שיעבור עם זה בה בגזה ובעבודה ועוד שהרי מצאנו אחר זה במצות עשה שבזה שפרט ביחד הנדר והנדבה וקרא הנדבה נדר כמו שאמר כאשר נדרת לה' אלהיך נדבה אשר דברת בפיך וזה לאות שבה הנדר הנזכר בכאן כלל הנדבה והנה הנדר שהוא להשם הוא עולה או שלמים או נסכים או ערבים או הקדש לבדק הבית או הדמין כי אלו כולם נקראי' נדר לפי מה שנתבאר בפרשת פינחס ובפרש' אם בחקותי וכבר הזהיר במה שקדם הצואה להביא אלו הנדרים למקום הבחירה לרגל שפגע בו תחלה. ובזה המקום הזהיר שלא נאחר לשלמו וראוי שנחקור מתי יעבור הוא על זאת האזהרה ונאמר שכבר ביאר בפרשת פינחס שהנדר אפשר שישלמהו בכל אחד ממועדי השנה שנאמר אלה תעשו להה' במועדיכם לבד מנדריכם ונדבותיכם מגיד שהדברים אחרים יתכן שישלמם באי זה שיהיה משלשה המועדים הנזכרים שם על סדרם ולזה למדנו מזה שלא יעבור בכל תאחר עד שיעברו על הנדר שלשה המועדי' על סדרם והם חג המצות וחג השבועות וחג הסוכות והנה נכלל במה שאמר לא תאחר לשלמו כל מה שנמשך להשלמת הנדר רוצה לומר כי גם בו יעבור בכל תאחר והמשל אם התנדב בהמה ונפל בה מום קודם שיביאה למקום הבחירה ופראה באחרת הרי הוא מוזהר שלא יעברו על האחרת שהפריש שלשה רגלים ומפני שאמר ובאת שמה והבאתם שמה וגומ' למדנו שכל מה שנדר יחוייב לשלמו כשימצא למי ולזה יתחייב בנדרי העניים תכף אם יש עניים אצלו אמר בספר מלכים על שלמה רק בבמות היא מזבח וגומ' וזה לאות שלא נאסרו הבמות במוחלט עד שנבנה בית המקדש:
@65 **כי דרוש ידרשו ה' אלהיך מעמך ודיה בך חטא.** וזה שאם לא תשלם נדריך להשם הנה זה יורה על חלשת אמונתך בו ומעוט יראתך ממנו ולזה יגיעך השם יתעלה עונש על זה:
@66 **וכי תחדל לנדור לא יהיה בך חטא.** הורה בזה שאין חפץ השם יתעלה באלו הנדרים מצד עצמותם ולזה לא יענישך אם תחדל לנדור ואולם יענישך אם נדרת לו ולא תשלם לסבה שזכרנו:
@67 **מוצא שפתיך תשמור ועשית.** צוה בזה המקום לשמור דבר הנדרים כלם כדי לעשות מה שנדר ליי' להוציאו מפיו אבל דברים שבלב אינם כלום ולזה אמר מוצא שפתיך והנה מוצא השפתים הוא לפי שמנהג הטבעי מה שכיון בלב ולזה צריך שיסכימו בדבר הנדר פיו ולבו והנה ביאר בכאן שאלו הדברים יכלול בהם הנדבה גם כן אמר נדבה אשר דברת בפיך לפי שכבר שכבר יחשב שהנדבה יספיק בה כונת הלב לבד כי הדבה מייחסת ללב כאמרו אשר ידבנו לבו וכל נדיב לב ולזה ביאר שצריך בזה גם כן הוצאה בפה מה שבלה:
@68 **כי תבוא בכרם רעך.** ראוי שתדע שאין הרצון בזה שיבא שם בלא רשות בעלים. כי אין ראוי שיעשה עם שהתורה תדבר במה שדרכו להיות כן כמו שהתבאר בשרשים הכוללים ולזה הוא מבואר שהרצון בזה כשיבא שם לעשות מלאכת הבעלים כמו הענין בשכיר וכבר אמר כמו זה בזאת הפרשה גם בבהמות שנא' לא תחסום שור בדישו ולפי שאמר רעך למדנו שאם היה משל הקדש אין השכיר אוכל:
@68 **ואכלת ענבים כנפשך שבעך וגו'.** מגיד שבמה שהוא עושה הוא אוכל בכר ענבים בקמה שבולים לא במה שאינו עושה ואכלת ענבים ולא שימוץ אותם ולא שיתנם לאחר ואפילו לבניו ולאשתו שנא' ואכלת ואמר "כ ואל כליך לא תתן להזהירו שלא יתן אל כליו ולא יתן לאחרים כי הכל הולך אל מקום אחד והוא מבואר שאוכל מהם די שבעו אך לא אכילה נסה שנאמ' כנפשך שבעך ולפי ששנה המאמ' בה בכרם ובקמה שהם גדולי קרקע ודברים שלא נגמרה מלאכתן למדנו שאין הפועל אוכל בשעת מלאכה אלא מגדולי קרקע ודברי' שלא נגמר' מלאכתן ואין ראוי שנשפוט שהתורה לא התירה לשכיר זה בתלוש שהרי גם לבהמה הזהירה התורה מלחסום פיה מלאכול כמה שתעשה בתלוש כאמרו לא תחסום שור בדישו ומזה נלמד ג"כ ביאור אלו הדברים הסתומים הנזכרים פה והוא שבשעת מלאכה הוא שהתיר זה ולזה יחוייב שיהיה עושה מלאכת בעלים קודם שיאכל והוא החלק הראשון שתחלקהו המלאכה ההיא בזה כאלו תאמר שיבצור וימלא הסל מהענבים קודם שיאכל מהענבים:
@68 **ואל כליך לא תתן.** ר"ל אך לכליו של בעל הבית תן וזה עוד ממה שיורה שכראוי לתת לכלי הכתוב מדבר ובאמרו וחרמש לא תניף הורה גם כן שכראוי להניף עליו חרמש הכתוב מדבר וראוי שתדע שלא ינהג זה הדין כי אם במי שהיו מעשיהם גמר מלאכה כמו הענין כחריש וקצי' אבל המנכש אינו אוכל כי אין מעשיו גמר מלאכ' ואמ' וחרמש לא תניף להעיד שלא הותר לו לבטל ממלאכת הבעלים בהיותן על קמתו לצורך אכילתו השבלים וירים מפני זה החרמש כי בעת שהוא קוצר אינו מניף החרמש אבל הוא משפילו וכורע עצמו לקצור ומניף החרמש לימינו לשמאלו לקצור או לשמאלו לימינו אם היה אטר יד ימינו אבל אינו מניף אותו אלא בשעה שהוא בטל מלאכתו וזה מבואר מענין החרמש וזה ממה שיחייב שיהיה הפועל זה על דרך שלא תבוטל מלאכת הבעלים ואמר וקטפת מלילות בידך לפי שמאלו השבולי' לא יאכל האדם שעור רב והנה לא הותר לו לצלות ולקלותן כדי שיהיו יותר נאותים לאכילה כי לא התירה התורה אכילתם אלא כמו שהם שנאמר ואכלת ענבים ולזה תהיה אכילת המלילות כדמיון אכילת הענבים כמו שהם:
@70 **כי יקח איש אשה ובעלה.** לפי שידענו שאין מתנאי המוציא אשתו בגט שיהיה בועל אשתו קודם זה שהרי אמר אחר זה והיתה לאיש אחד ושאה האיש האחרון וכתב לה ספר כריתות ואף על פי שלא בעל אותה הנה הרצון בזה כי יקח איש אשה או שבעלה והנה הקיחה הוא קנין ודרכו שיהיה בכסף או בשטר ולמד בזה המקום שכבר תהיה גם כן אשו בבעילה לבד כמו שמצאנו ביבמה ואמר שאיך שיהיה קניינו אותה מאלו הקנינים יוכל לגרשה:
@70 **והיה אם לא תמצא חן בעיניו כי מצא בה ערות דבר.** אמר זה לפי הנהוג לא יגרש אדם אשתו אלא לסבה גדולה ולזה אמר כי ימצא בה ערות דבר אמנם על דרך האמת כבר ביארה התורה שאפילו לא מצא בה ערות דבר יש לו רשות לגרשה אם שנאה כאמרו ושנאה האיש האחרון וכתב לה ספר כריתות ולזה מבואר שאיך שיהיה שלא מצאה חן בעיניו יש לו רשות לגרשה ולפי שזה הוא התנאי בגט למדנו שאין האיש מגרש אשתו אלא לרצונו כי התורה יחסה כל זה הפועל לרצון האיש:
@70 **וכתב לה.** שצריך שיכתוב הוא או שלוחו והנה לא יפול שם כתב כי אם בכתיבה שתהיה בדברים שרשומם עומד וצרך שיהיה נכתב לשמה לתכלית שתתגרש בו ולזה אמ' לה ספר כריתת ולפי שלא אמר בספר כמו שמצאנו בשאר המקומות כמו כתוב זאת זכרון בספר וכתב את האלות והאלה הכהן בספר למדנו מזה שבאי זה דבר שיכתוב זה הענין תגרש איך שיהיה בדרך שיוכל לתתו ברשותה שנאמ' ונתן בידה ולא יהיה מחוסר מעשה אחר הכתיבה אלא נתינה שנאמר וכתב לה ספר כריתות ונתן בידה והנה ספר כריתות הוא שיהיו נכתבים בו דברים יורו על כריתות האישות שביניהם וסלוקו כי לזה התכלית יתן בידה הספר ההוא ולזה צריך שלא תשאר נקשרת לבעלה בשום דבר מהדברים כל ימי חייב כי יכרות זה הספר בכללות מה שביניהם מהקשר מעת מהעתים ולפי שאמר ושלחה מביתו למדנו שצריך שתהיה כונת הספר ההוא שהוא משלח אותה ומסלק אותה מקניניו ולא שישלח אל עצמו ממנה כי אינו קנין לה אך היא קנינו:
@70 **ונתן בידה ושלחה מבית.** למדנו מזה שצריך שיתננו לה או הוא או שלוחו שנאמר ונתן בידה לא שתקחהו מעצמה ולא שיתנהו לה אחר שאינו שלוחו ולמדנו מאמרו בידה שאם לא הגיע הגט ברשותה או ברשות שלוחה אינה מתגרשת ואמ' אחר זה ושלחה מביתו להורו' שצריך שתהיה נתינתו בידה זה הגט לתכלית שישלחנה מביתו ולפי שאלו הדברים הכרחיים בגט כמו ששנה המאמר אחר זה ושנאה האיש האחרון וכתב לה ספר כריתת ונתן בידה ושלחה מביתו למדנו שצריך שיהיו שם שני עדים כשרים שכבר נשלמו כל אלו התנאים בזה הגט שהרי אמרה תרה על פי שנים עדים או שלשה עדים יקום דבר. ורואי שיתבאר מזה שבשטר מתגרשת לא בכסף:
@73 **לא יוכל בעלה הראשון לשוב לקחתה עוד אחרי אשר הוטמאה.** ידוע כי אין התנאי בה אסרה על בעלה הראשן שתהיה נבעלת לבעל השני כי לא התנה בזה תחלה אלא שתהיה לאיש אחר והיא לו תכף שנתקדשה ועוד שהרי נתבאר מדברי ירמיהו שאין התנאי בזה שתהיה נבעלתה לשני שנאמר לאמור הן ישלח איש את אשתו ויצאה מאתו והלכה והיתה לאיש אח' הישוב אליה עוד הלא חנוף תחנף הארץ ההיא ואת זנית רעים רבים וגו'. ולזה תהיה הכונה בזה שלא יוכל לשוב לקחתה אחר שיהיה אפשר לה שתבעל לבעלה השני והסבה בזה שאם היה מותר להחזירה אחר כן היה זה סבה אל שתמלא הארץ זמה כי מי שיחשוק אשת רעהו ישתדל עמו שיגרשהו ויקחה הוא ואת' עשותו חפצו ממנה יגרשנה וישיבנה לבעלה הראשון כדי שיתרצה בה כי אשו לא עשתה זמה בזה הפועל ולזה לא ירחיקה מפני זה ולזה התבאר שאם הפקירה עצמה אחר שגרשה מזולת קדושין לא נאסרה עלו כי אם ליראה שיגרשה לתכלית שתנשא עם האיש ההוא אוחר ישוב לקחתה בעלה הראשון כי זה מרוחק מאד אצל האנשים רוצה לומר לקיחת אשה מפקרת עצמה ומזה המקו' למדנו שהאשה שנטמאה בהיותה עם בעלה היא אסורה לו שהרי הוטמאה וכבר ביארנו זה עוד בפרש' נשא ממה שאמר ונקתה ונזרעה זרע:
@74 **כי יקח איש אשה חדשה.** למדנו שאם היתה אשתו וגרשה וחזר ונשאה לא ינהג בו זה הדין והרצון באמרו כי יקח נשואין שהרי אמר מי האיש אשר ארש אשה ולא לקחה ועתה מבואר מה יהיה דינו אם לקחה:
@74 **לא יצא בצבא.** רוצה לומר למלחמת הרשות כמו שביארנו באמרו מי האיש אשר ארש אשה:
@74 **ולא יעבור עליו לכל דבר.** רוצה לומר לא לצרכי הגדוד ולא לצרכי העיר אין מעמיסי' עליו שום מעמס:
@74 **נקי יחיה לביתו שנה אחת.** רוצה לומר שנה אחת מיום שנשאה והנה מפני שהתורה השותה דין לבונה הבית ולא חנכו ונוטע כרם ולא חללו ומארש אשה ולא לקחה ושנה גם כן בהשואת השלשה דברים האלו בדברי הקללות הנזכרות בפרשת והיה כי תבא למדנו שהכונה בית וחנכו והנוטע כרם ולא חללו יהיה גם כן נקי לביתו שנה אחת כי התור' ביארה כי לא ישלם הפיוס בזה הפועל לבעליו כי אם לשנה אחת ואמנם זכר זה בענין האשה בזה המקו' לפי שראוי לאדם שיהיה עם אשו בהתחלה באופן שיתפייס לבה בו ותאהבהו ויהיה זה סבה אל שלא תשנא עליו אח' כך ולא יצטרך לו לגרשה ולזאת הסבה צותה התור' שישמח עם אשתו אשר לקח בתתו לה חקה מעונתה:
@75 **לא יחבול ריחים ורכב וגו'.** הנה הריחים הוא אבן התחתון מכלי הטחינה ורכב הוא הכלי העליון והזהירה התורה שלא יקחם לאדם משכון על הלואתו ולא בשעה הלואה ולא אחר הלואה איך שיהיה שיהיו לו למשכון וביארה התורה טעם זאת האזהרה לפי שהעושה זה הוא חושב לקחת למשכון זה הכלי והוא לוקח למשכון נפש בעליו כי הוא משמש בעצמות להכין המזון להם אשר הוא שב להיו' חלק מבעל נפש ולפי הסבה בזה היא היותר משמשין להכנת מזון למדנו כי כל מה שישמש להכין המזון שאנחנו מוזהרים מלקיחתו למשכון ואפילו אם היו שם שני כלים משמשי' יחד לשמוש אחד חייב על זה בפני עצמו ועל זה בפני עצמו ולזה הוצרכה התורה להזכיר בפרט זאת האזהרה רחיים ורכב ללמדנו שהוא חייב על זה בפני עצמו ועל זה בפני עצמו כיון שיש בהם שמוש מה להכנת אכל נפש:
@76 **כי ימצא איש גונב נפש מאחיו מבני ישראל.** למדנו מאמרו גונב נפש שאפילו גונב קטן יתחייב עליו ובאמרו מאחיו מבני ישראל למדנו שאם לא היה מאחיו מבני ישראל כמו הענין בעבד כנעני ובגר תושב לא ינהג בו זה הדין ואף על פי שהיה העבד חציו בן חורין כמו העניין בשפחה חרופה כי אינו עדין מאחינו ולמדנו מאמרו גונב נפש מאחיו שאינו חייב עד שיגנבנו ויוציאנו מרשות אחיו פרט למי שלא יצא מרשות אחיו וחביריו שהוא עומד עמהם כמו האב שגנב את בנו והרב את תלמידו:
@76 **והתעמר בו ומכרו ומת הגנב ההוא.** ראוי שתדע שאין הכונה בזה שישתעבד בו או שימכרנו שהרי דקדק בפרשת ואלה המשפטים בשני אלו הדברים גם כן ואמר וגונב איש ומכרו ונמצא בידו קדם מכירתו אתו ועניין היותו בידו הוא שישתעבד בו אי זה שעבוד שיהיה שיורה שהו' תחת ידו כאלו הוא עבדו ובהיות הענין כן הנה לא יתחייב אם לא מכרו ונשתעבד בו קודם זה:
@76 **ומת הגנב ההוא.** רוצה לומר כישלמו בו כל אלו התנאים לא בזולת זה:
@77 **השמר בנגע צרעת.** הזהיר להשמר בענין נגע הצרעת לנהוג בו לפי מה שיתן הדין באופן שישב מחוץ למחנ' המצורע המוחלט ולא יעלי' איש את נגעיו מהראותם אל הכהן. ולא יחתוך סמני הצרעת כדי שיטהרנו הכהן כי זה ממה שיביא הפסד רב לאנשים ובעל הנגע לא ירגיש בענין הזיקו להם עד שיסורו מפני זה תועלו' רבות ימשכו ממה שסדרה התורה בנגע הצרעת כמו שביארנו בפרשת מצורע:
@78 **זכור את אשר עשה יי' אלהיך למרים.** אמר זה להעיר שאין ראוי לנטות ימין ושמאל ממה שצותה התורה מענין המצורע הלא תראה כי גם מרים עם גודל מעלתה ומעלת אחיה לא הסכים השם יתעלה להעביר לה מדיני צרעת דבר אבל הוכרחה להיותה נסגרת שבעת ימים עד שנתרפאה ואף על פי שנמשך מהסגרה עכוב ישראל כמו שאמר והעם לא נסע עד האסף מרים וסמך דבר מרים לענין הנגעים לבאר שהנגעים על לשון הרע וזולתו מן החטאים ולזה סמך דבר הנגעים לענין גונב נפש:
@79 **כי תשה ברעך משאת מאומה לא תבא אל ביתו לעבוט עבוטו.** הזהיר בזה המקום מי שיש לו מלוה על חבירו שלא יכנס לביתו למשכנו ולפי שזה לא יתכן אם לא על ידי שליח בית דין כי אין כח באדם למשכן חבירו על חובו אלא אם היה זה ברצונו ואולם לא יוכל לקחת משכון ממנו בעל כרחו אבל ראוי שיקראהו לפני בית דין והם יצוו לפרעו או למשכן הלוה הנה תכלול האזהרה הזאת גם כן שליח בית דין שאף על פי שיש לו כח להכריח הלוה לפרוע המלוה או ליתן לו המשכון הנה לא רצתה התורה שיכנס בביתו של לוה לבחור אי זה משכון יקח אבל יכריח הלוה להביא לו משכון מבחוץ לפי החוב ויקחהו שליח בית דין מידו אף על פי שלא מרצונו שאם היה הענין כן הנה לא יהיה כח לבית דין להכריח הלוה לפרוע המלוה והנה הדברים קל וחומר אם כשיתן הלוה ברצונו המשכון למלוה לא רצתה התורה שיכנס המלוה ברשותו לקחת משכונו כדי שלא יבוש המלוה אם לא יתן לו היותר טוב והיותר ראוי להפרע ממנו בקלות כל שכן כשימשכן אותו שליח בית דין בעל כרחו שראוי להשמר מלהכנס בבית הלוה למשכנו כי אין לאל יד הלוה לברוח ממה שירצה אותו שליח בית דין לקחת משכון:
@81 **ואם איש עני הוא לא תשכב בעבוטו.** הנה זה יהיה כשיהיה כסות לילה ואין הכונה בזה שלא ישתמש בעבוטו כי זה ממה שאין צריך להזהיר בו ואפילו אם היה עשיר ואמנם הרצן בזה שלא ישכב ועבוטו אצלו אבל יחוייב לו להביאו לו וביאר שבבא השמש משיבו לו את המשכון כדי שישכב בשמלתו והנה למדנו מזה שהוא הדין לכסות יום להחזירו לו ביום כדי שישתמש בו ביום ואולם דברה התורה בהווה לפי שהממשכן את חבירו ימשכנהו ביום על הרוב ואז לא יוכן לעני לתת לו כי אם כסות לילה והנה למדנו מזה שאם היה לעני במה ישכב זה המשכון לא יחוייב המלוה להשיבו לו ולפי שזה הדין הוא בזה המקום במי שלקחו משכון ממנו שלא בשעת הלואה למדנו שאם לוה על המשכון בתחילת ההלוואה אינו חייב להחזיר:
@82 **ולך תהיה צדקה.** רוצה לומר שהשם יחשבה לך לצדקה אם תשיב לעני כסות יום ביום וכסות לילה בלילה:
@83 **לא תעשוק שכיר עני ואביון.** ידוע כי התורה דברה בזה בהווה וזה כי אף על פי שהיה עשיר אין ראוי לעשוק שכירותו ואולם זכר עני ואביון כי החטא בו יותר עצום כאמרו וקרא עליך אל יי' והיה בך חטא:
@83 **מאחיך או מגרך.** זה גר צדק אשר בארצך בשעריך. רוצה לומר אשר הוא בארצך ובשעריך לבקש שכירותו ממך ולמדנו מזה שאם לא בקש לו שכירותו אינו עובר על איחור שכירותו:
@84 **ביומו תתן שכרו ולא תבא עליו השמש.** הנה במקום אחר אמ' לא תלין פעולת שכיר אתך עד בקר למדנו ששכיר יום גובה כל הילה שנאמ' עד הבקר ואחר זה עובר עליו ושכיר לילה גובה כל היום שנאמר ביומו תתן שכרו ולא הבא עליו השמש ולמדנו מזה שאם היה שכיר לזמן רב ונשלמה פעולת שכירתו ביום גובה כל הלילה שנאמר ולא תלין פעולת שכיר עד השלימו כל פעולתו ששכרו עליה אינו עובר ואז יש לו כל הלילה אם השלים ביום ואם השלים בלילה יש לו כל היום עד בא השמש:
@84 **כי עני הוא ואליו הוא נושא את נפשו.** רוצה לומר כי אל השכירות ההוא נושא נפשו כי ממנו הוא מתפרנס ומחיה עצמו ואם לא תפרעהו בזמנו יקרא עליך אל יי' ויביא עליך עונש חזק על אחורך לעני מזונותיך כי משכירותו הוא מתפרנס וזה שזכר בסוף אינו כי אם בעני כי העשיר אינו מחיר כל לגבות שכירותו ולא תחסר פרנסתו מפני האחור הזה:
@85 **לא יומתו אבות על בנים ובנים לא יומתו על אבות.** בארו רבותינו זה המאמר בעדות הקרובים כדי להשמר מההכפל. שהרי אמר אחר זה איש בחטאו יומתו והנראה מפשט הכתוב שהוא בא להזהיר הדיינים שלא ישפטו למות האבות בעבור חטא הבנים ולא הבנים בעבור חטא אביהם אבל איש בחטאו לבד ואולם דבר עדות הקרובים יתבאר ממה שנזכר ברוצח מענין גואל הדם שמצד רתיחתו ירצה עכ"פ להמית הרוצח אף על פי שאין לו חטא מות ולזה הוא כמו בעל דבר וכמו שבעבור אהבת קרוביו והיותו עצמו ובשר שלו יפותה להמית מי שאין לו חטא כן יפותה להעיד לו עדות אף על פי שאינו אמת ולפי שהגואל לא יעבור שני בשני כמו שבארה התורה בפרשת בהר סיני. או דודו או בן דודו יגאלנו. והנה בן דודו שני בשני הנה אינו נפסל מהקרובים לעדות כי אם שני בשני ועוד שכמו שפסלה התורה הרשע והחמסן לעדות לפי שאנחנו רואים אותם נוטים מדרכי התורה ולזה נחשוד אותם שאולי לסבת ממון או אהבה לא יחוש להעיר שקר כל שכן שנחשוד הקרובים כי כמעט שטבע הקורבה ימשכם לעזור לקרובים להשים מבקשו כי טבע האד' הוא להיות בלתי מתעלם מבשרו והנה תעמוד על זה בחוש מהריב המתחדש בין אנשים אפילו בממון שתמצא הקרובים נקשרים לאגודה אחת לעזור לקרובים אם במשפט אם בכח והנה כמו שהדיינין ראוי שיהיו בלתי נוטים בטבעם לאהבת החלק האחד יותר מהאחר כמו שביארנו בפרשת יתרו כן ראוי שימשך ענין בעדים כי על פיהם יצא מה שיצא מהמשפט כי אם אין עדים אין דיינין והנה הוצרכה התורה לצוות שלא יומתו אבות על בנים לפי שכבר זכרה כי השם יתעלה פוקד עון אבות על בנים ואולי יחשבו הדיינין לעשות דבר ראוי אם ילכו בדרכי השם יתעלה וכן שכן שבארה התורה בעיר הנידחת שימותו בה בנים על אבות ולזה הזהירה התורה מזה בזה המקום וכאלו אמר שאף על פי שזכר בכאן שאם יקרא העני אל יי' יהיה בשוכר עונש מהשם יתעלה הנה אין ראוי לשפטים שילמדו מזה ויענשו הכובש שכר שכיר שלא לפרוע בזמנו כמו שהשם יתעלה עונש אותו:
@86 **לא תטה משפט גר יתום.** רוצה לומר גר צדק ויתום והזהיר עליה מלהנות משפטם כי לשפלותם אולי לא יזהר הדיין מלהטות משפטם כי אין בשער עזרתם ולזה הוסיף זאת האזהרה לדין עליהם:
@86 **ולא תחבול בגד אלמנה.** בין עניה בין עשירה ואפילו ברצונה ואפילו בשעת הלואה אם לקח המשכון ממנה חייב להחזירו לה והנה חמלה עליה לשפלותה ולדאבונה עם שזה יביא לפעמי' לידי זמה במה שימשך מזה מחייוב השבת משכונה של יו ביום ושל לילה בלילה:
@87 **וזכרת כי עבד היית במצרים ויפרך ה' אלהיך משם.** ולזה אתה עובד הש"י ותחוייב לעשות מקניניך מה שירצה כי אתה וקניניך לו:
@88 **כי תקצו' קצירך בשדה.** כי תקצו' כולל אם קצרה הוא או שלוחו אבל אם קצרוה לסטים או קרסמוה נמלים ומה שידמה לזה לא ינהג בקציר הדין הנזכר. קצירך לא קציר הקדש ולא קציר גוים ולא קציר הפקר:
@88 **בשדך.** פרט לשפזרה הרוח את עמריו בשדה אחר כי אע"פ ששכחם שם אינו שכחה:
@88 **ושכחת עומר בשדה.** ושכחת עומר ולא גדיש והנה דרך העומר להיות עושה פחות מסאתים לפי הוראת הגדר ולזה אם יהיו בו סאתים אינו שכחה:
@88 **ושכחת עומר בשדה.** ושכחת עומר ולא גדיש והנה דרך העומר להיות עושה פחות מסאתים לפי הוראת הגדר ולזה אם יהיו בו סאתים אינו שכחה:
@88 **ושכחת עומר בשדה.** ראוי שיהיה נשכח בשדה אבל אם נשכח בעיר כיון שאינו נשכח בשדה אינו שכחה וענין השכחה הזאת הוא במה שדרכו לשכח כמו שאין שם בשדה מי שרואה אותו בעת שאתה שוכחו. אבל אם יש שם רואה אין ראוי לשכחו כי מדרך האנשים שיזכירו קצתם לקצת מה שהם רואים. ורואי שתדע ששכחת הפועלים שם כמו שכחת בעל הבית כי הם שם במקומו וגם על ידיה' נעשה הלקט שהוא לעניים כמו שקדם ולפי שאמר עומר ידענו שאם לא היו האגודות באופן שיקראו עומר לקטנותם הנה אין השכחה נוהגת בהם ולפי שאמר כי תקצור קצירך בשדה אצל זכירתו שכחת העומר למדנו מזה שני דברים האחד שיש שכחה ג"כ בקצירת הקמה וכבר נתבאר זה עוד ממה שאמרה התורה אחר זה לא תפאר אחריך לא תעולל אחריך והנה מה שעזב אחרי הואר שכחה למדנו שהשכחה נוהגת במחובר ולזה תהיה נוהגת בקמה ויוגבל שעורה מהשיעור המוגבל לעומר והשני שהוא שיהיה בעת הקצירה קצירך ואז יהיה נוהג בו דין השכחה אמנם אם בשעת קצירה אינו קצירך בדרך שאינו אז מחוייב בפיאה הנה לא ינהג בו אחר זה דין השכחה והוא מבואר שהשכוח בשדה אע"פ שזכר אותו אחר זה הוא לעניים שהרי הזהירה התורה ואמרה לא תשוב לקחתו והנה ענין השכחה הוא שישכח העומר או הקמה במקום שלא תכריחהו מלאכתו לשוב אצלו להיותו כמו גמר מלאכה אצל המקום ההוא ואפילו היה טמון שם או שקצר בלילה או אסף העמרים בלילה ולפי שאמר כי תקצור למדנו שבמה שראוי לקצור לפי הנהוג ינהג דין השכחה לא במה שאינו ראוי לקצור כמו התבואה שקצרה קודם שנגמרה להאכילה לבהמה:
@88 **לא תשוב לקחתו.** הזהיר מלקיחתו אחר זה אע"פ שזכרו:
@88 **לגר וליתום ולאלמנה יהיה.** מגיד שאם לקחו יחויב לתתו לעניי' והנה זה הגר הנזכר פה הוא גר צדק והיתום והאלמנה וכן ראוי לשאר עניים אך דברה תורה בהווה והראייה על זה שהרי אמר בפרש' בהר סיני תמורת זה המאמר לעני ולגר תעזוב אותם למדנו עוד מאמרו לגר וליתום ולאלמנה יהיה שראוי לעשו' בדרך שתהיה יד העניים שוה בזה ולזה לא ימנע קצת העניים מלהכנס שמה ויניח קצתם להכנס שם ומה שדומה לזה ממה שיסבב אם לא יכנסו העניי' שם או שיכנסו קצתם זולת קצת ולמדנו מאמרו לגר ליתום ולאלמנה יהיה בזמן ההוא מוכן לחיו' לגר ליתום ולאלמנה ר"ל עניי' אז הוא מוזהר שלא לשוב לקחתו לא בזמן שאינו מוכן להיות להם והוא בשעת סור העניים מלחזר אחר אלו העניים הדברים בשדות כי התורה אמרה לגר ליתום לאלמנה יהיה שאע"פ שעבר ולקחו בעל הבית חייב להחזירה לעניים בגורן או בקמה או בפת:
@88 **למען יברכך יי' אלהיך בכל משלח ידיך.** מגיד שבשכר זה יברכך השם יתע' להוסיף על תבואתך כי כמו שתחנן העניים יחנך השם יתעלה. למען תתן להם. כי הוא נותן לחם לכל בשר וישימך כלי לנתינת המזון לעניים אשר ישפיעהו הש' ית' עליהם מצד ההשגחה הכולל:
@89 **כי תחבוט זיתיך לא תפאר אחריך.** ר"ל שמה שישכח מפארות הזית לחבוט ויתיחס אינו חוזר אחר זה כשזכר אותו לעיין בפארות לחבטם והנה אם היה קצת הזית שכוח נשער אם יש בו סאתים אינו שכחה כי כמו זה השעור אין מדרכו שישכח ואם היה שדה לאילן שיהיו בו אילנות רבות ושכח אילן מהם שלא חבט פירותיו הרי זו שכחה כיון שעבר ממנו אם לא היה אצלו מה שראוי שיביאהו לזכרו מצד עוצם המלאכה ואם שכח ג' אילנות במקום אחד אין זו שכחה כי כמו זה לא יורגל לשכחו בעת לקיטת הפירות מהאילנות וכן אם היה שם אילן אחד חשוב אשר לחשיבותו נקרא בשם מיוחד ושכחו כלו אינו שכחה כי חשיבותו יביאהו לזכרו ולזה אינו ראוי שישכח:
@89 **לגר ליתום ולאלמנה יהיה.** כבר פירשנוהו במה שקדם ואולם מה שראוי להוסיף בו ביאור בזה המקום הוא שאם היה האילן גבוה שלא יוכלו העניים לעלות עליו אם לא בסכנה או יעלו שם קצתם זולת קצת ראוי לבעל הבית לעשות באופן שתהיה השכחה לגר ליתום ולאלמנה:
@90 **כי תבצור כרמך לא תעולל אחריך.** הזהיר בזה המקום שמה ששכח מבצירת הכרם אחריו לא ישוב לקחתו ולזה אמר אחריך ואמר ולא תעולל דבר בהוה כי יונקות הגפנים הם היותר ראויות להשכח כמו שאמר באילן לא תפאר לפי שהפארה היא יותר ראויה שתשכח מהאילן כלו וכבר זכרנו דין השכחה באילנות וכן דינה בכרם:
@91 **וזכרת כי עבד היית בארץ מצרי'.** ר"ל ולזה אתה וקנייניך לשם יתעלה ותחוייב לעשות מקנייניך מה שירצה כי הוא הוציאך מהעבדות ההוא:
@92 **כי יהיה ריב בין אנשים וגומ'.** חייבה התורה טוען ונטען לבא לפני בית דין והם ישפטו אותם בעל כרחם:
@92 **והצדיקו או הצדיק והרשיעו את הרשע.** מגיד שהוא מחוייב שיהיו השופטים בתכונת שיצדיקו את הצדיק והרשיעו את הרשע בדרך שלא יטו המשפט ואמר אחר זה והיה אם כן הכות הרשע להגיד שכמו שהם מוזהרים להרשיע הרשע בממון שלא יטו הדין כן הוזהרו להרשיע הרשע למכות כי אולי יחשבו שאינם עושי' בזה עול לשום אדם ויעלימו מפני זה עיניהם מלענשו במלקות והנה הרשע יקרא מי שעבר על מצו' לא תעשה שאין בהם מיתת בית דין ולא עונש ממון כי לא מצאנו במצות עשה לבלי מקיים עונש בידי אדם ולזה סמך לזה אמרו לא תחסום שור בדישו שהוא מצות עשה שלא הוזכר עונש וכמו שזאת העבירה יש בו מעשה כן כל לא תעשה שיש בו מעשה וכן מצאנו שדקדקה התורה שיהיה מעשה במה שחייבה על שגגתו חטאת וכן יתבאר שמה שנתקו התורה לעשה לא יהיה בו מלקות כי לא עבר על לא תעשה עדין עד שיבטל העשה שבו ולזה אינו רשע עדין:
@93 **והפילו השופט והכהו לפניו כדי רשעתו במספר.** מגיד שאינו מוכה אלא כשהוא נופל ולפי שאמר והכהו למדנו שההכאה צריך שיהיה בו בעצמו לא בבגדיו ולזה צריך שיגלה המקום שהכהו בו ולפי שאין ראוי שיתבייש לפני בית דין לגלות עדותו הנה ראוי שיגלו לבו וסביבו יכו עם שההכאה ההיא היא בכלו כי הלב הוא השורש וההתחלה לכללות הגוף וצריך שיכו אותו לפני השופט שיהיו עיניו בהכאות ההם כדי שלא יעבור המלקה אותו החק שהגביל עם שהוא יראה אם לא יוכל לסבול המוכה כל ההכאות ההם ויצוה למנוע מלהכותו כל המספר שהגביל וראוי שתדע שראוי שיהיה אומר מספר מהמכות שיוסר בו ולא יתכן שימות בו כי התורה לא חייבה באלה העבירות ואן ראוי לדיין להוסיף עונש על מה שחייבה התורה כל שכן בכמו זה האופן ואמר כדי רשעתו לבאר שאינו מכה אותו יחד על רשעיות אבל על רשע אחד ולמדנו מזה שמרבים מספר המכות או ממעטין כדי שיהיה במספר ההוא מהמכות כדי ליסרו לפי חולשתו או לפי חוזקו אך שלא יוסיף המספר המוגבל אחר זה וכבר ביארנו כדי רשעתו בזה האופן לפי שאין ראוי שיובן כי לפי גודל החטא ירבה מספר המכות כי כמו שכל חייבי מיתה מה יהיה עונשן שוה אף על פי שבקצתם החטא יותר עצום מקצת כן ראוי שנבין הענין בזה המקום עם שזה האומר לא יתכן שישלם לאחד מהשופטים כי זה דבר בתכלית מההעלם ר"ל היחס שבין קצת החטאים לקצת והיא ראוי אם כן שתבאר התורה מספר המכות באזהרה ואזהרה כמו שביארה מיני המיתות ואמר במספר לבאר שהוא מחוייב שיהיה שם מי שימנה מספר המכות כדי שלא יוסיפו עליהם וזה ג"כ דבר ראוי שימנ' על ידי שופט כמו שדקדקה התורה שיהיה רואה צורת ההכאות וזה לא ישלם בשלמות כי אם על ידי ב' שופטים אחד מעיין בהכאות ואח' מונה ולפי שאין ב"ד שקול הנה יהיו שם ג' שופטים:
@94 **ארבעים יכנו לא יוסיף.** ידוע שאין כונת התורה לצוות שיכנו ארבעים לא פחות שהרי אמרה קודם זה והכהו לפניו כדי רשעתו מגיד שזאת ההכאה תהיה מתחלפת המספר באנשים ואם היה החיוב להכות ארבעים לא פחות וכבר חייב ג"כ שלא יוסיף על זה המספר הנה לא יהיה מספר ההכאות מתחלף לפי די מוסר הרשע וזה הפך מה שזכרה התורה מזה ולזה ראוי שנבין שאמרו מ' יכנו הרצון בו עד מ' יכנו וכמוהו רבי' בתורה ובדברי נביאים כמו שזכר במה שקדם ולפי שאמרו עד מ' יכנו יסבול שיהיה עד בכלל או לא יהיה עד בכלל הנה יחוייב מפני הספק שלא נכהו יותר מל"ט הכאות ואם אמר אומר כי הכונה אפשר שתהיה בזה שהוא מחוייב שיכנו מ' לכל הפחות אך יוסיפו הדיינים להכותו כדי רשעתו ויהיה אמרו לא יוסיף שב אל המספר שאמדוהו והדיינים. התשובה הנה לפי זה הדעת לא היה ראוי שיאמר פן יוסיף להכותו על אלה כי לא זכר המספר ההוא ישתכן שיאמ' אלה ועוד שאם הודינו שהדבר ספק הנה מפני הספק ראוי שנשפט בו להקל למוכה כדי שנשאר מלהטיל עליו מהעונש יותר למה שהגבילה אותו התורה. לא יוסיף ר"ל שלא יוסי' המכה להכותו על האומד שאמדוהו ב"ד:
@94 **פן יוסיף להכותו על אלה מכה רבה ונקלה אחיך לעיניך.** ר"ל אם היה אפשר למכה להוסיף על האומד ההוא הנה לפעמים יקרה שיוסיף להכות על אלה הל"ט שהגבלנו בתורה שהם מכה ורבה ויקרה מזה למוכה מצד החולשה שיתקלקל ברעי או בשתן לפני הדיין ויקבל בזה קלון חזק וכדי שלא יבא זה לקלון השגיחה התורה אל שלא יהיה מספ' ההכאות כי אם עד מ' ויהיה כח לדיינים לגרוע מזה המספר מצד חולשתו כדי שלא יקרה לו כמו זה הבשת ומזה המקום למדנו שאחר שאמדוהו ב"ד למספר מה מהמכות אין ראוי להוסיף עליהם ולמדנו עוד שצריך שיזהרו הדיינים שלא יהיה נקלה ולזה אם אמדוהו למספר מה והתחילו להכותו וראו שאם ישלימו להכותו המספר ההוא ימות או יבא לידי קלון הרי הם מחוייבים לאמדו שנית לפי מה שראוי מצד מה שנתבאר להם מחלשתו ולמדנו מזה עוד שאם התחילו להכותו ונקלה בזה האופן אין מכין אותו יותר ואפילו נקלה מהפחד פטור ואין מכין אותו כי התורה ברחה מהקלותו כי הוא יותר קשה אצל התורה מהמכות ולפי שאמר כדי רשעתו למדנו שאחר שלקה הוסרה רשעתו ואינו רשע אחר שקבל המוסר ולזה ג"כ קראו אחיך אחר לקותו שנאמר ונקלה אחיך והנה מפני שזכרה התורה שכבר יתכן שיוכה עד המ' מכות מזולת שיהיה נקלה למדנו שאין ראוי שתהיינה המכות האלה מכות רב או אבן או אגרוף ולא מכת שבט כי כן יתכן המות כמו שזכרה התורה בפרשת ואלה המשפטים בעבד כנעני ולזה יחוייב שתהיה ההכאה שיהיה ראוי בה לקיחת המוסר. ולזה יהיה בה סכנה בכמו המספר הזה כמו שימצא העניין בזה ברצועת עור ולפי שההכאות יחוייב שתהיינה בגופו אצל לבו שתהיה ההכאה כוללת כל גופו הנה יחולק זה המספר השלוש מלפניו על לבו בין שדיו ושני השלישים אצל שתי כתפיו מאחוריו כי הם אצל הלב כי הלב מוטה מהשמאל אל הימין וזה כלו להקל הלוקה כי אם תהיינה כל הכאות לפניו אצל לבו אולי ימות ולזה ידמה ג"כ שזכרה התורה מספר מכות ראויות להשתלש. ומזה המקום למדנ שהמכה את חבירו עובר בלא תעשה שהרי אף במי שיש רשות להכותו הזהירה התורה מלהכותו יותר ממה שהוגבל כ"ש בשאר האנשים:
@95 **לא תחסום שור בדישו.** הזהיר בכאן מחסימת פה הבהמה מלאכול בשעת מלאכתה ממה היא עושה מגדולי קרקע בין בתלוש בין במחובר. והנה לא זכרה התורה שור ולא דישה אלא שדברה התורה בהווה והנה הכונה להרחיק מדות האכזריות ולזה צותה התורה שלא למנוע עושה המלאכה מאכילת מה שהוא עושה בו ולזה אם חסמה קודם שתהיה חסומה בעת הדישה או חסמה בעת הדישה עובר על זאת האזהרה ואיך שמנעה מלאכל ממה שהיא עושה אם בהכאה או בפחד הכאה אם בקול הרי זה עובר על זאת האזהרה:
@96 **כי ישבו אחים יחדיו ומת אחד מהם ובן אין לו.** ראוי שתדע שאלו האחים יחוייב שיהיו אחים מן האב כי לא ישאיר שם האח מי שהוא אחיו מן האם כי המשפח' מיוחסת אל האב לבד כמו שנתבאר במקומות רבים מהתורה ועוד כי דרך האחים מן האב להיות יושבים יחדיו לא האחים מן האם כי כל אחד יושב עם משפחת בית אביו ולמדנו מאמרו כי ישבו אחים יחדיו שאם לא היתה להם ישיבה יחדיו כמו שמת הראשון קודם שנולד השני הנה לא ינהג בהם זה הדין:
@96 **ובן אין לו.** ר"ל בשום מקום ולזה צריך לחקור אף על פי שאין לו בן מזאת אם יש לו בן מאשה אחרת שהוא הדין ראוי שיקרא בנו להוציא את שנא משפחה ונכרי שאינו בן אלא בנה ולזה הוא מבואר שאם היה לו בן בשום מקום לא ינהג בו זה הדין ואחד בן ואחת בת כי התורה לא השגיחה אלא שלא ימחה שמו מישראל ומי שיש לו בת לא ימחה שמו בישראל והנה נאמן האב לומר זה בני לפטור את אשו מן היבום ומן החליצה והנה ראוי שתמתין היבמה שלש חדשים כדי שיודע אם בן אין לו ממנה שאז יוכר אם היא מעוברתם:
@96 **לא תהיה אשת המת החוצה לאיש זר.** הזהיר שלא יקח אשת המת איש אחר זולתי יבמה שהוא אחי בעלה מן האב כמו שקדם ופי שאמ' אשת המת והיא תקרא אשתו מן הארוסין כאמרו בנער' המאורסה על דבר אשר ענה את אשת רעהו ולפי שאמר אחר זה יבמה יבא עליה ויבמה למדנו שאין הזר עובר בלא תעשה עד שיבא עליה כי הרצון בזה יבמה יבא עליה לאיש זר ולזה יהיה הרצון באמרו לא תהיה אשת המת החוצה לאיש זר לא תהיה לו לאשה באופן שיבעלוה אך יבמה לבד יבא עליה יבמה יבא עליה ולקחת לו לאשה ויבמה. לפי שאמר יבא עליה ולקחה לו לאשה למדנו שכיון שבא עליה איך שיהיה קנאה לו לאשה. אך לפי שאין הביאה נעשית אלא כשיכוין לביאה הנה ראוי שתהיה כונתו לביאה ואף על פי שלא תהיה כונתו לבא עליה והנה זה הפועל נקרא ייבום:
@97 **והיה הבכור אשר תלד יקום על שם אחיו המת.** רוצה לומר הראשון שתלד יוקם בו זרע למת כי כבר יחסוהו לו כמו שאמר על רות המואביה שילדה לבועז בן יולד בן לנעמי כאלו היתה מבנה שהוא הבעל הראשון לרות אך יקרא בשמו להתיחס לו למשפחה הלא תראה שיהודה שביאתו על תמר היה כמו היבום ולא נתיחסו הבנים לער ואונן ול נקראו בשמם ולפי שאמר אשר תלד למדנו שאם אינה ראויה לילד לא ינהג בה זה הדין וכן אם הוא אינו ראוי להוליד כי לא יתכן שיאמ' בו כשייבם אותה והיה הבכור אשר תלד:
@97 **ולא ימחה שמו מישראל.** וזה גם כן מורה שאם היה סריס אינו נוהג בו זה הדין שהרי אין יבומו כלי אל שלא ימחה שמו מישראל שהרי אי אפשר לו להוליד. ולפי שאין הכונה בזה אלא כדי שלא ימחה שם אחיו מישראל למדנו שאינו מייבם אלא לאחת ואע"פ שהיו למת נשים רבות:
@98 **ואם לא יחפוץ האיש לקחת את יבמתו.** למדנו מזה שאם היתה יבמתו באופן שהתורה תמנעהו ממנה כאלו תאמר שהיתה ערוה עליו לא ינהג בה זה הדין כי הא במה שאין בו מונע אלא רצונו יצתה זו שהתור' מונעת אותה ולפי שאינו מייבם אלא לאחת והיתה האחרת בלי ראויה לחליצה וליבום הנה השאר פטורות מזה ג"כ לפי שראוי שאיזו מהם שירצה ליבם יהיה הרשות בידו כי התורה אמרה אשת המת וזה המאמר שב לכל אחת מנשיו כי כל אחת מהם היא אשת המת ולזה ראוי שתהיה כל אחת מהם ראויה לבא עליה יבמה או לא ינהג בה זה הדין והוא מבואר במה שאין ספק בו כי כשלא היה לו בה לקוחין כמו הערוה לא ינהג בה חליצה ויבום שנ' יבא עליה וגו' מי שיש לו בה לוקחים ואולם מי שהוא מוזהר מלקיחתה כמו אלמנה לכהן גדול וגרושה לכהן הדיוט היא בת ייבום וחליצה כי התורה צותה שיקחה לו לאשה ולזה סר ממנו אסור הלאו כי עשה דוחה את לא תעשה:
@98 **ועלתה יבמתו אל השערה את הזקנים.** מגיד שהיבמה באה אצל היבם להתירה כי אלו הזקנים הם זקני עיו ואמרה מאן יבמי וגו' אלו הדברים צריך שתאמרם בלשון הקדש:
@99 **וקראו לו זקעי עירו ודברו אליו.** מגיד שהם צריכים לדבר לו לתת לו עצה ההוגנת לו:
@99 **ועמד ואמר לא חפצתי לקחתה.** צריך שיאמר זה בלשון הקדש:
@100 **ונגשה יבמתו אליו לעיני הזקנים וחלצה נעלו מעל רגלו.** מגיד שצריך שיראו זה הפועל הזקנים והנה התבאר מהשרשים הוללים שה יהיה ברגלו הימני וצריך שיהיה נעל של עור כי זה הוא הנהוג בו ושיהיה לו עקב וצריך שתחלוץ היא לא שיעזור לה בה ושתהיה חולצת מעל רגלו שהוא המקום אשר הוא קשור בו לפי הנהוג לא מעל ארכובתו כי אין זה מעל רגלו הקדי' תחלה שיאמר' אלו הדברים שמורים שהם רוצים להפרד בו זה מזה להורות שצריך שתעשה החליצה לשמה ויתכונו הוא והיא בה שתהיה להסיר הזיקה שיש ביניהם:
@100 **וירקה בפניו.** מזה המקום למדנו שצריך שלא יהיה היבם סומא כי הוא אינו רואה הרוק והתורה כונה שיראה הרוק לביישו וכאלו היא רוקקת מצד מיאוסה אותו ואין הרצון בו שתרוק בו בעצמו כי אין זה מן הראוי אך כמנהג המאוס שרוקקין בראותם אותו כאמרו מפני לא חשבו רוק וצריך שתהיה הרקיק' לפי הנהוג ממנה לא שתרוק דם ולא שתרוק בסבת מאכלים מרבים הורק אבל מעצמה שנ' וירקה:
@100 **וענתה ואמרה ככה יעשה לאיש וגו' ונקרא שמו בישראל בית חלוץ הנעל.** הנה תאמר זה בלשון הקדש ותאמ' זה להעיר שכבר עשתה זה הפועל מהחליצ' לתכלית שתסור זיקתה ממנו ולפי שאמ' בית חלוץ הנעל למדנו שהחליצה לבד היא המעכבת ולזה הוא מבואר שאם חלצה אע"פ שלא קראה ולא רקתה חליצתה כשרה כיון שהיתה לשמה כי אלו הדברים נראה מעניינם שלא חייבה התורה בקריאתם כי אם לתכלית מה שיתבאר שהחליצה היא לשמה:
@102 **כי ינצו אנשים יחדו איש ואחיו.** ולא עבד או גר ותושב ר"ל שאם החזיקה אשת הישראלי במבושיו אין קוצצין כפה להצילו מידה:
@102 **להציל את אישה מיד מכהו.** ולא מיד מכהו נפש כי אז ההותר לה להצל בעלה אפי' בנפשו של מכה אותו כמו שקדם:
@102 **והחזיקה במבושיו.** הוא מקום שיש סכנת נפשות והוא הדין לשאר המקומות שיש בהם סכנת נפשות ולזה יצילהו מידה בעת החזקתה במבושיו בקציצת כפה אם לא יוכלו להצילו בזולת ה:
@103 **לא תחוס עיניך.** הזהיר מלחוס על הרודף ואפי' היה בה התואר שיש לו קצת התנצלות לפי מה שיחשוב ואולם אין זה התנצלות לפי שלא היו מכין זה את זה מכת נפש ולזה לא הותר לה להרוג המכה את אישה:
@104 **לא יהיה לך בכיסך אבן ואבן גדולה וקטנה.** ר"ל שהמשקל דאחד בעצמו לא יהיה לו אחד גדול ואחד קטן כאלו תאמר שיהיה המשקל שהוא ליטרא לו אחד גדול ואחד קטן לקנות באחד ולמכור באחר ואמר לא יהיה לך להעיר שאפילו לא שקל בו אלא קיימו עובד בזאת האזהרה:
@105 **לא יהיה לך בביתך איפה ואיפה גדולה וקטנה.** ר"ל שהסאה דרך משל לא יהיה לו ממנה שנים אחת גדולה ואחת קטנה כי מאלו הדברים ימצא עול לקנות בזו ולמכור בזו:
@106 **אבן שלמה וצדק יהיה לך.** ר"ל משקל שלם וצדק שלא יהיה נוסף על השיעור הראוי וכאלו אמר שלא יהיה חסר ולא יהיה נוסף וזה יכלול ג"כ שיהיה הצדק והיושר בדבר המשקל שנכריע המשקל כפי מה שנהוג ושלא יהיה עול במאזנים אשר ישקול בהם:
@106 **איפה שלמה וצדק.** ר"ל מדה שלמה שלא תהיה חסרה ולא יתירה ושיהיה הצדק במחיקת' או בגדישתה ובכלי המחיקה:
@106 **למען יאריכון ימיך.** מגיד שההתנהג בצדק וביושר מביא ישראל להאריך ימיהם על הארץ:
@107 **כי תועבת יי' אלהיך כל עושה עול.** מגיד שבאי זה דרך שיהיה אין ראוי שיעשו עול ולזה יתבאר מזה שאסור לעשות שום עול במסחר ולזה יהיה אסור לערב פירות בפירות כי בזה האופן יעשו עול הסוחרים כשיערבו מעט מן הרעות ביפות כי לא ירגישו בהם הקונים וכן הענין בשאר מה שימשך ממנו אי זה עול שיהיה קטן או גדול:
@108 **זכור את אשר עשה לך עמלק בדרך בצאתכם ממצרי'.** צוה לזכור תמיד הרע שדמה לעשו' לנו עמלק ברפידים בצאתינו ממצרים והנה מן הדומה שהוא עורר אז המלחמה לראותו ישראל בתכלית החולשה עם שידמה ממה שנזכר בזה המקום שהגידו חכמיו שהוא ינצח ישראל אז מצד המערכת ושאין ישראל ראויין עדיין אל הברכה אשר ברך יצחק את יעקב אשר היא מפאת ההשגחה הפרטית ולזה נמצא להם אז לכלות ישראל ותסור מהם הקללה שנתקללו להיות עובדים ליעקב כי עמלק היה מבני עשו כמו שנזכר בסוף פרשת וישלח יעקב והנה על עומק מחשבתם זאת לכלות ישראל קודם שיהיו ראויים לזאת ההשגחה צוה השם לכלותם כמו שצוה להכות את המדיני' על עומק מחשבת' להסיר מישר' ההשגחה האלהית הפרטית כדי לכלותם באמרו כי צוררי' הם לכם בנכליהם אשר נכלו לכם על דבר פעור ועל דבר כזבי:
@109 **אשר קרך ברך.** ר"ל שהוא הזמין עצמו להלחם עמך בדרך לחשבו שאתה שם בזולת מלחמה עם היותך גם כן עיף ויגע ולא היית גם כן אז ירא אלהים בדרך שתדבק בך ההשגחה הפרטית והנה לולי תפילת משה כבר היו עמלק מנצחים כמו שביארנו שם וזה לאות שלפי המערכת היה שינצח עמלק:
@109 **ויזנב בך כל הנחשלים אחריך.** ר"ל שהרג הזנב שבהם והם כל החלושים שיהיו הולכים בזנב המחנה לחולשתם ולזה הוא מבואר שעמלק קבץ כאן כל הסגית שישלם בהם כלוי ישראל האחת עוררו מלחמה לישראל בדרך שלא נשמרו מזה קודם להחלץ בכלי המלחמה ובזה האופן הרג כל החלושים שיהיו בסוף המחנה כי לא נשארו מהם. והשנית שמצאם יגיעים ועיפים מטורח הדרך והשלישית שעדיין לא דבקה בישראל ההשגחה הפרטית כי אז לא היה ישראל ירא אלהים כמו שנראה מהריב שהריבו ישראל שם ונסו השם ית' כמו שנזכר שם והרביעית מצד הדבק ההשגחה הכללית בעמלק לנצח ישראל ולהתחבר כל אלו הסיבות במה שלא ימלטו מידו שלא יכלם ויסורו מעליו ומעל שני בני עשו הקללות שנתקלל עשו בעבור ברכת יעקב ולזה צוה השם יתעלה שאחר שישלימו מלחמות שבעת גוים יניח יי' לישראל מכל אויביהם מסביב ימחו את זכר עמלק לשערו מה שישתדל זה העם להרע לישראל בכל דור כי כשיהיה לאל ידם וכבר תעמוד על זה ממה שתמצא בימי השופטים מצקלג עיר דוד כי זה יורה היותם פונים תמיד להרע לישראל כשיהיה לאל ידם ומה שדמה לעשות המן בן המדתא האגגי לישראל בימי מרדכי ואסתר לולי יי' שהיה להם היה מכלה אותם:
@110 **לא תשכח.** הזהיר אותם מלשכח בלב מה שעשה להם עמלק. הנה זה ביאור מה שנראה לנו שהוא צריך בזאת הפרשה.

@1 **כי תצא למלחמה על אויביך וגו' עד כי יקרא קן צפור לפניך.**
@1 **ואולם התועלות המגיעות ממנה הם תשעה:**
@1 **התועלת** הראשון הוא במצות והוא להתנהג ביפת תואר המנהג שהגבילה אותה התורה והנה התועלת בזאת המצוה הוא לתת מקום ליצר הרע כשיגבר על האדם שתתקרר רתיחתו ותשקוט כי אם לא היתה התורה מתרת לו זה העניין בזה האופן כבר היה נכשל בה גם כן והשתדלה התורה עם זאת למנעו מזאת התאוה לפי מה שאפשר ולזה צוה לנוולה כדי שלא יחשוק בה עוד והזהיר מלמכרה אחר ענותו אותה ומלהתעמר בה כדי שימנע מלבא עליה כדי שלא יפסיד הממשלה שיש לו בה בהשבותו אותה. והנה סמך אל הפרשה ההיא מה שיביא להתרחק מעניין נשואי יפת תואר כי לא יתכנו לו כל אלו הדינים שיוכל לקיימם באופן שהגבילה אותה התורה שלא יפול בזה אי זה נמנע להתקיימה כולם שהותר לו לבעלה ולזה ימנע בתחילה בלקיחתה וזה כי כבר ביאר אחר זה שסופה להיות שנואה לו מפני שלא חשק בה אלא מפני יפיה ואולם מעשיה יהיו מגונים מפני מה שגדלה עליו מהפעולות המגונות ולזה ראוי שתהיה שנואה לו. וסמך לזה דבר בן סורר ומורה להודיע שהזרע שיצא ממנה סופו להיות סורר ומורה וסופר להיות מגדף או עובד ע"ז ולזה סמך אליה פרשת וכי יהיה איש חטא משפט מות והומת:
@1 **התועלת** השני הוא במצות והוא מה שצוה שלא להעביר נחלה מהאחד מהאחים ולתתה לאחר ואף על פי שהיה אשר העביר הנחלה ממנו בן השנואה ואולם הוצרכה התורה להזהיר זו בשתי נשי' האחת אהובה והאחת שנואה כדי שלא יטול דין הבכורה מהבכורה בן השנואה ויתנה לבן האהובה לפי שכבר מצאנו ביעקב שעשה זה כי לאה היתה שנואה ורחל אהובה ונטל הבכורה מן ראובן ונתנה ליוסף כמו שהתבאר בספר בראשית אלא שזה היה על פי הגבורה ולא היה זה בקנינים שהיה מחזיק בהם יעקב אך בראוי להיות לזרעו ואין הבכור נוטל בראוי כבמוחזק כמו שהתבאר מדברינו:
@1 **התועלת** השלישי הוא במצות והוא מה שהגבילה התורה שתהיה נחלת הבכור פי שנים על נחלת כל אחד מהאחים לפי הוא ראשית אונו ולזאת הסבה מצאנו שיזכה בממלכה הבכור כאמרו ואת הממלכה נתן ליהורם כי הוא הבכור והיה זה כי אהבת האדם היה יותר דבקה לראשון מבניו ממה שהוא אוהב לבניו האחרים:
@1 **התועלת** הרביעי הוא במדות והוא מה שצונו לדין בבן סורר ומורה לפי מה שבארה התורה וכבר בארנו התועלת המגיע מזה כי מי שילבש זה הרועי באילו התכונות ולא יקבל מוסר לא מהוריו ולא מבית דין בעת הילדות שהוא עת המוסר הנה הוא מבואר שהוא יוסיף ברוע תמיד עד שישחית עצמו וזולתו ולזה מהרה התורה בהמתתו:
@1 **התועלת** החמישי הוא במצות והוא מה שצותה התור' לתלות המגדף ועובד עבודה זרה אחר סקילתם להוסיף יראה לאנשים מההליכה בדרכיהם:
@1 **התועלת** הששי הוא במצות והוא מה שצוה לקברם ביום ההוא ושלא להלין נבלתם על עץ כדי שלא יזכר פעולותיהם המגונות ויהיה בזה חלול השם:
@1 **התועלת** השביעי הוא במצו' והו' מה שהזהיר מהתעלם מאבדת אחיו כאשר ימצאה ומה שצוה להשי' אותה לו והנה התועלת בזאת המצוה בתיקון הקבוץ המדיני מבואר עם שיש בזה הקנאת מנהג אל היושר והחנינה:
@1 **התועלת** השמיני הוא במצו' והוא מה שהזהיר מהתעלם כשיראה איש חמור אחיו או שורו נופלים בדרך תחת משאו ומה שצוה לטעון עמו המשא על הבהמות והנה התועלת באלו המצות מבואר בתיקון הקבוץ המדיני כמו העניין כמצות הקודמות:
@1 **התועלת** התשיעי הוא במצות והוא מה שהזהיר מהיות כלי גבר על אשה וכלי אשה על איש והנה התועלת באלו האזהרות מבואר לפי שהדברים ההם אם יעשו הנה הם מסלול ודרך אל שתמלא הארץ זמה כמו שביארנו אצל באורינו דברי זה הפסוק:
@20 **כי יקרא קן צפור לפניך וגו' עד אשר תכסה בה.**
@20 **ואולם התועלות המגיעות ממנה הם ה':**
@20 **התועלת** הראשון הוא במצות והוא מה שצונו לשלוח אם קן הצפור אם לקחנוה על הבנים ומה שהזהירנו מלקחת אותה על הבנים וכבר בארנו התועלת המגיע מזאת המצוה אצל באורנו בה:
@20 **התועלת** השני הוא במצות והוא מה שצונו להסיר המכשולות מהבית כדי שלא נשים דמים בביתינו הפך מה שהיתה הכונה בו בבניית הבית:
@20 **התועלת** השלישי הוא במצו' והוא מה שהזהיר מזריעת הכרם כלאים וכבר בארנו התועלת המגיע ממצות כלאים בפרשת קדושים תהיו ומהמקום ההוא יתבאר זה ואמנם החמירה התורה יותר בכלאי הכרם משאר כלאי זרעים לפי שהגפן היא חזקת היניקה ויקרה מזה שתמשך אליה המזון ששנה אותו הזרע האחר למשוך אותו אליו ויקרה מזה מה שידמה להרכבת אילן באילן שלוקחן האחד טבע מהאחר והפרי הוא מתיחס בצד מה לכל אחד משניהם וכמו מורכב מטבע שניהם ולפי מה שיקרה בו זה תפסק ההולדה בו כמו שהתבאר בטבעיות מנעה אותו התורה של נשתמש בטוב אשר האציל השם יתעלה בצמחים שיהיה להם כח לשנות המזון שיזונו ממנו להשחתתם והנה בענין מצות הכלאים תועלת משותף והוא כי זה יישירנו אל ההבדל שיש בין המינים וזה יעמידנו על מציאות הצורות שאין דרך מבלעדיו לקנות שום שלמות אנושי. וכבר תעמוד על זה ממה שחשבו קצת הקודמים שיהיו כל הדברים דבר אחד ואלו חשבו שלא תהיה שם צורה והכחישו מפני זה מציאו' האלוה ית' וכל חכמת הנמצאות ובכלל אם לא נעמוד על ההבדל אשר בין הדברים לא נקנה שום חכמה וזה ממה שאינו צריך אל ביאור למעיין בזה הספר. והנה זה התועלת כולל לכל מיני הכלאים הנזכרים פה כמו החרישה בשור וחמור ולבישת בגד כלאים:
@20 **התועלת** הרביעי הוא במצות והוא מה שהזהירנו שלא נשתף במלאכה אחת בהמה טהורה וטמאה והנה התועלת בזאת המצוה מבואר ממה שקדם ובה עוד תועלת להעמידנו על שההבדל שהבדילה התורה בין הבהמה הטהורה לטמא' הוא הבדל בעצמו' הדבר לא במקרה ובדבר שאין לו רושם במהותם. וכבר בארנו שהענין הוא כן בפרשת ויהי בים השמיני:
@20 **התועלת** החמישי הוא במצות והוא מה שהזהירתנו התורה מלבישת בגד שהוא צמר ופשתים יחדיו וכבר בארנו מה שיש מהתועלת בזאת המצוה בפרשת קדושים תהיו ובזה המקום כמו שקדם והנה סמך אליה מצות ציצית להעיר איך נסתעפו מן האחד דברים מתחלפים בצורה ובמהות כמו שביארנו ממצות ציצית בסוף פרשת שלח לך:
@20 **כי יקח איש אשה וגו'. עד לא תשיך לאחיך וגו'.**
@20 **ואלו התועלות המגיעות ממנה הם י"ג:**
@20 **התועלת** הראשון הוא במצות והוא מה שצוה מענין מוציא שם רע מה עונש לו או לה דבריו אמתיים וכבר ביארנו התועלת בזאת המצוה אצל ביאורנו זה:
@20 **התועלת** השני הוא במצות והוא מה שצוה מהעונש לשוכב עם אשה בעולת בעל ולזה והנה התועלת בזאת המצוה מבואר:
@20 **התועלת** השלישי הוא במצו' והוא מה שצוה מדין הבא על נערה מאורשה ברצון או באונס והתועלת בזא' המצוה מבואר ולמדנו ממנה שהאנוס פטור מכלום כשהרודף אחר נערה מאורסה יש רושת לרואה להושיע לה ואפילו בנפשו של רודף אם לא יוכל בצד אחר וכן הענין ברודף אח' שאר העריות או כרודף אחר חבירו להרגו ואולי סמיכות אלו הפרשיות הוא להעיר שהמוציא שם רע מפני שהולך אחר עיניו ולזה אינו חפץ באשתו ושונא אותה ומוציא עליה שם רע הנה סופו לפתות אשת איש אשר יקל בה הפתוי יותר והיא בעולה ולא יספיק לו זה אבל יפתה נערה בתולה מאורסה ואף על פי שיקשה בה הפתוי הנה לתגבורת יצרו עליו ישתדל בזה שלא יספיק לו זה אבל יאנוס אותה גם כן:
@20 **התועלת** הרביעי הוא במצות והוא מה שצוה מדין אונס נערה בתולה והתועלת בזאת המצוה כבר ביארנוהו עם ביאורינו דברי זאת הפרשה:
@20 **התועלת** החמישי הוא במצות והוא מה שצוה שלא יגלה איש ערות אביו. וביאר עם זה שאשת אביו לא יוכל איש קחת אות' לו לאשה אבל יקח הוא אנוסת אביו ומפותת אביו וזה הוא מבואר ממה שזכרנו למעלה בשרשים הכוללים וכבר ביארנו תועלת המגיע מזאת האזהרה אצל ביאורנו דבריה ולפי שכבר זכר דבר אונס נערה בתולה המאורסה השלים דיני אונס נערה בתולה ולזה זכר דיני אונס נערה בולה אשר לא אורשה והמשיך אליה האזהרה שלא יקח איש את אשת אביו לבאר כי הבן יוכל השקיט תלונת האשה אם תחפוץ בו כמו שביארנו:
@20 **התועלת** השישי הוא במצות. והוא שהזהיר מלישא בת ישראל מי שנשחת בו אי זה שיהיה מבלי ההולדה והנה התועלת בזאת המצוה הוא משני פנים האחד כי מפני שזה ענינו הוא בלתי מוליד אם הוליד הולדה חסרה הנה היה מן הראוי שלא יקח אשה ישראלית כי בעילת הבלתי מוליד הוא כמו בעילת זנות שלא יכון בה הולדה רק הנאה לבד והמוליד הולדה חסרה הוא בלתי ראוי גם כן לישראלית כי ידמה שיהיה הזווג ההוא לכונת הבעילה לבד אחר שלא יושג בה בפריה ורביה כי אם תועלת פחו' והנה התועלת השני הוא היותר שלם הוא שאם יהיה מורת לקח ישראלית היו האנשים השטופים בזמה כשישחקו באשה משחיתים כלי הולדה לאיש אחד ויתנוה לו לאשה ואחר זה יתעוללו בה והוא לא יחוש והיא לא תבוש אם תתעבר לחשבה שהיא מחזקה שיש לה בעל:
@20 **התועלת** השביעי הוא במצות והוא מה שהזהיר שלא יבא ממזר בקהל הש' עד עולם והנה התועלת בזאת המצוה לפי שאם יולד ממנו זרע יהיה נבדל מהזרוג בישראל לנצח ויהיה זה סבה גם כן אל שיהיה חטאתם בלתי נשכח וזה ממה שיוסיף זירוז על ההשמר מגלוי הערוה:
@20 **התועלת** השמיני הוא במצות והוא מה שהזהיר מבא עמוני ומואבי בקהל ה' אף אם נתגיירו עד עולם והמשיכה זאת האזהרה לאזהרת ביאת הממזר בקהל לפי שעמון ומואב היו ללוט מבנותיו ולזה היו ממזרים והנה הממזר לא ינקה ממום בכל עת. ולפי דרכנו למדנו מזה שהממזר הוא מהעריות אשר לא יתכן שיהיה לאדם אישות בהם ואפילו בברה כמו הבת שאין לאדם אישות כלל בה ואם קדשה אינה אשת איש וכן הענין בשאר העריות הדומה לה ואולם אשר יהיה לאדם בהם אישות כמו אלמנה לכהן גדול והדומים לה הנה לא יהיה מהם ממזר כי לא יהיה ממזר הנולד לאדם מאשתו והנה זכרה התורה בהרחקת עמוני ומואבי סבה תכלול הזכרים ולזה אין זאת האזהרה נוהגת כי אם בזכרים והוא מה שזכר מדוע לבבם שלא קדמו לישראל בלחם ובמים בצאתם ממצרים ושכבר השתדל למשחית ישראל ולזה הזהיר שאם נלחם עמהם לא נקרא להם בשלום:
@20 **התועלת** התשיעי הוא במצות והוא מה שהזהיר מלהרחיק אדומי ומצרי לעולם אך הותר להם לבא בקהל הדור שלישי שיולדו להם לפי שתלה הענין בלידה צריך שתהיה האם שניה בדרך שיהיה הנולד לה שלישי והנה הרחיקה התורה המצרי והאדומי יותר מהאומות הנשארות לרוע מנהגם כמו שזכר בתורה כמעשה ארץ מצרים ועוד שאדום לא הניח את ישראל עבור בגבולו ולולי שהיה אדום אחינו והיינו גרים בארץ מצרים היינו מרחקים אותם עד עולם כמו הענין בעמון ובמואב:
@20 **התועלת** העשירי הוא במצות והוא מה שצונו להשמר במחנה מכל דבר רע בדרך שתדבק ההשגחה האלהית בנו ולהרחיק הרואה קרי מהמחנה כדי שישמור כל אדם מהרהורים הרעים המביאים לידי ראיית קרי כי ישיגהו מזה בושת נפלא גם הרחיק הצואה מהמחנה הקדוש בדרך שלא תראה ערות דבר במקום הנכבד ההוא שהשם יתעלה מתהלך בקרבו ומפני זה צוה לכסות הצואה לנקיות ולכבוד השם יתעלה ולהסיר העפוש משם:
@20 **התועלת** האחת עשרה הוא במצות והוא להודיע חבת ישוב ארץ ישראל כי גם העבד הכנעני הבורח שם להמלט מדוניו הישראלי הדר בחוצה לארץ נצטווינו שלא נסגירהו אל אדוניו אך ישלחנו חפשי מעצמו ויהיה גר צדק ורצתה התורה ישב עמנו בקרבנו לא בפני עצמו כדי שנישירהו למצות התורה וממה שרצתה התורה בזה יתבאר שאם רצה העבד לברוח מעם אדוניו ומעם השם יתעלה כאלו תאמר שרצה לשוב לדתו ולארצו הנה נסגירהו אל אדוניו כי התנאי הוא שלא ירצה להנצל כי אם מעם אדוניו ושישבת עמנו בקרבנו:
@20 **התועלת** השתים עשרה הוא במות והוא מה שאסר הקדשה מבנות ישראל לבד והקדש גם כן להרחיק הזמה מהעם הקדוש והנה סמך דבר הקדשה למה שזכר מדבר העבד כי השפחה כנענית היא כמו קדשה והתורה לעבד עברי או לעבד כנעני שלא באישות והוא מבואר עוד שהקדשה מהגוים לא הזהירה התורה עליהם כי לא אסרה תורה רק דרך חתנות שנאמר לא תתחתן בם:
@20 **התועלת** השלש עשרה הוא במצות והוא מה שהזהירה תורה מהביא אתנן זונה ומחיר כלב בית ה' אלהיך לעשות ממנו קרבן וכבר זכרנו התועלת המגיע מזאת המצוה אצל ביאורינו בה:
@63 **לא תשיך לאחיך נשך כסף עד כי יהיה ריב בין אנשים:**
@63 **ואולם** למה היו הפרשיות בזה הסדור הנה נאמר בו מה שיראה לנו ונאמר שכבר ידמה סמך ענין הנשך למצוות אתנן זונה כי כמו שהזונה תדמה למשוך אליה ממון האנשים ברצנם ותחשוב שאין לה אשם על זה ואינה יודעת כי בנפשה הוא פני מה שתעשה מהזמה בעבור חמדת הממון כן העניין בנושך שהוא חושב שאין בזה מהנטייה כי אם משיכתו אליו ממון האנשי' ולא ידע כי בנפשו הוא כי בעבור חמדת הממון ימשך לה עד שישוב הלוה עני וימיתהו הוא וביתו ברעב ובצמא ובערום ובחוסר כל ולפי שהנשך ותנן הם כמו נדרים והיה לחושב שיחשוב שהנדרים שידור אדם לתת בזולת שיגיע לה מחיר מה שהוא נותן לה הם הדברים מאסה בהם התורה והרחיקה אותם והיה אפשר שיביא זה אל שיחשוב האדם שאין ראוי שיקיים נדריו לשם יתעלה אחר שלא יקח מהשם יתע' בעבורם מה שהוא תמורתם הזהיר מעבור לקיים הנדרים שהם ליי' והנה סמך לזאת אזהרת הפועלים שלא לשים בכליהם מפירות בעלי הבית כי אולי יחשבו שאינם עול אם ישימו מהם בכליהם שיעור מה שהיה אפשר להם לאכול אחר שכבר הותר להם לאכול מהם שם וזה יביאם לגנוב מהפירות ההם ולשאת לביתם מהם הרבה כי לא יוכלו למשול בתאותם אחר שיפותו לה שלא יקחו מהם יותר מן החוק הרבה עם שכבר ישפטו בעת ועת שכבר אפש' להם שיאכלו ויביאו לביתם בזה הרבה מהפירות של בעל הבית וכן לא יחשבו לעשות אם יבטלו מלאכת בעל הבית בעבור אכילתם פירותיו. ובזה האופן יוכלו לבטל רוב היום ויקחו רוב שכרם בעול והנה סמך לזה מגרש אשתו ומחזיר' לפי שאולי יקח האדם מון מזולתו שחשק באשתו ויפותה מפני הממון לגרשה שתהיה לו לחשבו שאין בזה אש לו ולזה ולא בחושק כי בהיתר יקחיה ולחשבו שהוא לא יפסיד בה דבר כי כבר ישוב לקחתה אחר היותה לאיש ההוא כשיגרשנה ויתנה לו זה כדי שיתרצה הראשון לגרשה בבטחו שכבר תשוב אליו ולזה עשתה התורה כנגד זה הרצון כי בו תמלא הארץ זמה ולא ירגישו שיעשו בזה חטא. והנה סמך לזה הענין לוקח אשה חדשה לשמור האשה מזמה ולזה צוה לו שישמח אשתו אשר לקח כדי שלא תחשוק אחרים לשמור הארץ מזמה ואחר שהשלים מה שסמך מהמצות לעניין הנשך שב להשלים קצת מצוה בעניין ההלואה והזהיר מלקחת למשכון כלי שישתמשו בו בהכנת אוכל נפש כי זה עם שאפשר שיביא למה שהוא נשך וזה יהיה אם ישתמש המלוה בכלים ההם הנה הוא עוד כמו לוקח נפש למשכו בעבור החוב כי זה הכלי יוכן בו בעצמותו המזון שהוא שב חלק מהנזון ולזה סמך לו גונב נפש מבני ישראל ומכרו כי הוא נותן נפש בעד ממון בזה האופן המגונה ששני אלו הדברים נמשך מהם היזק מהאדם לזולתו בנפש במה שלא חשב שהזיק את הנפש וזה בקלוח כלי תיקון מזון מבואר ואולם בגונב נפש לחשבו שהוא לא הזיק לו בעצמו אל לקחו והו' רשו' עצמות תמיד גם אחר המכרו אחר שאינו נתן למכר' ויביא זה לחשו' שאין לו חטא בנפשו כלל. הנה סמך לה עניין הצרעת שאם לא יתנהג האדם בו לפי משפט התורה יגיע לאנשים היזק בנפשם ויחשוב שאין לו אשם בזה וזה יהיה אם יעלים נגעו בצד מן הצדדים באון שלא יוכרח לישב בדד חוץ למחנה ויעמוד בין האנשים ויעפשם ואחר שהשלים אלו המצות הנמשכות לאזהרות לקיחת משכון כלי האוכל נפש שב להשלים קצת מצות אחרות בענין לקיחת המשכון והזהיר המלוה מלבא אל בית הלוה לקחת המשכון על חובו לפי שבזה העניין יכאיב לבו מאד כשיוכרח לתת למשכון מה שיקשה בעיניו להוציאו מביתו ויהיה כמו חובל נפש עם שזה אולי יביא למה שידמה לרבית כי המלוה יאמר שלא יקח כי אם המשכון שיראה שחפץ בו הלווה יותר וזה יביא הלוה אל שיתן שוחד למלוה כדי שיתפייס במשכון האחר וצוה שלא יעכב אצלו מהעני כסות יום ביום וכסות לילה בלילה כי בזה גם כן יהיה כמו חובל נפש כי העני ישאר ערום אין כסות בקרה ויזוק מהקור ולזאת הסבה סמך לו שלא יאחר אדם פרעון שכר שכיר כי הא יחשוב היותו בלתי חוטא בזה אם שרצונו לפרעו ואולי ישחית בזה נפש השכיר ונפש ביתו עם שכבר יחשוב שאין בזה חטא על איחור הפרעון אחר שמנעה התורה לקיחת הרבית על ההלואה מפני איחור פרעונה והנה סמך לזה האזהרה מהמתת בנים על אבות להעיר כי הכובש שכר שכיר מפני שהוא דבה להמית אבות ובנים ברעב בסבת אחור פרעון השכירות הנה ישיבלו השם יתעלה מהעונש מדה כנגד מדה במה שאמר זה על העונש וקרא עיך אל יי' והיה כך חטא ועוד כי מפני שזכר מה שראוי בו לחמלה בזה על השפלים אע"פ שהם עשירים זכר אחר זה מה שראוי בו לחמלה בזה על החטאים וכאילו הזהיר שלא יענשו המחוייבים למות בממונם אך יהיה ממונם ליורשיהם שאם יענשו בממונם יהיה זה סבה שימותו בנים על אבות ואבות על בנים והנ' הוצרך להזהיר על זה מפני מה שמצאנו בעיר הנדחת שהיה ממונם אבד והיו מתים גם כן הבנים על האבות. ולפי שכבר התחיל להזכיר הדינים לחמלה על השפלים והעניים והחטאים שב להזכיר צדדים אחרים מהחמלה על השפלים והעניים והחטאים ולזה הזהיר תחילה מלהטות משפט גר יתום ואפילו הם עשירים מצד שפלותם ולא לקחת משכון בגד אלמנה ואפילו היא עשירה מצד שפלותה ואחר זה צוה לתת קצת מתנות לעניים לחמלה עליהם ואחר זה הזהיר מהוסיף על מספר מכות הלוקה לחמלה עליו אע"פ שהוא חוטא שלא יעבור ענשו החוק הראוי ואחר זה הזהיר מה שהוא לחמלה על הבהמות והוא דומה באופן מה למה שהזהיר מההוספ' על עונש החוטא כי די שנעמיס עליה משא העבודה שהוכן לה בטבע להיות לעבודתנו לא שנמנעה עם זה מהאכילה ממה שהיא עושה במה שימשכנה הטבע לאכול ממנו עם שבזה מהאכזריות מה שלא יעלם ואחר זה שב להשלים הדין במה שהוא לחמלה על החוטא וזה כי מפני שבארה התורה בקצת החטאים שיהיה העונש שימות ערירי עם שהוא ראוי שתהיה מיתת האדם בלא בנים בסבת חטא הנה השגיחה התורה על מי שמת בלא בנים שלא ימחה שמו מישראל כשהיתה לו אשה ולזה רצה שתתיבם לאחיו והנה זה המת אפשר גם כן שיהיה מת על יד ב"ד על חטא שקד' לו והשגיחה בו התור עם זה בזה האופן ואחר שזכרה התורה מה שראוי לחמול על החטאים בארה שלא יחמול עליהם מהמגיע להם העונש הראוי ואע"פ שיש שם סבה לחשוב שהיה ראוי לחמול עליהם וזכר דין המחזקת במבושי איש להציל את אישה מיד מכהו והזהיר מחמול עליה ועם זה דבר לזכור נקם עמלק על מה שעשה כנגדנו אפילו שחשב להציל עצמו בזה מהקללות שקלל יצחק את עשו שיהיה עבד ליעקב כי מפני זה לא היה ראוי לו להשתדל בעשיית זה הרע הנפלא ליש' שדמה בו לכלותם כמו שלא היה ראוי לאשת המוכה להשתדל בהריגת המכה אותו מפני שהכהו על דבר הריב לא להרגו והנה זכר כן שני אלו שתנהג בצדק וביושר במשקלים ובמידות לבאר שכמו שאין ראוי להוסיף עונש יותר מהחק הראוי כן אין ראוי שתגרע מחק העונש דבר ואולם התועלות המגיעות מזאת הפרשה שהגבלנו באורה פה הם שנים ועשרים:
@63 **התועלת** הראשון הוא במצות והוא מה שהזהיר מלקיחת שום רבית על ההלואה שנאמר לא תשיך לאחיך נשך כסף וכבר ביארנו התועלת המגיע מזאת האזהרה במה שקדם:
@63 **התועלת** השני הוא במצות והוא מה שצונו להלוות לנכרי ברבית כשיצטרך לזה שנאמר לנכרי תשיך ופה התועלת בזה הוא שלא לההנות עובדי עבודה זרה להרחיקנו יותר מעבודתה עם שבזה הישירה ליסר הנכרי מעבוד עבודה זהר:
@63 **התועלת** השלישי הוא במצות והוא מה שהזהירתנו מלאחר שלום הנדרים אשר נדרנו ליי' ומה שצותנו לקיים אותם והנה התועלת המגיע בזה הוא לולי זאת האזהרה כבר היה האדם מחר הנדרים לחשבו שאינו מזיק בזה לשם יתעלה כי אין לו הנאה בקרבנות ההם ולא יחסר גם כן מהכהנים דבר ממה שהוא שלהם כי הם לא יזכו בקרבנות כי אם אחר הקרבתם לשם יתעלה ויהיה זה סבה אל שלא יתקיימו הנדרי' וזה יביא למעט האמנה בש' יתע' כמו שזכרנו במה שקדם:
@63 **התועלת** הרביעי הוא במצו' והוא מה שהזהיר הפועלי' מתת לכליהם דבר מפירות הבעלים שהם עושין בהם ואע"פ שהתיר להם לאכול מהם די שבעם כמו שהם מזות תקון אחר ומה שהזהיר הפעלים מלבטל ממלאכת הבעלי' בעבור אכילתם הפירות ההם וזה כולו על צד היושר מחובר עם החמלה שחמלה התורה על הפועלים שלא יוכרחו להמנע מהפירות שהם מתעסקים בהם כי יצר להם אם יראו בעיניהם ומשם לא יאכלו:
@63 **התועלת** החמישי הוא במצות והוא מה שצונו מדיני הגט אשר תותר בו האשה להנשא לכל מי שתרצה והתועלת בזה מבואר כדי שלא יוכרח האדם שיהיה עם אשתו כל ימיו השנואה לו ויהיה זה סבה על שימנע מפריה ורביה אם שיוליד בנים בלתתי הגונים כי לא ישלם להם המוסר מהאב והאם מצד רוע ההסכמה שביניהם עם שתמיד תהיה הקטטה בבית:
@63 **התועלת** השישי הוא במצות והוא מה שהזהיר הבעל מלהחזיר גרושתו אחר שהוטמא' לו והתועלת בזה הוא הרחקת הזימה כמו שבארנו ולזאת הסבה גם כן צוה שיהיה החתן נקי לביתו שנה אחת לא יצא לצבא ולא יעבור עליו לכל דבר כמו שבארנו במה שקדם:
@63 **התועלת** השביעי הוא במצו' והוא מה שהזהיר מלקחת למשכון כלי שעושין בו אוכל נפש והנה התועלת בזאת האזהרה מבואר בתורה ועוד הוא מבואר מדברינו במה שקדם:
@63 **התועלת** השמיני הוא במצות והוא מה שהוסיף כאן מהבאור בדיני גונב נפש שיתחייב מיתה על מה שזכר מזה בפרשת ואלה המפשטים והנה התועלת בה מבואר בנפשו כי בזה יהיה מקלקול הקבוץ המדיני מה שלא יעלם עם שיקרה מזה לעבור על דבר העריות ולא ירגיש בזה הנגנב ר"ל שכבר אפשר שיקרה אחותו או אמו או אחת מהעריות שהם קרובותיו ולא ישער בזה:
@63 **התועלת** התשיעי הוא במצות והוא מה שהזהיר מלנטות ב"ד בדיני הצרעת מדרכי התורה כי כבר יקרה הרבה מההפסד בזה בקבוץ המדיני כמו ושזכרנו במה שקדם וכאלו הזהיר מלזון הרע במה שנזכר מה שעשה השם יתעלה למרים כמו שביארנו:
@63 **התועלת** העשירי הוא במצות והוא מה שהזהיר מלהכניס בבית הלוה לקחת המשכון על חובו וכבר נתבאר התועלת המגיע מזה מדברינו במה שקדם:
@63 **התועלת** האחת עשרה הוא במצות והוא מה שהזהיר מלעכב המלוה משכון העני אצלו בעת שהוא צריך לו והנה התועלת בזאת המצוה מבואר:
@63 **התועלת** השתים עשרה הוא במצות והוא מה שהזהיר מלאחר פרעון שכירות השכיר וכ"ש כשהיה עני כי אז יהיה החטא יותר עצום ולזה צוה לתתו ביומו אם היה שכיר לילה ובלילו אם היה שכיר יום:
@63 **התועלת** השלש עשרה הוא במצות והוא מה שהזהיר מענוש למות האבות על הבנים והבנים על האבות אך איש בחטאו ומזה נתבאר עוד כמו שבארנו שממון המומתין הוא ליורשיהם והנה התועלת בזאת האזהרה מבואר מצד היושר שהוא ראוי במשפט:
@63 **התועלת** הארבע עשרה הוא במצות והוא מה שהזהיר מהטות משפט השפלים כי אין בשער עשרתם והוא אמרו ללא תטה משפט גר יתום והנה התועלת בזה הוא להמשך אל היושר ולהרחיק ההמם:
@63 **התועלת** החמש עשרה הוא במצות והוא מה שהזהיר מלקיחת למשכון בגד אלמנה וכבר נתבאר התועלת בזאת המצוה ממה שקדם.
@63 **התועלת** השש עשרה הוא במצות והוא מה שהזהיר מלקחת שכחת הקציר ופירות האילן והכרם ומה שצוה שיהיו לעניים והנה התועלת בזאת המצוה מבואר לחונן העניים ולחיותם:
@63 **התועלת** השבע עשרה הוא במצוות והוא מה שצוה לחלקות החוטא כדי רשעתו במספר עד מ' מכות ומה שהזהיר מלהוסיף על זה המספר והנה התועלת בזאת המצוה מבוא' ליסר החוטאי' לפי מה שראוי להם לא יותר:
@63 **התועלת** הי"ח הוא במצות והוא מה שהזהיר מלמנוע הבהמה מאכילת מה שהוא עושה בו וכבר ביארנו התועלת המגיע מזה במה שקדם:
@63 **התועלת** הי"ט הוא במצו' והוא מה שצונו ליבם אשת האח שמת בלא בנים כדי שלא ימחה שמו מישר' ומה שצוה מענין החליצה אם לא חפץ ליבם מה שיש בו מהבשת והזרות ומה שיביאהו להסכים ליבם:
@63 **התועלת** העשרים הוא במצות והוא מה שצוה להציל הנרדף אפילו בנפשו של רודף מבלתי חמלה על הרודף כאמרו לא תחוס עינך עליו. והנה התועלת בזאת המצוה מבואר:
@63 **התועלת** האחת ועשרים הוא במצות והוא מה שהזהיר מהיות לנו אבן ואבן גדולה וקטנה לשקול בו איפה ואיפה גדולה וקטנה למדוד בה ומה שצוה שיהיה לנו אבן שלמה ודק ואיפה שלמה וצדק והנה התועלת בזה להמשך אל היושר ולהרחיק העול:
@63 **התועלת** השתים ועשרים הוא במצות והוא מה שצונו לזכור מה שעשה לנו עמלק ומה שהזהיר שלא נשכח זה ולמחות זכרו אחרי שיניח השם יתע' מכל אויביו מסביב לישראל והנה התועלת בזאת המצוה מבואר ממה שזכרנו:
